import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  PRINCIPAL = 'PRINCIPAL',
  TEACHER = 'TEACHER',
  STUDENT = 'STUDENT',
  PARENT = 'PARENT'
}

export enum CBCGrade {
  EE = 'EE', // Exceeding Expectations
  ME = 'ME', // Meeting Expectations
  AE = 'AE', // Approaching Expectations
  BE = 'BE'  // Below Expectations
}

export interface Student {
  id: string;
  admissionNumber: string;
  firstName: string;
  lastName: string;
  class: string;
  stream: string;
  gender: 'Male' | 'Female';
  dob: string;
  guardianPhone: string;
  feeBalance: number;
}

export interface ExamResult {
  subject: string;
  score: number;
  grade: string;
  competency: CBCGrade;
  remarks: string;
}

export interface Payment {
  id: string;
  amount: number;
  date: string;
  method: 'M-PESA' | 'CASH' | 'BANK';
  transactionId: string;
  description: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
}

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { StudentManagement } from './components/StudentManagement';
import { FinanceModule } from './components/FinanceModule';
import { AttendanceModule } from './components/AttendanceModule';
import { TranscriptModule } from './components/TranscriptModule';
import { UserRole, User } from './types';

// Mock Auth State
const INITIAL_USER: User = {
  id: 'u1',
  name: 'Principal Maina',
  email: 'maina@elimusmart.co.ke',
  role: UserRole.PRINCIPAL,
  avatar: 'https://picsum.photos/200/200?random=1'
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(INITIAL_USER);
  const [currentTab, setCurrentTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-blue-600 p-4">
        <div className="bg-white rounded-xl shadow-2xl p-8 max-w-md w-full">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-blue-800">ElimuSmart</h1>
            <p className="text-gray-500">Kenyan CBC & JSS Management</p>
          </div>
          <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); setUser(INITIAL_USER); }}>
            <div>
              <label className="block text-sm font-medium mb-1">Email / Phone</label>
              <input type="text" className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500" placeholder="admin@school.ac.ke" />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Password</label>
              <input type="password" className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500" placeholder="••••••••" />
            </div>
            <button className="w-full bg-blue-600 text-white font-bold py-3 rounded-lg hover:bg-blue-700 transition">
              Sign In
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      currentTab={currentTab} 
      setCurrentTab={setCurrentTab}
      isSidebarOpen={isSidebarOpen}
      setIsSidebarOpen={setIsSidebarOpen}
      logout={() => setUser(null)}
    >
      <main className="p-4 md:p-8">
        {currentTab === 'dashboard' && <Dashboard user={user} />}
        {currentTab === 'students' && <StudentManagement />}
        {currentTab === 'finance' && <FinanceModule />}
        {currentTab === 'attendance' && <AttendanceModule />}
        {currentTab === 'reports' && <TranscriptModule />}
      </main>
    </Layout>
  );
};

export default App;

import React from 'react';
