            <h3 className="text-lg font-bold flex items-center gap-2">
              <Smartphone className="w-5 h-5 text-green-600" />
              Direct M-Pesa Payment
            </h3>

            {step === 'form' && (
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Student ADM Number</label>
                  <input type="text" className="w-full p-2 border rounded-lg" placeholder="e.g. ADM001" />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Phone Number (M-Pesa)</label>
                  <input type="text" className="w-full p-2 border rounded-lg" placeholder="07XXXXXXXX" />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Amount (KES)</label>
                  <input type="number" className="w-full p-2 border rounded-lg" placeholder="5000" />
                </div>
                <button 
                  onClick={handleMpesaPush}
                  className="w-full bg-green-600 text-white font-bold py-3 rounded-lg hover:bg-green-700 transition"
                >
                  Send STK Push
                </button>
              </div>
            )}

            {step === 'processing' && (
              <div className="text-center py-8 space-y-4">
                <div className="animate-spin w-12 h-12 border-4 border-green-600 border-t-transparent rounded-full mx-auto"></div>
                <p className="font-medium">Requesting M-Pesa STK Push...</p>
