              <button className="text-sm text-blue-600 font-medium hover:underline">View All</button>
            </div>
            <div className="divide-y">
              {[
                { name: 'Kamau Njoroge', ref: 'QRA92KJH2', amount: 15000, date: 'Today, 10:45 AM', status: 'Confirmed' },
                { name: 'Amara Kiprono', ref: 'QRZ11S922', amount: 5000, date: 'Yesterday, 2:30 PM', status: 'Confirmed' },
