export const TranscriptModule: React.FC = () => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [aiRemarks, setAiRemarks] = useState<string>('');
  const printRef = useRef<HTMLDivElement>(null);

  const generateAIRemarks = async () => {
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const prompt = `Based on these results for a Grade 7 Kenyan student named ${MOCK_TRANSCRIPT_STUDENT.firstName}: 
        ${MOCK_RESULTS.map(r => `${r.subject}: ${r.score}% (${r.competency})`).join(', ')}.
        Provide a concise, encouraging, professional summary for a report card in 50 words. Focus on strengths and one area for improvement.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      setAiRemarks(response.text || 'Performance is consistent and commendable.');
    } catch (error) {
      console.error(error);
      setAiRemarks('Student shows remarkable growth and discipline in all learning areas.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 no-print">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Academic Transcripts</h1>
          <p className="text-gray-500">Generate, download, and print official CBC-compliant transcripts.</p>
        </div>
        <div className="flex space-x-2">
          <button 
            onClick={generateAIRemarks}
            disabled={isGenerating}
            className="flex items-center space-x-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 disabled:opacity-50"
          >
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />}
            <span>Generate AI Remarks</span>
          </button>
          <button 
            onClick={handlePrint}
            className="flex items-center space-x-2 border border-gray-300 px-4 py-2 rounded-lg hover:bg-gray-100"
          >
            <Printer className="w-4 h-4" />
            <span>Print Transcript</span>
          </button>
        </div>
      </div>

      {/* Transcript Preview Card */}
      <div className="bg-white shadow-xl rounded-xl border max-w-4xl mx-auto overflow-hidden p-8 md:p-12" id="printable-transcript">
        {/* School Header */}
        <div className="flex justify-between items-start border-b-4 border-blue-600 pb-6 mb-8">
