            </div>
          </div>
          <div className="text-right">
            <div className="text-sm font-bold text-gray-400 uppercase tracking-widest">Official Transcript</div>
            <div className="text-xl font-bold text-blue-600 mt-1">2024 Academic Year</div>
          </div>
        </div>

        {/* Student Bio Info */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8 bg-blue-50 p-6 rounded-xl border border-blue-100">
          <div>
            <div className="text-xs font-bold text-blue-800 uppercase">Student Name</div>
