/**
 * Helper to determine current Kenyan academic term based on current month.
 * Term 1: Jan - Apr (0-3)
 * Term 2: May - Aug (4-7)
 * Term 3: Sept - Dec (8-11)
 */
const getCurrentAcademicTerm = () => {
  const month = new Date().getMonth();
  if (month <= 3) return 1;
  if (month <= 7) return 2;
  return 3;
};

const getCurrentAcademicYear = () => new Date().getFullYear();

