import React, { useState, useEffect } from 'react';
import { 
  BookOpen, 
  Plus, 
  Search, 
  ChevronRight, 
  Save, 
  Wand2, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Filter,
  ArrowLeft
} from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { Exam, MarkEntry, CBCGrade } from '../types';
import { schoolService } from '../services/schoolService';
import { Language, translations } from '../services/localizationService';

export const AcademicsModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [view, setView] = useState<'exams' | 'mark-entry'>('exams');
  const [exams, setExams] = useState<Exam[]>([]);
  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [selectedSubject, setSelectedSubject] = useState('Mathematics');
  const [selectedClass, setSelectedClass] = useState('Grade 7 Oak');
  const [marks, setMarks] = useState<MarkEntry[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isGeneratingRemarks, setIsGeneratingRemarks] = useState<string | null>(null);

  useEffect(() => {
    schoolService.getExams().then(setExams);
  }, []);

  const handleOpenMarkEntry = async (exam: Exam) => {
    setSelectedExam(exam);
    const entries = await schoolService.getMarkEntries(exam.id, selectedSubject, selectedClass);
    setMarks(entries);
    setView('mark-entry');
  };

  const handleScoreChange = (studentId: string, scoreStr: string) => {
    const score = parseInt(scoreStr) || 0;
    setMarks(prev => prev.map(m => 
      m.studentId === studentId 
        ? { ...m, score, competency: schoolService.calculateCBCGrade(score) } 
        : m
    ));
  };

  const handleRemarkChange = (studentId: string, remarks: string) => {
    setMarks(prev => prev.map(m => m.studentId === studentId ? { ...m, remarks } : m));
  };

  const generateAIRemark = async (student: MarkEntry) => {
    if (!process.env.API_KEY) {
      handleRemarkChange(student.studentId, `${student.studentName} shows ${student.competency} in ${selectedSubject}. Keep it up!`);
      return;
    }

    setIsGeneratingRemarks(student.studentId);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Write a one-sentence professional teacher remark for a student named ${student.studentName} who scored ${student.score}% (CBC level: ${student.competency}) in ${selectedSubject}. Make it encouraging and specific to the grade.`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      handleRemarkChange(student.studentId, response.text || '');
    } catch (error) {
      console.error(error);
      handleRemarkChange(student.studentId, 'Commendable performance.');
    } finally {
      setIsGeneratingRemarks(null);
    }
  };

  const saveMarks = async () => {
    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1500));
    setIsSaving(false);
    alert('Marks saved successfully and synced with report cards.');
    setView('exams');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Academics & Grading</h1>
          <p className="text-gray-500">Manage exams, enter marks, and assess CBC competencies.</p>
        </div>
        {view === 'exams' && (
          <button className="flex items-center space-x-2 bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 font-bold transition">
            <Plus className="w-5 h-5" />
            <span>Create New Exam</span>
          </button>
        )}
      </div>

      {view === 'exams' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {exams.map(exam => (
            <div key={exam.id} className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition group">
              <div className="flex justify-between items-start mb-4">
                <div className="p-3 bg-blue-50 text-blue-600 rounded-lg">
                  <BookOpen className="w-6 h-6" />
                </div>
                <span className="px-3 py-1 bg-gray-100 rounded-full text-[10px] font-black uppercase tracking-widest text-gray-500">
                  {exam.type}
                </span>
              </div>
              <h3 className="text-xl font-bold text-gray-800 mb-1">{exam.title}</h3>
              <p className="text-sm text-gray-500 mb-6">Term {exam.term}, {exam.year} • Date: {exam.date}</p>

              <button 
                onClick={() => handleOpenMarkEntry(exam)}
                className="w-full flex items-center justify-center space-x-2 py-3 bg-gray-50 text-blue-600 rounded-lg font-bold group-hover:bg-blue-600 group-hover:text-white transition"
              >
                <span>Enter Marks</span>
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
      ) : (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-4 rounded-xl border flex flex-wrap items-center justify-between gap-4">
            <div className="flex items-center space-x-4">
              <button onClick={() => setView('exams')} className="p-2 hover:bg-gray-100 rounded-full">
                <ArrowLeft className="w-5 h-5" />
              </button>
              <div>
                <h3 className="font-bold text-lg">{selectedExam?.title}</h3>
                <p className="text-xs text-gray-500 uppercase font-black">{selectedClass} • {selectedSubject}</p>
              </div>
            </div>

            <div className="flex flex-wrap gap-2">
              <select 
                value={selectedSubject} 
                onChange={e => setSelectedSubject(e.target.value)}
                className="p-2 border rounded-lg text-sm bg-gray-50 font-bold"
              >
                <option>Mathematics</option>
                <option>English Language</option>
                <option>Kiswahili</option>
                <option>Integrated Science</option>
              </select>
              <button 
                onClick={saveMarks}
                disabled={isSaving}
                className="flex items-center space-x-2 bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 font-bold disabled:opacity-50"
              >
                {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                <span>Save All Marks</span>
              </button>
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-gray-50 border-b text-[11px] font-black uppercase text-gray-400">
                    <th className="px-6 py-4">Student</th>
                    <th className="px-6 py-4 text-center">Score (%)</th>
                    <th className="px-6 py-4 text-center">CBC Level</th>
                    <th className="px-6 py-4">Teacher Remarks (AI Assisted)</th>
                    <th className="px-6 py-4 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y text-sm">
                  {marks.map((entry) => (
                    <tr key={entry.studentId} className="hover:bg-gray-50/50">
                      <td className="px-6 py-4">
                        <div className="font-bold text-gray-800">{entry.studentName}</div>
                        <div className="text-[10px] font-mono text-gray-400">{entry.admissionNumber}</div>
                      </td>
                      <td className="px-6 py-4 w-32">
                        <input 
                          type="number" 
                          max="100" 
                          min="0"
                          value={entry.score}
                          onChange={e => handleScoreChange(entry.studentId, e.target.value)}
                          className="w-full p-2 border rounded-lg text-center font-bold focus:ring-2 focus:ring-blue-500"
                        />
                      </td>
                      <td className="px-6 py-4 text-center">
                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${
                          entry.competency === CBCGrade.EE ? 'bg-green-100 text-green-700' :
                          entry.competency === CBCGrade.ME ? 'bg-blue-100 text-blue-700' :
                          entry.competency === CBCGrade.AE ? 'bg-amber-100 text-amber-700' :
                          'bg-red-100 text-red-700'
                        }`}>
                          {entry.competency}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center space-x-2">
                          <input 
                            type="text"
                            placeholder="Type a remark..."
                            value={entry.remarks}
                            onChange={e => handleRemarkChange(entry.studentId, e.target.value)}
                            className="flex-1 p-2 border-none bg-transparent focus:ring-0 italic text-gray-600 placeholder:text-gray-300"
                          />
                          <button 
                            onClick={() => generateAIRemark(entry)}
                            className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition"
                            title="Generate with AI"
                          >
                            {isGeneratingRemarks === entry.studentId ? <Loader2 className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />}
                          </button>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="text-green-600">
                          <CheckCircle2 className="w-5 h-5 ml-auto" />
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 no-print">
             <div className="bg-blue-50 p-6 rounded-xl border border-blue-100 flex items-start space-x-4">
                <div className="p-3 bg-blue-600 text-white rounded-full">
                  <CheckCircle2 className="w-6 h-6" />
                </div>
                <div>
                  <h4 className="font-bold text-blue-900">Grading System</h4>
                  <p className="text-sm text-blue-700">CBC grading is automatically mapped: EE (80-100), ME (60-79), AE (40-59), BE (0-39). These sync directly to report cards.</p>
                </div>
             </div>
             <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100 flex items-start space-x-4">
                <div className="p-3 bg-indigo-600 text-white rounded-full">
                  <Wand2 className="w-6 h-6" />
                </div>
                <div>
                  <h4 className="font-bold text-indigo-900">AI Teacher Remarks</h4>
                  <p className="text-sm text-indigo-700">Use the spark icon to generate professional, encouraging remarks based on the student's score and competency level.</p>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

