                    </div>
                  </div>
                </div>
              )}

              <div className="pt-8 border-t flex justify-end">
                <button 
                  type="submit"
                  disabled={isSaving}
                  className="flex items-center space-x-2 bg-blue-600 text-white px-8 py-3 rounded-lg hover:bg-blue-700 font-bold transition disabled:opacity-50 shadow-lg"
                >
                  {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                  <span>Save Changes</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

