  id: '1',
  admissionNumber: 'ADM001',
  firstName: 'Kamau',
  lastName: 'Njoroge',
  class: 'Grade 7',
  stream: 'Oak',
  gender: 'Male',
  dob: '2011-04-12',
  guardianPhone: '0712345678',
  guardianName: 'Sarah Njoroge',
  feeBalance: 12500
};

export const FinanceModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [isProcessing, setIsProcessing] = useState(false);
  const [step, setStep] = useState<'identify' | 'details' | 'review' | 'success'>('identify');
  const [paymentMode, setPaymentMode] = useState<'mpesa' | 'cash' | 'bank'>('mpesa');
  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'reconciliation'>('payments');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [studentSearch, setStudentSearch] = useState('');

  // Payment Form State
  const [admSearch, setAdmSearch] = useState('');
  const [targetedLearner, setTargetedLearner] = useState<Student | null>(null);
  const [amount, setAmount] = useState('');
  const [transactionId, setTransactionId] = useState('');

  const handleIdentifyLearner = (customAdm?: string) => {
    const adm = customAdm || admSearch;
    if (!adm) return;
    setIsProcessing(true);
    setTimeout(() => {
      setTargetedLearner({ ...MOCK_STUDENT_RESULT, admissionNumber: adm });
      setStep('details');
      setIsProcessing(false);
      setActiveTab('payments');
    }, 600);
  };

  const handlePostPayment = () => {
    setIsProcessing(true);
    setTimeout(() => {
      setStep('success');
      setIsProcessing(false);
    }, 2000);
  };

  const resetForm = () => {
    setStep('identify');
    setTargetedLearner(null);
    setAdmSearch('');
    setAmount('');
    setTransactionId('');
  };

  const classSummaryData = useMemo(() => KENYAN_CLASSES.map(cls => ({
    name: cls,
    expected: 450000,
    collected: Math.floor(Math.random() * 400000),
    students: 40 + Math.floor(Math.random() * 10)
  })), []);

