  const filteredBulkStudents = MOCK_BULK_STUDENTS.filter(s => 
    s.class === filterClass && (filterStream === 'All' || s.stream === filterStream)
  );

  const exportToCSV = (data: any[], filename: string) => {
    if (!data.length) return;
    const headers = Object.keys(data[0]);
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(header => JSON.stringify(row[header])).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `${filename}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleBulkDownload = async () => {
    if (filteredBulkStudents.length === 0) return;
    setIsBulkGenerating(true);

    const element = document.getElementById('bulk-transcripts-container');
    const filename = `Bulk_Reports_${filterClass.replace(' ', '_')}_${new Date().toISOString().split('T')[0]}.pdf`;

    const opt = {
      margin: 0,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 1.5, useCORS: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: 'avoid-all', after: '.bulk-page' }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error(error);
      alert('Bulk generation failed. Try smaller batch.');
    } finally {
      setIsBulkGenerating(false);
