                    onChange={(e) => setSendSMS(e.target.checked)} 
                  />
                  <div className={`absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform duration-200 ${sendSMS ? 'translate-x-6' : 'translate-x-0'}`}></div>
