                                  <td className="px-8 py-6 text-gray-600 font-bold">{cls.students} Learners</td>
                                  <td className="px-8 py-6 font-black">KES {cls.expected.toLocaleString()}</td>
                                  <td className="px-8 py-6 font-black text-green-600">KES {cls.collected.toLocaleString()}</td>
                                  <td className="px-8 py-6 font-black text-red-600">KES {(cls.expected - cls.collected).toLocaleString()}</td>
                                  <td className="px-8 py-6">
                                     <div className="flex items-center gap-2">
                                        <div className="w-full bg-gray-100 rounded-full h-1.5 min-w-[60px]">
                                           <div className={`h-full rounded-full ${percent > 75 ? 'bg-green-500' : 'bg-blue-500'}`} style={{ width: `${percent}%` }} />
                                        </div>
                                        <span className="font-black text-[9px]">{percent}%</span>
                                     </div>
                                  </td>
                               </tr>
                            );
                         })}
                      </tbody>
                   </table>
                 ) : (
                   <table className="w-full text-left">
                      <thead>
                         <tr className="bg-gray-100 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                            <th className="px-8 py-5">ADM</th>
                            <th className="px-8 py-5">Student Name</th>
                            <th className="px-8 py-5">Total</th>
                            <th className="px-8 py-5">Paid</th>
                            <th className="px-8 py-5">Balance</th>
                            <th className="px-8 py-5 text-right">Actions</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-100">
                         {filteredStudents.map((student, idx) => (
                            <tr key={idx} className="hover:bg-blue-50/30 transition-colors">
                               <td className="px-8 py-5 font-mono font-bold text-gray-600">{student.adm}</td>
                               <td className="px-8 py-5 font-black">{student.name}</td>
                               <td className="px-8 py-5 font-bold text-gray-400">KES {student.total.toLocaleString()}</td>
                               <td className="px-8 py-5 font-black text-green-600">KES {student.paid.toLocaleString()}</td>
                               <td className="px-8 py-5 font-black text-red-600">KES {student.balance.toLocaleString()}</td>
                               <td className="px-8 py-5 text-right">
                                  <div className="flex justify-end gap-2">
                                     <button 
                                      onClick={() => { setLastTx({ name: student.name, adm: student.adm, amount: student.paid, date: 'Cumulative', method: 'SYSTEM', id: 'STM-' + student.adm }); setTimeout(() => generatePDF('receipt-template', `Statement_${student.adm}.pdf`), 100); }}
                                      className="p-2 hover:bg-white rounded-lg border-2 border-transparent hover:border-blue-100 text-blue-600 transition-all"
                                      title="Download Statement"
                                     >
                                        <FileText className="w-4 h-4" />
                                     </button>
                                     <button onClick={() => handleIdentifyLearner(student.adm)} className="bg-blue-50 text-blue-600 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase hover:bg-blue-600 hover:text-white transition-all">Post</button>
                                  </div>
                               </td>
                            </tr>
                         ))}
                      </tbody>
                   </table>
                 )}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'reconciliation' && (
        <div className="space-y-6 text-center py-20 bg-white rounded-3xl border border-gray-100 shadow-sm">
           <PieChart className="w-16 h-16 text-blue-600 mx-auto mb-6" />
           <h3 className="text-2xl font-black uppercase tracking-tight">Automated Reconciliation</h3>
           <p className="text-gray-500 max-w-md mx-auto">Balances are updated automatically via M-Pesa Daraja and Bank API integration. Use this portal for manual bank statements.</p>
           <button className="mt-8 bg-blue-600 text-white font-black uppercase tracking-widest px-8 py-4 rounded-2xl hover:bg-blue-700 transition-all shadow-xl">Import CSV Statement</button>
        </div>
      )}
    </div>
  );
};

