import React, { useState, useEffect } from 'react';
import { 
  FileText, 
  ClipboardCheck, 
  Wallet, 
  ChevronRight, 
  Download, 
  Printer, 
  Search,
  ArrowLeft,
  FileSpreadsheet,
  FileBadge,
  Files,
  Filter,
  Loader2,
  CheckCircle2
} from 'lucide-react';
import { TranscriptModule } from './TranscriptModule';
import { schoolService, AttendanceRecord, FeeTransaction } from '../services/schoolService';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, SCHOOL_STREAMS, Student } from '../types';
// @ts-ignore
import _html2pdf from 'html2pdf.js';

type ReportView = 'selection' | 'transcript' | 'attendance' | 'fees' | 'bulk-transcripts';

const MOCK_BULK_STUDENTS: Student[] = [
  { id: '1', admissionNumber: 'ADM001', firstName: 'Kamau', lastName: 'Njoroge', class: 'Grade 7', stream: 'Oak', gender: 'Male', dob: '2011-04-12', guardianPhone: '0712345678', guardianName: 'Sarah Njoroge', feeBalance: 12500 },
  { id: '2', admissionNumber: 'ADM002', firstName: 'Amara', lastName: 'Kiprono', class: 'Grade 7', stream: 'Palm', gender: 'Female', dob: '2010-08-25', guardianPhone: '0722000111', guardianName: 'David Kiprono', feeBalance: 0 },
  { id: '3', admissionNumber: 'ADM003', firstName: 'Zuri', lastName: 'Achieng', class: 'Grade 7', stream: 'Oak', gender: 'Female', dob: '2011-01-05', guardianPhone: '0788999888', guardianName: 'Grace Achieng', feeBalance: 4500 },
  { id: '4', admissionNumber: 'ADM004', firstName: 'Sifa', lastName: 'Otieno', class: 'Grade 8', stream: 'Acacia', gender: 'Male', dob: '2019-02-15', guardianPhone: '0712121212', guardianName: 'Peter Otieno', feeBalance: 2000 },
];

export const ReportsModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [view, setView] = useState<ReportView>('selection');
  const [attendanceData, setAttendanceData] = useState<AttendanceRecord[]>([]);
  const [feeData, setFeeData] = useState<FeeTransaction[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isBulkGenerating, setIsBulkGenerating] = useState(false);

  // Bulk Filters
  const [filterClass, setFilterClass] = useState('Grade 7');
  const [filterStream, setFilterStream] = useState('All');

  const filteredBulkStudents = MOCK_BULK_STUDENTS.filter(s => 
    s.class === filterClass && (filterStream === 'All' || s.stream === filterStream)
  );

  const exportToCSV = (data: any[], filename: string) => {
    if (!data.length) return;
    const headers = Object.keys(data[0]);
    const csvContent = [
      headers.join(','),
      ...data.map(row => headers.map(header => JSON.stringify(row[header])).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `${filename}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleBulkDownload = async () => {
    if (filteredBulkStudents.length === 0) return;
    setIsBulkGenerating(true);

    const element = document.getElementById('bulk-transcripts-container');
    const filename = `Bulk_Reports_${filterClass.replace(' ', '_')}_${new Date().toISOString().split('T')[0]}.pdf`;

    const opt = {
      margin: 0,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 1.5, useCORS: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: 'avoid-all', after: '.bulk-page' }
    };

    try {
      // Robust constructor check for html2pdf
      const html2pdf = typeof _html2pdf === 'function' ? _html2pdf : (_html2pdf as any).default;
      if (typeof html2pdf !== 'function') throw new Error('html2pdf is not a function');

      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error('Bulk PDF Error:', error);
      alert('Bulk generation failed. Try smaller batch.');
    } finally {
      setIsBulkGenerating(false);
    }
  };

  const loadAttendance = async () => {
    setIsLoading(true);
    const data = await schoolService.getAttendanceHistory('s1');
    setAttendanceData(data);
    setIsLoading(false);
    setView('attendance');
  };

  const loadFees = async () => {
    setIsLoading(true);
    const data = await schoolService.getFeeStatement('s1');
    setFeeData(data);
    setIsLoading(false);
    setView('fees');
  };

  if (view === 'transcript') {
    return (
      <div className="space-y-4">
        <button 
          onClick={() => setView('selection')} 
          className="no-print flex items-center text-blue-600 font-bold hover:gap-2 transition-all"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Reports
        </button>
        <TranscriptModule />
      </div>
    );
  }

  return (
    <div className="space-y-8 max-w-6xl mx-auto pb-20">
      <div className="no-print">
        <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Academic Reporting</h1>
        <p className="text-gray-500 font-medium">Generate, print and export comprehensive school records.</p>
      </div>

      {view === 'selection' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 no-print animate-in fade-in duration-300">
          <ReportCard 
            title="Report Cards" 
            desc="Individual academic transcripts with CBC ratings."
            icon={FileBadge}
            onClick={() => setView('transcript')}
            color="indigo"
          />
          <ReportCard 
            title="Bulk Download" 
            desc="Generate report cards for whole classes at once."
            icon={Files}
            onClick={() => setView('bulk-transcripts')}
            color="purple"
          />
          <ReportCard 
            title="Attendance" 
            desc="History of student presence and absence records."
            icon={ClipboardCheck}
            onClick={loadAttendance}
            color="emerald"
          />
          <ReportCard 
            title="Fee Statements" 
            desc="Transaction history and balance tracking."
            icon={Wallet}
            onClick={loadFees}
            color="blue"
          />
        </div>
      )}

      {view === 'bulk-transcripts' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="no-print flex items-center justify-between bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
            <div className="flex items-center gap-4">
              <button onClick={() => setView('selection')} className="p-2 hover:bg-gray-100 rounded-full">
                <ArrowLeft className="w-6 h-6 text-gray-600" />
              </button>
              <div>
                <h3 className="font-black text-xl text-gray-900 tracking-tight">Bulk Report Generation</h3>
                <p className="text-xs text-gray-500 font-bold uppercase tracking-widest">Select Class & Stream to process</p>
              </div>
            </div>
            <div className="flex gap-2">
              <div className="relative">
                <select 
                  value={filterClass}
                  onChange={(e) => setFilterClass(e.target.value)}
                  className="pl-9 pr-4 py-2 border-2 border-gray-100 rounded-xl text-xs font-black uppercase appearance-none bg-white outline-none focus:border-blue-500"
                >
                  {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <Filter className="w-4 h-4 absolute left-3 top-2.5 text-gray-400" />
              </div>
              <select 
                value={filterStream}
                onChange={(e) => setFilterStream(e.target.value)}
                className="px-4 py-2 border-2 border-gray-100 rounded-xl text-xs font-black uppercase appearance-none bg-white outline-none focus:border-blue-500"
              >
                <option value="All">All Streams</option>
                {SCHOOL_STREAMS.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              <button 
                onClick={handleBulkDownload}
                disabled={isBulkGenerating || filteredBulkStudents.length === 0}
                className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2 rounded-xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 disabled:opacity-50 shadow-lg shadow-blue-100 transition-all"
              >
                {isBulkGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
                <span>{isBulkGenerating ? 'Processing...' : `Download ${filteredBulkStudents.length} Reports`}</span>
              </button>
            </div>
          </div>

          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden no-print">
             <div className="p-8 border-b bg-gray-50/50">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Students Queue for {filterClass}</h4>
             </div>
             <div className="divide-y">
               {filteredBulkStudents.map(student => (
