  const [admSearch, setAdmSearch] = useState('');
  const [targetedLearner, setTargetedLearner] = useState<any | null>(null);
  const [amount, setAmount] = useState('');
  const [transactionId, setTransactionId] = useState('');
  const [lastTx, setLastTx] = useState<any>(null);
  const [schoolConfig, setSchoolConfig] = useState<AcademicConfig | null>(null);

  useEffect(() => {
    schoolService.getAcademicConfig().then(setSchoolConfig);
  }, []);

  const classSummaryData = useMemo(() => {
    return KENYAN_CLASSES.map(cls => {
      const clsStudents = allStudents.filter(s => s.class === cls);
      const expected = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.total, 0) : 450000;
      const collected = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.paid, 0) : Math.floor(expected * 0.7);
      return { name: cls, expected, collected, students: clsStudents.length > 0 ? clsStudents.length : 40 };
    });
  }, [allStudents]);

  const currentStats = useMemo(() => {
    let filteredList = allStudents;
    if (selectedClass !== 'All Classes') {
      filteredList = allStudents.filter(s => s.class === selectedClass);
    }
    const expected = selectedClass === 'All Classes' ? classSummaryData.reduce((acc, curr) => acc + curr.expected, 0) : classSummaryData.find(c => c.name === selectedClass)?.expected || 0;
    const collected = selectedClass === 'All Classes' ? classSummaryData.reduce((acc, curr) => acc + curr.collected, 0) : classSummaryData.find(c => c.name === selectedClass)?.collected || 0;
    const studentCount = selectedClass === 'All Classes' ? classSummaryData.reduce((acc, curr) => acc + curr.students, 0) : classSummaryData.find(c => c.name === selectedClass)?.students || 0;
    return { students: studentCount, expected, collected, outstanding: expected - collected, prepaid: 240000 };
  }, [selectedClass, allStudents, classSummaryData]);

  const handleIdentifyLearner = (customAdm?: string) => {
    const adm = (customAdm || admSearch).toUpperCase();
    if (!adm) return;
    setIsProcessing(true);
    setTimeout(() => {
      const student = allStudents.find(s => s.adm === adm);
      if (student) {
        setTargetedLearner(student);
        setStep('details');
        setActiveTab('payments');
      } else { alert("Student ADM not found."); }
      setIsProcessing(false);
    }, 600);
  };

  const handlePostPayment = () => {
    if (!targetedLearner || !amount) return;
    setIsProcessing(true);
    const payAmount = parseInt(amount);
    setTimeout(() => {
      setAllStudents(prev => prev.map(s => {
        if (s.adm === targetedLearner.adm) {
          const newPaid = s.paid + payAmount;
          return { ...s, paid: newPaid, balance: s.total - newPaid };
        }
        return s;
      }));
      const newTx = {
        name: targetedLearner.name,
        adm: targetedLearner.adm,
        method: paymentMode.toUpperCase(),
        amount: payAmount,
        id: transactionId,
        status: 'Confirmed',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        date: new Date().toISOString().split('T')[0]
      };
      setHistory([newTx, ...history]);
      setLastTx(newTx);
      setStep('success');
      setIsProcessing(false);
    }, 1200);
  };

  const generatePDF = async (elementId: string, filename: string) => {
    const element = document.getElementById(elementId);
    if (!element) {
      console.error(`Element with id ${elementId} not found`);
      return;
    }

    // Improved constructor check for html2pdf
    const html2pdf = _html2pdf?.default || _html2pdf;

    if (typeof html2pdf !== 'function') {
      console.error("html2pdf library could not be initialized as a function. Falling back to print.");
      window.print();
      return;
    }

    const opt = {
      margin: 0.3,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, logging: false },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    try { 
      await html2pdf().set(opt).from(element).save(); 
    } catch (e) { 
      console.error("PDF Generation Error:", e); 
      window.print(); 
    }
  };

  const filteredStudents = useMemo(() => {
    return allStudents.filter(s => (selectedClass === 'All Classes' || s.class === selectedClass) && (s.name.toLowerCase().includes(studentSearch.toLowerCase()) || s.adm.toLowerCase().includes(studentSearch.toLowerCase())));
  }, [allStudents, selectedClass, studentSearch]);

  return (
    <div className="space-y-8">
      {/* Hidden Templates for PDFs - Moved off-screen instead of display:none */}
      <div className="absolute -left-[9999px] top-0 pointer-events-none overflow-hidden h-0 w-0" aria-hidden="true">
        {/* Receipt Template */}
        {lastTx && (
          <div id="receipt-template" className="p-16 bg-white text-gray-900 font-sans border-2 border-gray-900" style={{ width: '210mm', minHeight: '148mm' }}>
            <div className="flex justify-between border-b-4 border-gray-900 pb-6 mb-8">
              <div>
                <h1 className="text-3xl font-black uppercase tracking-tighter text-blue-900">{schoolConfig?.schoolName}</h1>
                <p className="text-xs font-bold uppercase tracking-widest text-gray-500">Official Payment Receipt</p>
                <p className="text-[10px] font-black text-gray-400 mt-2 uppercase">Ref No: {lastTx.id}</p>
              </div>
              <div className="text-right">
                <div className="text-xl font-black">{lastTx.date}</div>
                <div className="text-[10px] font-bold text-gray-400 uppercase">Transaction Date</div>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-12 mb-12">
              <div className="space-y-4">
                <div className="border-b border-gray-100 pb-1">
                  <span className="text-[9px] font-black text-gray-400 uppercase block">Received From</span>
                  <span className="text-lg font-black">{lastTx.name}</span>
                </div>
                <div className="border-b border-gray-100 pb-1">
                  <span className="text-[9px] font-black text-gray-400 uppercase block">Admission No.</span>
                  <span className="font-mono font-black text-blue-700">{lastTx.adm}</span>
                </div>
              </div>
              <div className="space-y-4">
                <div className="border-b border-gray-100 pb-1">
                  <span className="text-[9px] font-black text-gray-400 uppercase block">Payment Method</span>
                  <span className="font-black">{lastTx.method}</span>
                </div>
                <div className="border-b border-gray-100 pb-1">
                  <span className="text-[9px] font-black text-gray-400 uppercase block">Status</span>
                  <span className="font-black text-green-600 uppercase">Confirmed</span>
                </div>
              </div>
            </div>
            <div className="bg-gray-100 p-8 rounded-2xl mb-12 flex justify-between items-center border-2 border-gray-200">
               <span className="text-2xl font-black uppercase">Amount Paid</span>
               <span className="text-4xl font-black text-blue-900">KES {lastTx.amount.toLocaleString()}.00</span>
            </div>
            <div className="flex justify-between items-end mt-12 pt-12 border-t border-dashed border-gray-300">
               <div>
                  <div className="text-[10px] font-black uppercase text-gray-400 mb-6">Cashier Signature</div>
                  <div className="w-48 h-[1px] bg-gray-900"></div>
                  <p className="text-[8px] font-bold text-gray-400 mt-2 italic">Electronic Receipt - No stamp required</p>
               </div>
               <div className="text-right">
                  <div className="w-20 h-20 border-4 border-double border-blue-900/10 rounded-full flex items-center justify-center opacity-30 rotate-12">
                    <span className="text-[8px] font-black text-center uppercase">OFFICIAL<br/>SEAL</span>
                  </div>
               </div>
            </div>
          </div>
        )}

        {/* Class Ledger Template */}
        <div id="class-report-template" className="p-16 bg-white" style={{ width: '210mm' }}>
           <div className="text-center border-b-4 border-blue-900 pb-8 mb-8">
              <h1 className="text-3xl font-black uppercase text-blue-900">{schoolConfig?.schoolName}</h1>
              <h2 className="text-xl font-bold uppercase tracking-widest text-gray-500 mt-2">{selectedClass} Financial Status Report</h2>
              <p className="text-[10px] font-black text-gray-400 uppercase mt-2">Generated on {new Date().toLocaleDateString()}</p>
           </div>
           <div className="grid grid-cols-3 gap-4 mb-8">
              <div className="p-4 bg-blue-50 border border-blue-100 rounded-xl text-center">
                 <p className="text-[8px] font-black text-blue-400 uppercase">Total Expected</p>
                 <p className="text-lg font-black text-blue-900">KES {currentStats.expected.toLocaleString()}</p>
              </div>
              <div className="p-4 bg-green-50 border border-green-100 rounded-xl text-center">
                 <p className="text-[8px] font-black text-green-400 uppercase">Total Collected</p>
                 <p className="text-lg font-black text-green-900">KES {currentStats.collected.toLocaleString()}</p>
              </div>
              <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-center">
                 <p className="text-[8px] font-black text-red-400 uppercase">Total Outstanding</p>
                 <p className="text-lg font-black text-red-900">KES {currentStats.outstanding.toLocaleString()}</p>
              </div>
           </div>
           <table className="w-full border-collapse border border-gray-200">
              <thead>
                 <tr className="bg-gray-100 text-[9px] font-black uppercase">
                    <th className="p-3 border">ADM</th>
                    <th className="p-3 border text-left">Learner Name</th>
                    <th className="p-3 border text-right">Total Fees</th>
                    <th className="p-3 border text-right">Paid</th>
                    <th className="p-3 border text-right">Balance</th>
                 </tr>
              </thead>
              <tbody className="text-[10px]">
                 {filteredStudents.map(s => (
                    <tr key={s.adm}>
                       <td className="p-2 border font-mono text-center">{s.adm}</td>
                       <td className="p-2 border font-bold uppercase">{s.name}</td>
                       <td className="p-2 border text-right">{s.total.toLocaleString()}</td>
                       <td className="p-2 border text-right text-green-600 font-bold">{s.paid.toLocaleString()}</td>
                       <td className="p-2 border text-right text-red-600 font-bold">{s.balance.toLocaleString()}</td>
                    </tr>
                 ))}
              </tbody>
           </table>
        </div>

        {/* Institutional Summary Template */}
        <div id="institutional-summary-template" className="p-16 bg-white" style={{ width: '210mm' }}>
           <div className="text-center border-b-4 border-blue-900 pb-8 mb-8">
              <h1 className="text-3xl font-black uppercase text-blue-900">{schoolConfig?.schoolName}</h1>
              <h2 className="text-xl font-bold uppercase tracking-widest text-gray-500 mt-2">Institutional Financial Summary</h2>
              <p className="text-[10px] font-black text-gray-400 uppercase mt-2">Comprehensive Record - {new Date().toLocaleDateString()}</p>
           </div>
           <table className="w-full border-collapse border border-gray-200">
              <thead>
                 <tr className="bg-gray-100 text-[9px] font-black uppercase">
                    <th className="p-3 border text-left">Grade / Class</th>
                    <th className="p-3 border text-right">Expected</th>
                    <th className="p-3 border text-right">Realized</th>
                    <th className="p-3 border text-right">Outstanding</th>
                 </tr>
              </thead>
              <tbody className="text-[10px]">
                 {classSummaryData.map((cls, idx) => (
                    <tr key={idx}>
                       <td className="p-3 border font-black uppercase">{cls.name}</td>
                       <td className="p-3 border text-right">{cls.expected.toLocaleString()}</td>
                       <td className="p-3 border text-right text-green-700 font-bold">{cls.collected.toLocaleString()}</td>
                       <td className="p-3 border text-right text-red-700 font-bold">{(cls.expected - cls.collected).toLocaleString()}</td>
                    </tr>
                 ))}
                 <tr className="bg-blue-900 text-white font-black">
                    <td className="p-3 border uppercase">Grand Totals</td>
                    <td className="p-3 border text-right">KES {classSummaryData.reduce((a,c)=>a+c.expected,0).toLocaleString()}</td>
                    <td className="p-3 border text-right">KES {classSummaryData.reduce((a,c)=>a+c.collected,0).toLocaleString()}</td>
                    <td className="p-3 border text-right">KES {classSummaryData.reduce((a,c)=>a+(c.expected-c.collected),0).toLocaleString()}</td>
                 </tr>
              </tbody>
           </table>
        </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">{t.finance}</h1>
          <p className="text-gray-500 font-medium">Institutional Financial Records & Cashier Portal</p>
        </div>
        <div className="flex flex-wrap items-center gap-3 no-print">
          <div className="relative">
            <select 
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="appearance-none pl-10 pr-10 py-2.5 bg-white border-2 border-gray-100 rounded-xl text-xs font-black uppercase tracking-widest text-gray-700 focus:border-blue-500 outline-none shadow-sm transition-all hover:border-blue-100"
            >
              <option>All Classes</option>
              {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
            </select>
            <Filter className="w-4 h-4 absolute left-3.5 top-3 text-gray-400 pointer-events-none" />
          </div>

          <div className="flex p-1.5 bg-gray-100 rounded-xl">
            <button onClick={() => setActiveTab('payments')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Post Payment</button>
            <button onClick={() => setActiveTab('class-summary')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{selectedClass === 'All Classes' ? 'Overview' : `${selectedClass} Ledger`}</button>
            <button onClick={() => setActiveTab('reconciliation')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'reconciliation' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Sync</button>
          </div>
        </div>
      </div>

      {/* Header Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-2xl border-2 border-indigo-50 shadow-sm relative overflow-hidden group hover:border-indigo-100 transition-all">
          <Target className="w-12 h-12 text-indigo-600 absolute -right-2 -bottom-2 opacity-[0.05]" />
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Expected Revenue</p>
          <h3 className="text-xl font-black text-indigo-900 tracking-tighter">KES {currentStats.expected.toLocaleString()}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl border-2 border-green-50 shadow-sm relative overflow-hidden group hover:border-green-100 transition-all">
          <TrendingUp className="w-12 h-12 text-green-600 absolute -right-2 -bottom-2 opacity-[0.05]" />
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Collected Fees</p>
          <h3 className="text-xl font-black text-green-700 tracking-tighter">KES {currentStats.collected.toLocaleString()}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl border-2 border-red-50 shadow-sm relative overflow-hidden group hover:border-red-100 transition-all">
          <AlertCircle className="w-12 h-12 text-red-600 absolute -right-2 -bottom-2 opacity-[0.05]" />
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Outstanding Debt</p>
          <h3 className="text-xl font-black text-red-700 tracking-tighter">KES {currentStats.outstanding.toLocaleString()}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl border-2 border-blue-50 shadow-sm relative overflow-hidden group hover:border-blue-100 transition-all">
          <Forward className="w-12 h-12 text-blue-600 absolute -right-2 -bottom-2 opacity-[0.05]" />
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Prepaid Credits</p>
          <h3 className="text-xl font-black text-blue-700 tracking-tighter">KES {currentStats.prepaid.toLocaleString()}</h3>
        </div>
      </div>

      {activeTab === 'payments' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1">
            <div className="bg-white rounded-3xl shadow-2xl border border-gray-100 overflow-hidden sticky top-8">
              <div className="bg-gray-900 p-8 text-white relative">
                 <ShieldCheck className="w-16 h-16 absolute top-0 right-0 p-6 opacity-10" />
                 <h3 className="text-xl font-black uppercase tracking-tight flex items-center gap-3">
                   <div className="p-2 bg-blue-600 rounded-lg"><Receipt className="w-5 h-5 text-white" /></div>
                   Record Payment
                 </h3>
              </div>
              <div className="p-8 space-y-6">
                {step === 'identify' && (
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ADM No.</label>
                      <input autoFocus value={admSearch} onChange={(e) => setAdmSearch(e.target.value)} className="w-full p-4 border-2 border-gray-100 rounded-2xl font-black text-lg focus:border-blue-500 outline-none" placeholder="e.g. ADM001" />
                    </div>
                    <button onClick={() => handleIdentifyLearner()} disabled={!admSearch || isProcessing} className="w-full bg-blue-600 text-white font-black uppercase tracking-widest py-4 rounded-2xl hover:bg-blue-700 transition-all shadow-xl flex items-center justify-center gap-2">
                      {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <UserCheck className="w-5 h-5" />}
                      Verify Student
                    </button>
                  </div>
                )}
                {step === 'details' && targetedLearner && (
                  <div className="space-y-6">
                    <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 flex items-center justify-between">
                       <div>
                         <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Learner Verified</p>
                         <h4 className="font-black text-blue-900">{targetedLearner.name}</h4>
                       </div>
                       <button onClick={() => setStep('identify')} className="p-2 hover:bg-white rounded-xl text-blue-400"><X className="w-4 h-4" /></button>
                    </div>
                    <div className="grid grid-cols-3 gap-2">
                        {[{ id: 'mpesa', icon: Smartphone, label: 'M-Pesa' }, { id: 'bank', icon: Building2, label: 'Bank' }, { id: 'cash', icon: Banknote, label: 'Cash' }].map(mode => (
                          <button key={mode.id} onClick={() => setPaymentMode(mode.id as any)} className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${paymentMode === mode.id ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-gray-50 text-gray-400'}`}>
                            <mode.icon className="w-5 h-5 mb-1" />
                            <span className="text-[9px] font-black uppercase">{mode.label}</span>
                          </button>
                        ))}
                    </div>
                    <input value={transactionId} onChange={(e) => setTransactionId(e.target.value.toUpperCase())} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl font-black outline-none uppercase" placeholder="Ref Number" />
                    <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full p-4 border-2 border-gray-100 rounded-2xl font-black text-2xl outline-none" placeholder="Amount (KES)" />
                    <button onClick={() => setStep('review')} disabled={!amount || !transactionId} className="w-full bg-blue-600 text-white font-black uppercase tracking-widest py-4 rounded-2xl hover:bg-blue-700 flex items-center justify-center gap-2">Verify Details <ArrowRight className="w-5 h-5" /></button>
                  </div>
                )}
                {step === 'review' && (
                   <div className="space-y-6">
                      <div className="bg-gray-50 p-6 rounded-2xl border-2 border-dashed border-gray-200 space-y-4">
                         <div className="flex justify-between border-b pb-2"><span className="text-[10px] font-black text-gray-400 uppercase">Learner</span><span className="font-black">{targetedLearner.name}</span></div>
                         <div className="flex justify-between border-b pb-2"><span className="text-[10px] font-black text-gray-400 uppercase">Ref #</span><span className="font-black text-blue-600">{transactionId}</span></div>
                         <div className="flex justify-between pt-1"><span className="text-[10px] font-black text-gray-400 uppercase">Amount</span><span className="text-2xl font-black text-green-600">KES {parseInt(amount).toLocaleString()}</span></div>
                      </div>
                      <button onClick={handlePostPayment} disabled={isProcessing} className="w-full bg-green-600 text-white font-black uppercase tracking-widest py-4 rounded-2xl hover:bg-green-700 shadow-xl flex items-center justify-center gap-2">
                        {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <ShieldCheck className="w-5 h-5" />}
                        Finalize Posting
                      </button>
                   </div>
                )}
                {step === 'success' && (
                  <div className="text-center py-10 space-y-6">
                    <div className="w-20 h-20 bg-green-50 rounded-full flex items-center justify-center mx-auto border-4 border-white shadow-xl">
                      <CheckCircle2 className="w-10 h-10 text-green-600" />
                    </div>
                    <div className="space-y-2">
                      <h4 className="text-xl font-black uppercase">Posted!</h4>
                      <p className="text-sm text-gray-500 font-medium">The ledger has been updated.</p>
                    </div>
                    <div className="flex flex-col gap-2">
                      <button 
                        onClick={() => generatePDF('receipt-template', `Receipt_${lastTx.id}.pdf`)}
                        className="w-full bg-gray-900 text-white font-black uppercase tracking-widest py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-black transition-all"
                      >
                        <Printer className="w-4 h-4" />
                        Print Receipt
                      </button>
                      <button onClick={() => setStep('identify')} className="text-blue-600 font-black uppercase text-[10px] tracking-widest py-2">Post Another</button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="lg:col-span-2">
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                <h3 className="font-black text-gray-800 uppercase tracking-tight flex items-center gap-2"><History className="w-5 h-5 text-blue-600" /> Recent Transactions</h3>
              </div>
              <div className="divide-y">
                {history.map((tx, idx) => (
                  <div key={idx} className="p-6 flex items-center justify-between hover:bg-gray-50/30 transition-colors group">
                    <div className="flex items-center space-x-4">
                      <div className={`p-3 rounded-xl ${tx.method === 'M-PESA' ? 'bg-green-50 text-green-600' : 'bg-blue-50 text-blue-600'}`}>
                        {tx.method === 'M-PESA' ? <Smartphone className="w-5 h-5" /> : <Building2 className="w-5 h-5" />}
                      </div>
                      <div>
                        <div className="font-black text-gray-900">{tx.name}</div>
                        <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{tx.id} • {tx.time}</div>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                       <div className="text-right">
                         <div className="font-black text-gray-900">KES {tx.amount.toLocaleString()}</div>
                         <div className="text-[9px] font-black text-green-600 uppercase">{tx.status}</div>
                       </div>
                       <button 
                        onClick={() => { setLastTx(tx); setTimeout(() => generatePDF('receipt-template', `Receipt_${tx.id}.pdf`), 100); }}
                        className="p-2 bg-gray-100 rounded-lg text-gray-400 hover:bg-blue-600 hover:text-white transition-all"
                       >
                         <Printer className="w-4 h-4" />
                       </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'class-summary' && (
