    try {
      // Exhaustive search for html2pdf constructor (ESM compatibility)
      const rawLib = (window as any).html2pdf || _html2pdf;
      const html2pdf = typeof rawLib === 'function' ? rawLib : (rawLib?.default || rawLib);

      if (typeof html2pdf !== 'function') throw new Error('html2pdf library could not be initialized as a function.');

      await html2pdf().set(opt).from(element).save();
