  { adm: 'ADM004', name: 'Sifa Otieno', total: 45000, paid: 0, balance: 45000, class: 'Grade 7' },
  { adm: 'ADM005', name: 'Baraka Ali', total: 45000, paid: 45000, balance: 0, class: 'Grade 7' },
  { adm: 'ADM101', name: 'Neema Wambui', total: 32000, paid: 32000, balance: 0, class: 'Grade 4' },
  { adm: 'ADM102', name: 'David Mwangi', total: 32000, paid: 12000, balance: 20000, class: 'Grade 4' },
  { adm: 'ADM103', name: 'Grace Mutua', total: 32000, paid: 5000, balance: 27000, class: 'Grade 4' },
  { adm: 'ADM201', name: 'Jabari Omondi', total: 25000, paid: 25000, balance: 0, class: 'PP1' },
  { adm: 'ADM202', name: 'Mwikali Musyoka', total: 25000, paid: 10000, balance: 15000, class: 'PP1' },
  { adm: 'ADM301', name: 'Caleb Kipkorir', total: 48000, paid: 40000, balance: 8000, class: 'Grade 9' },
];

export const FinanceModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [allStudents, setAllStudents] = useState(INITIAL_STUDENTS);
  const [history, setHistory] = useState([
    { name: 'Kamau Njoroge', adm: 'ADM001', method: 'M-PESA', amount: 15000, id: 'SBR4A6HJ78', status: 'Confirmed', time: '10:45 AM', date: '2024-05-20', class: 'Grade 7' },
    { name: 'Amara Kiprono', adm: 'ADM002', method: 'CASH', amount: 5000, id: 'RCP-88902', status: 'Confirmed', time: '09:15 AM', date: '2024-05-19', class: 'Grade 7' },
  ]);

  const [isProcessing, setIsProcessing] = useState(false);
  const [step, setStep] = useState<'identify' | 'details' | 'review' | 'success'>('identify');
  const [paymentMode, setPaymentMode] = useState<'mpesa' | 'cash' | 'bank'>('mpesa');
  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'reconciliation'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [studentSearch, setStudentSearch] = useState('');

  const [admSearch, setAdmSearch] = useState('');
  const [targetedLearner, setTargetedLearner] = useState<any | null>(null);
  const [amount, setAmount] = useState('');
  const [transactionId, setTransactionId] = useState('');
  const [lastTx, setLastTx] = useState<any>(null);
  const [schoolConfig, setSchoolConfig] = useState<AcademicConfig | null>(null);

  useEffect(() => {
    schoolService.getAcademicConfig().then(setSchoolConfig);
  }, []);

  const classSummaryData = useMemo(() => {
    return KENYAN_CLASSES.map(cls => {
      const clsStudents = allStudents.filter(s => s.class === cls);
      const expected = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.total, 0) : 0;
      const collected = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.paid, 0) : 0;
      return { name: cls, expected, collected, students: clsStudents.length };
    });
  }, [allStudents]);

  const currentStats = useMemo(() => {
    let filteredList = allStudents;
    if (selectedClass !== 'All Classes') {
      filteredList = allStudents.filter(s => s.class === selectedClass);
    }
    const expected = filteredList.reduce((acc, s) => acc + s.total, 0);
    const collected = filteredList.reduce((acc, s) => acc + s.paid, 0);
    return { students: filteredList.length, expected, collected, outstanding: expected - collected, prepaid: 0 };
  }, [selectedClass, allStudents]);

  const handleIdentifyLearner = (customAdm?: string) => {
    const adm = (customAdm || admSearch).toUpperCase();
    if (!adm) return;
    setIsProcessing(true);
    setTimeout(() => {
      const student = allStudents.find(s => s.adm === adm);
      if (student) {
        setTargetedLearner(student);
        setStep('details');
        setActiveTab('payments');
      } else { alert("Student ADM not found."); }
      setIsProcessing(false);
    }, 600);
  };

  const handlePostPayment = () => {
    if (!targetedLearner || !amount) return;
    setIsProcessing(true);
    const payAmount = parseInt(amount);
    setTimeout(() => {
      setAllStudents(prev => prev.map(s => {
        if (s.adm === targetedLearner.adm) {
          const newPaid = s.paid + payAmount;
          return { ...s, paid: newPaid, balance: s.total - newPaid };
        }
        return s;
      }));
      const newTx = {
        name: targetedLearner.name,
        adm: targetedLearner.adm,
        method: paymentMode.toUpperCase(),
        amount: payAmount,
        id: transactionId,
        status: 'Confirmed',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        date: new Date().toISOString().split('T')[0],
        class: targetedLearner.class
      };
      setHistory([newTx, ...history]);
      setLastTx(newTx);
      setStep('success');
      setIsProcessing(false);
    }, 1200);
  };

  const generatePDF = async (elementId: string, filename: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const rawLib = (window as any).html2pdf || _html2pdf;
    const html2pdf = typeof rawLib === 'function' ? rawLib : (rawLib?.default || rawLib);

    if (typeof html2pdf !== 'function') {
      window.print();
      return;
    }

    const opt = {
      margin: 0.3,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, logging: false },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    try { 
      await html2pdf().set(opt).from(element).save(); 
    } catch (e) { 
      window.print(); 
    }
  };

  const filteredStudents = useMemo(() => {
    return allStudents.filter(s => (selectedClass === 'All Classes' || s.class === selectedClass) && (s.name.toLowerCase().includes(studentSearch.toLowerCase()) || s.adm.toLowerCase().includes(studentSearch.toLowerCase())));
  }, [allStudents, selectedClass, studentSearch]);

  const paidHistoryForClass = useMemo(() => {
    return history.filter(h => selectedClass === 'All Classes' || h.class === selectedClass);
  }, [history, selectedClass]);

  return (
    <div className="space-y-8">
      {/* Off-screen Templates for PDF Generation */}
      <div className="offscreen-template" aria-hidden="true">
        {/* Single Receipt Template */}
        {lastTx && (
          <div id="receipt-template" className="p-16 bg-white text-gray-900 font-sans border-2 border-gray-900" style={{ width: '210mm' }}>
            <ReceiptContent tx={lastTx} schoolConfig={schoolConfig} />
          </div>
        )}

        {/* Bulk Receipts Container */}
        <div id="bulk-receipts-template">
          {paidHistoryForClass.map((tx, idx) => (
            <div key={idx} style={{ pageBreakAfter: 'always', padding: '16px', background: 'white' }}>
              <div className="p-16 border-2 border-gray-900">
                <ReceiptContent tx={tx} schoolConfig={schoolConfig} />
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">{t.finance}</h1>
          <p className="text-gray-500 font-medium">Institutional Financial Records & Cashier Portal</p>
        </div>
        <div className="flex flex-wrap items-center gap-3 no-print">
          <div className="relative">
            <select 
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="appearance-none pl-10 pr-10 py-2.5 bg-white border-2 border-gray-100 rounded-xl text-xs font-black uppercase tracking-widest text-gray-700 focus:border-blue-500 outline-none shadow-sm transition-all hover:border-blue-100"
            >
              <option>All Classes</option>
              {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
            </select>
            <Filter className="w-4 h-4 absolute left-3.5 top-3 text-gray-400 pointer-events-none" />
          </div>

          <div className="flex p-1.5 bg-gray-100 rounded-xl">
            <button onClick={() => setActiveTab('payments')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Post Payment</button>
            <button onClick={() => setActiveTab('class-summary')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Class Ledger</button>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Expected Revenue" value={currentStats.expected} icon={Target} color="indigo" />
        <StatCard label="Collected Fees" value={currentStats.collected} icon={TrendingUp} color="green" />
        <StatCard label="Outstanding Debt" value={currentStats.outstanding} icon={AlertCircle} color="red" />
        <StatCard label="Paid Students" value={paidHistoryForClass.length} icon={Users} color="blue" />
      </div>

      {activeTab === 'payments' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1">
            <div className="bg-white rounded-3xl shadow-2xl border border-gray-100 overflow-hidden sticky top-8">
              <div className="bg-gray-900 p-8 text-white">
                 <h3 className="text-xl font-black uppercase tracking-tight flex items-center gap-3">
                   <div className="p-2 bg-blue-600 rounded-lg"><Receipt className="w-5 h-5 text-white" /></div>
                   Record Payment
                 </h3>
              </div>
              <div className="p-8 space-y-6">
                {step === 'identify' && (
                  <div className="space-y-6">
                    <input autoFocus value={admSearch} onChange={(e) => setAdmSearch(e.target.value)} className="w-full p-4 border-2 border-gray-100 rounded-2xl font-black text-lg focus:border-blue-500 outline-none" placeholder="Enter ADM No." />
                    <button onClick={() => handleIdentifyLearner()} disabled={!admSearch || isProcessing} className="w-full bg-blue-600 text-white font-black uppercase tracking-widest py-4 rounded-2xl hover:bg-blue-700 flex items-center justify-center gap-2">
                      {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <UserCheck className="w-5 h-5" />}
                      Verify Student
                    </button>
                  </div>
                )}
                {step === 'details' && targetedLearner && (
                  <div className="space-y-6 animate-in slide-in-from-bottom-2">
                    <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 flex items-center justify-between">
                       <div>
                         <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Student Verified</p>
                         <h4 className="font-black text-blue-900">{targetedLearner.name}</h4>
                       </div>
                       <button onClick={() => setStep('identify')} className="p-2 hover:bg-white rounded-xl text-blue-400"><X className="w-4 h-4" /></button>
                    </div>
                    <div className="grid grid-cols-3 gap-2">
                        {[{ id: 'mpesa', icon: Smartphone, label: 'M-Pesa' }, { id: 'bank', icon: Building2, label: 'Bank' }, { id: 'cash', icon: Banknote, label: 'Cash' }].map(mode => (
                          <button key={mode.id} onClick={() => setPaymentMode(mode.id as any)} className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${paymentMode === mode.id ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-gray-50 text-gray-400'}`}>
                            <mode.icon className="w-5 h-5 mb-1" />
                            <span className="text-[9px] font-black uppercase">{mode.label}</span>
                          </button>
                        ))}
                    </div>
                    <input value={transactionId} onChange={(e) => setTransactionId(e.target.value.toUpperCase())} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl font-black outline-none uppercase" placeholder="Ref Number / Receipt #" />
                    <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full p-4 border-2 border-gray-100 rounded-2xl font-black text-2xl outline-none" placeholder="Amount (KES)" />
                    <button onClick={handlePostPayment} disabled={!amount || !transactionId} className="w-full bg-blue-600 text-white font-black uppercase tracking-widest py-4 rounded-2xl hover:bg-blue-700 flex items-center justify-center gap-2">Confirm Payment</button>
                  </div>
                )}
                {step === 'success' && (
                  <div className="text-center py-6 space-y-6">
                    <div className="w-16 h-16 bg-green-50 rounded-full flex items-center justify-center mx-auto">
                      <CheckCircle2 className="w-8 h-8 text-green-600" />
                    </div>
                    <h4 className="text-xl font-black uppercase">Payment Posted!</h4>
                    <div className="flex flex-col gap-2">
                      <button onClick={() => generatePDF('receipt-template', `Receipt_${lastTx.id}.pdf`)} className="w-full bg-gray-900 text-white font-black uppercase tracking-widest py-3 rounded-xl flex items-center justify-center gap-2 hover:bg-black transition-all">
                        <Download className="w-4 h-4" /> Download PDF
                      </button>
                      <button onClick={() => setStep('identify')} className="text-blue-600 font-black uppercase text-[10px] tracking-widest py-2">Next Payment</button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
          <div className="lg:col-span-2">
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                <h3 className="font-black text-gray-800 uppercase tracking-tight flex items-center gap-2"><History className="w-5 h-5 text-blue-600" /> Recent Transactions ({selectedClass})</h3>
                <div className="flex gap-2">
                   <button onClick={() => window.print()} className="flex items-center gap-2 bg-white border px-4 py-2 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-gray-50 transition-all">
                      <Printer className="w-4 h-4" /> Bulk Print
