        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Academic Reporting</h1>
          <p className="text-gray-500 font-medium">Generate printable transcripts and financial summaries.</p>
        </div>
        <div className="flex gap-3">
          <div className="relative">
            <select 
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="appearance-none pl-10 pr-10 py-2.5 bg-white border-2 border-gray-100 rounded-xl text-xs font-black uppercase tracking-widest text-gray-700 focus:ring-4 focus:ring-blue-100 outline-none shadow-sm transition-all"
            >
              <option>All Classes</option>
              {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
            </select>
            <Filter className="w-4 h-4 absolute left-3.5 top-3 text-gray-400 pointer-events-none" />
          </div>
          {view === 'selection' && (
            <button 
              onClick={handleBulkDownload}
              disabled={isBulkGenerating || filteredBulkStudents.length === 0}
              className="flex items-center gap-2 bg-blue-600 text-white px-5 py-2.5 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-blue-700 disabled:opacity-50 transition-all shadow-lg shadow-blue-100"
            >
              {isBulkGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Layers className="w-4 h-4" />}
              Bulk Download {selectedClass}
            </button>
          )}
        </div>
      </div>

      {view === 'selection' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 no-print animate-in fade-in duration-300">
          <ReportCard 
            title="Individual Cards" 
            desc="Academic transcripts with CBC ratings."
            icon={FileBadge}
            onClick={() => setView('transcript')}
            color="indigo"
          />
          <ReportCard 
            title="Attendance" 
            desc="Student presence and engagement history."
            icon={ClipboardCheck}
            onClick={loadAttendance}
            color="emerald"
          />
          <ReportCard 
            title="Fee Statements" 
            desc="Transaction history and billing records."
            icon={Wallet}
            onClick={loadFees}
            color="blue"
          />
          <ReportCard 
            title="Bulk Action" 
            desc="Export class report cards to unified PDF."
            icon={Files}
            onClick={handleBulkDownload}
            color="purple"
          />
        </div>
