        ))}
      </div>

      {view === 'attendance' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="no-print flex items-center justify-between">
            <button onClick={() => setView('selection')} className="flex items-center text-blue-600 font-black uppercase text-xs tracking-widest"><ArrowLeft className="w-4 h-4 mr-2" /> Back</button>
            <div className="flex gap-2">
              <button onClick={() => exportToCSV(attendanceData, 'Attendance_Report')} className="flex items-center space-x-2 border-2 px-6 py-2.5 rounded-xl hover:bg-gray-50 font-black uppercase text-xs tracking-widest text-gray-700"><FileSpreadsheet className="w-4 h-4" /> <span>CSV</span></button>
              <button onClick={() => window.print()} className="flex items-center space-x-2 bg-blue-600 text-white px-6 py-2.5 rounded-xl hover:bg-blue-700 font-black uppercase text-xs tracking-widest shadow-lg transition-all"><Printer className="w-4 h-4" /> <span>Print</span></button>
            </div>
          </div>
          <div className="bg-white rounded-3xl shadow-sm border p-8">
            <h2 className="text-3xl font-black text-gray-900 uppercase text-center mb-8 border-b pb-8">Attendance History</h2>
            <table className="w-full text-left">
              <thead><tr className="bg-gray-50 border-b text-[10px] font-black uppercase text-gray-400 tracking-widest"><th className="px-8 py-4">Date</th><th className="px-8 py-4">Status</th><th className="px-8 py-4">Remarks</th></tr></thead>
              <tbody className="divide-y">{attendanceData.map((rec, i) => (<tr key={i} className="hover:bg-gray-50/50"><td className="px-8 py-4 font-black text-gray-800">{rec.date}</td><td className="px-8 py-4"><span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${rec.status === 'Present' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>{rec.status}</span></td><td className="px-8 py-4 text-gray-500 italic text-sm">{rec.remarks || 'Normal'}</td></tr>))}</tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'fees' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="no-print flex items-center justify-between">
            <button onClick={() => setView('selection')} className="flex items-center text-blue-600 font-black uppercase text-xs tracking-widest"><ArrowLeft className="w-4 h-4 mr-2" /> Back</button>
            <div className="flex gap-2">
              <button onClick={() => exportToCSV(feeData, 'Fee_Statement')} className="flex items-center space-x-2 border-2 px-6 py-2.5 rounded-xl hover:bg-gray-50 font-black uppercase text-xs tracking-widest text-gray-700"><FileSpreadsheet className="w-4 h-4" /> <span>CSV</span></button>
