            <button onClick={() => setActiveTab('class-summary')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Class Receipts</button>
          </div>
        </div>
      </div>

      {activeTab === 'payments' && (
