               </h3>
            </div>
            <div className="p-8 space-y-6">
              {step === 'identify' && (
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Student Admission No.</label>
                    <input autoFocus value={admSearch} onChange={(e) => setAdmSearch(e.target.value)} className="w-full p-5 border-2 border-gray-100 rounded-2xl font-black text-xl focus:border-blue-500 outline-none" placeholder="e.g. ADM001" />
                  </div>
                  <button onClick={() => handleIdentifyLearner()} disabled={!admSearch || isProcessing} className="w-full bg-blue-600 text-white font-black uppercase tracking-widest py-5 rounded-2xl hover:bg-blue-700 transition-all shadow-xl flex items-center justify-center gap-2">
                    {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <UserCheck className="w-5 h-5" />}
