                          className="p-3 bg-gray-100 rounded-xl text-gray-500 hover:bg-blue-600 hover:text-white transition-all"
                          title="Save PDF"
                        >
                          <Download className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => { setLastTx(tx); setTimeout(() => window.print(), 50); }}
                          className="p-3 bg-gray-100 rounded-xl text-gray-500 hover:bg-gray-900 hover:text-white transition-all"
                        >
                          <Printer className="w-5 h-5" />
                        </button>
                     </div>
                  </div>
                </div>
              ))}
              {paidHistoryForClass.length === 0 && (
                <div className="p-20 text-center text-gray-400">
                   <AlertCircle className="w-12 h-12 mx-auto mb-4 opacity-20" />
                   <p className="font-bold italic">No payment history found for {selectedClass}.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

