  const [isLoadingConfig, setIsLoadingConfig] = useState(true);

  const activeStudent = student || {
    id: 's1',
    admissionNumber: 'ADM/2024/048',
    firstName: 'Juma',
    lastName: 'Kipruto',
    class: 'Grade 7',
    stream: 'Eagle',
    gender: 'Male',
    dob: '2012-05-14',
    guardianPhone: '0711222333',
    guardianName: 'Robert Kipruto',
    feeBalance: 0
  } as Student;

  useEffect(() => {
    schoolService.getAcademicConfig()
      .then(data => setConfig(data))
      .finally(() => setIsLoadingConfig(false));
  }, []);

  const handleDownload = async () => {
    setIsDownloading(true);
    const element = document.getElementById(`printable-transcript-${activeStudent.id}`);
    if (!element) {
      setIsDownloading(false);
      return;
    }

    const filename = `Report_${activeStudent.firstName}_${activeStudent.lastName}_T${config?.term || 1}.pdf`;

    // Robust constructor resolution for html2pdf
    const getHtml2Pdf = () => {
      if (typeof _html2pdf === 'function') return _html2pdf;
      if (typeof (_html2pdf as any)?.default === 'function') return (_html2pdf as any).default;
      if (typeof (window as any).html2pdf === 'function') return (window as any).html2pdf;
      return null;
    };

    const html2pdfFunc = getHtml2Pdf();

    if (!html2pdfFunc) {
      window.print();
      setIsDownloading(false);
      return;
    }

    const opt = {
      margin: 0.2,
      filename: filename,
      image: { type: 'jpeg', quality: 0.95 },
      html2canvas: { 
        scale: 1.2, // Reduced scale to prevent browser hanging
        useCORS: true, 
        logging: false 
      },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    try {
      await html2pdfFunc().set(opt).from(element).save();
    } catch (error) {
      console.error('PDF Engine Error:', error);
      window.print();
    } finally {
      setIsDownloading(false);
    }
  };

  if (isLoadingConfig) {
    return (
