  /**
   * Robust resolver for html2pdf to handle ESM-wrapped imports correctly.
   */
  const getPdfLib = () => {
    // Try different common ESM export patterns
    if (typeof _html2pdf === 'function') return _html2pdf;
    if (_html2pdf && typeof (_html2pdf as any).default === 'function') return (_html2pdf as any).default;
    if (typeof (window as any).html2pdf === 'function') return (window as any).html2pdf;
    return null;
  };

  const generatePDF = async (elementId: string, filename: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    setIsPdfGenerating(true);
    const html2pdf = getPdfLib();

    if (!html2pdf) {
      console.error("PDF Engine (html2pdf) failed to initialize.");
      window.print();
      setIsPdfGenerating(false);
      return;
    }

    const opt = {
      margin: 0.3,
      filename: filename,
      image: { type: 'jpeg', quality: 0.95 },
      html2canvas: { 
        scale: 1.2, // Optimized for performance/bulk
        useCORS: true, 
        logging: false,
        letterRendering: true
      },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    try { 
      // Ensure we are calling the function correctly
      const worker = html2pdf();
      await worker.set(opt).from(element).save(); 
    } catch (e) { 
      console.error("PDF Export failed:", e);
      // Fallback to native print if library fails
      window.print(); 
    } finally {
      setIsPdfGenerating(false);
    }
