const MOCK_STUDENTS_LIST: Student[] = [
  { id: 's1', admissionNumber: 'ADM/2024/048', firstName: 'Juma', lastName: 'Kipruto', class: 'Grade 7', stream: 'Eagle', gender: 'Male', dob: '2012-05-14', guardianPhone: '0711222333', guardianName: 'Robert Kipruto', feeBalance: 0 },
  { id: 's2', admissionNumber: 'ADM/2024/001', firstName: 'Sarah', lastName: 'Njeri', class: 'Grade 7', stream: 'Oak', gender: 'Female', dob: '2012-08-20', guardianPhone: '0722111444', guardianName: 'Grace Njeri', feeBalance: 1500 },
  { id: 's3', admissionNumber: 'ADM/2024/002', firstName: 'Kamau', lastName: 'Njoroge', class: 'Grade 7', stream: 'Oak', gender: 'Male', dob: '2011-04-12', guardianPhone: '0712345678', guardianName: 'Sarah Njoroge', feeBalance: 12500 },
  { id: 's4', admissionNumber: 'ADM/2024/105', firstName: 'Zuri', lastName: 'Achieng', class: 'Grade 4', stream: 'Willow', gender: 'Female', dob: '2014-01-05', guardianPhone: '0788999888', guardianName: 'Grace Achieng', feeBalance: 4500 },
];

export const ReportsModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [view, setView] = useState<ReportView>('selection');
  const [attendanceData, setAttendanceData] = useState<AttendanceRecord[]>([]);
  const [feeData, setFeeData] = useState<FeeTransaction[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPdfGenerating, setIsPdfGenerating] = useState(false);
  const [selectedClass, setSelectedClass] = useState('Grade 7');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  const filteredStudents = MOCK_STUDENTS_LIST.filter(s => 
    selectedClass === 'All Classes' || s.class === selectedClass
  );

  const getPdfLib = () => {
    if (typeof _html2pdf === 'function') return _html2pdf;
    if (_html2pdf && typeof (_html2pdf as any).default === 'function') return (_html2pdf as any).default;
    if (typeof (window as any).html2pdf === 'function') return (window as any).html2pdf;
    return null;
  };

  const handleBulkDownload = async () => {
    if (filteredStudents.length === 0) return;
    setIsPdfGenerating(true);

    const element = document.getElementById('bulk-transcripts-container');
    if (!element) {
      setIsPdfGenerating(false);
      return;
    }

    const filename = `Report_Cards_${selectedClass.replace(/\s+/g, '_')}.pdf`;
    const html2pdf = getPdfLib();

    if (!html2pdf) {
      window.print();
      setIsPdfGenerating(false);
      return;
    }

    const opt = {
      margin: 0.2,
      filename: filename,
      image: { type: 'jpeg', quality: 0.95 },
      html2canvas: { scale: 1.2, useCORS: true, logging: false },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: 'avoid-all', after: '.bulk-page' }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error('Bulk generation failed:', error);
      window.print();
    } finally {
      setIsPdfGenerating(false);
    }
  };

  const openIndividualTranscript = (student: Student) => {
    setSelectedStudent(student);
    setView('transcript');
  };

  if (view === 'transcript' && selectedStudent) {
    return (
      <div className="space-y-6">
        <button 
          onClick={() => setView('selection')} 
          className="no-print flex items-center text-blue-600 font-black uppercase text-xs tracking-widest hover:gap-2 transition-all"
        >
          <ArrowLeft className="w-5 h-5 mr-2" /> Back to Reporting Center
        </button>
        <TranscriptModule student={selectedStudent} />
      </div>
    );
  }

  return (
    <div className="space-y-8 max-w-6xl mx-auto pb-20">
      <div className="no-print flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight uppercase">Academic Reporting</h1>
          <p className="text-gray-500 font-medium">Generate report cards and academic transcripts.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <div className="relative">
            <select 
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="appearance-none pl-10 pr-12 py-3 bg-white border-2 border-gray-100 rounded-2xl text-xs font-black uppercase tracking-widest text-gray-700 focus:ring-4 focus:ring-blue-100 outline-none shadow-sm transition-all"
            >
              <option>All Classes</option>
              {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
            </select>
            <Filter className="w-4 h-4 absolute left-3.5 top-3.5 text-gray-400 pointer-events-none" />
          </div>
          <button 
            onClick={handleBulkDownload}
            disabled={isPdfGenerating || filteredStudents.length === 0}
            className="flex items-center gap-3 bg-blue-600 text-white px-6 py-3 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 disabled:opacity-50 transition-all shadow-xl shadow-blue-100"
          >
            {isPdfGenerating ? <Loader2 className="w-5 h-5 animate-spin" /> : <Layers className="w-5 h-5" />}
            Bulk Export {selectedClass}
          </button>
        </div>
      </div>

      {view === 'selection' && (
        <div className="space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 no-print">
            <ReportCard 
              title="Individual Cards" 
              desc="Detailed report cards with CBC ratings."
              icon={FileBadge}
              onClick={() => {}}
              color="indigo"
              active={true}
            />
            <ReportCard 
              title="Attendance Records" 
              desc="Class presence and engagement history."
              icon={ClipboardCheck}
              onClick={async () => {
                setIsLoading(true);
                const data = await schoolService.getAttendanceHistory('s1');
                setAttendanceData(data);
                setIsLoading(false);
                setView('attendance');
              }}
              color="emerald"
            />
            <ReportCard 
              title="Fee Summaries" 
              desc="Institutional billing and arrears tracking."
              icon={Wallet}
              onClick={async () => {
                setIsLoading(true);
                const data = await schoolService.getFeeStatement('s1');
                setFeeData(data);
                setIsLoading(false);
                setView('fees');
              }}
              color="blue"
            />
          </div>

          <div className="bg-white rounded-[32px] shadow-sm border border-gray-100 overflow-hidden no-print">
             <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                <div>
                   <h3 className="text-xl font-black text-gray-900 tracking-tight uppercase">Learner Directory ({selectedClass})</h3>
                </div>
             </div>
             <div className="divide-y">
                {filteredStudents.map(student => (
                  <div key={student.id} className="p-6 flex items-center justify-between hover:bg-blue-50/20 transition-all group">
                     <div className="flex items-center gap-5">
                        <div className="w-14 h-14 rounded-2xl bg-blue-50 flex items-center justify-center font-black text-xl text-blue-600 border border-blue-100">
                           {student.firstName[0]}
                        </div>
                        <div>
                           <p className="font-black text-gray-900 text-lg leading-tight">{student.firstName} {student.lastName}</p>
                           <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">{student.admissionNumber} • {student.stream}</p>
                        </div>
                     </div>
                     <div className="flex gap-3">
                        <button 
                          onClick={() => openIndividualTranscript(student)}
                          className="flex items-center gap-2 bg-white border-2 border-gray-100 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest text-gray-700 hover:border-blue-200 transition-all shadow-sm"
                        >
                           <FileText className="w-4 h-4 text-blue-500" /> View Card
                        </button>
                        <button 
                          onClick={() => { setSelectedStudent(student); setTimeout(() => window.print(), 100); }}
                          className="p-2.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all shadow-sm border border-blue-100"
                        >
                           <Printer className="w-5 h-5" />
                        </button>
                     </div>
                  </div>
                ))}
                {filteredStudents.length === 0 && (
                   <div className="p-24 text-center">
                      <p className="text-gray-400 font-bold italic uppercase tracking-widest text-xs">No learners found in this class.</p>
                   </div>
                )}
             </div>
          </div>
        </div>
      )}

      {/* Bulk Rendering Stage */}
      <div id="bulk-transcripts-container" className="offscreen-template" style={{ width: '210mm' }}>
        {filteredStudents.map(student => (
          <div key={student.id} className="bulk-page" style={{ pageBreakAfter: 'always', padding: '20px', background: 'white' }}>
            <TranscriptModule student={student} hideControls />
          </div>
        ))}
      </div>

      {view === 'attendance' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="no-print flex items-center justify-between">
            <button onClick={() => setView('selection')} className="flex items-center text-blue-600 font-black uppercase text-xs tracking-widest"><ArrowLeft className="w-4 h-4 mr-2" /> Back</button>
            <button onClick={() => window.print()} className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-black uppercase text-xs shadow-lg transition-all"><Printer className="w-4 h-4 inline mr-2" /> Print Report</button>
          </div>
          <div className="bg-white rounded-3xl shadow-sm border p-12">
            <h2 className="text-4xl font-black text-gray-900 uppercase text-center mb-8 border-b-4 border-gray-900 pb-8">Student Attendance Report</h2>
            <table className="w-full text-left">
              <thead><tr className="bg-gray-50 border-b text-[10px] font-black uppercase text-gray-400 tracking-widest"><th className="px-8 py-5">Session Date</th><th className="px-8 py-5">Presence Status</th><th className="px-8 py-5">Remarks</th></tr></thead>
              <tbody className="divide-y">{attendanceData.map((rec, i) => (<tr key={i} className="hover:bg-gray-50/50"><td className="px-8 py-5 font-black text-gray-800 text-lg">{rec.date}</td><td className="px-8 py-5"><span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase ${rec.status === 'Present' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>{rec.status}</span></td><td className="px-8 py-5 text-gray-500 italic font-medium">{rec.remarks || 'Normal'}</td></tr>))}</tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'fees' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="no-print flex items-center justify-between">
            <button onClick={() => setView('selection')} className="flex items-center text-blue-600 font-black uppercase text-xs tracking-widest"><ArrowLeft className="w-4 h-4 mr-2" /> Back</button>
            <button onClick={() => window.print()} className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-black uppercase text-xs shadow-lg transition-all"><Printer className="w-4 h-4 inline mr-2" /> Print Statement</button>
          </div>
          <div className="bg-white rounded-3xl shadow-sm border p-12">
            <h2 className="text-4xl font-black text-blue-900 uppercase text-center mb-12 border-b-4 border-blue-900 pb-10">Fee Statement</h2>
            <table className="w-full text-left">
              <thead className="border-b-4 border-blue-900"><tr className="text-[10px] font-black uppercase text-gray-400 tracking-widest"><th className="py-6 px-4">Post Date</th><th className="py-6 px-4">Particulars</th><th className="py-6 px-4 text-right">Debit</th><th className="py-6 px-4 text-right">Credit</th><th className="py-6 px-4 text-right">Net</th></tr></thead>
              <tbody className="text-sm font-medium">{feeData.map((tx, i) => (<tr key={i} className="border-b hover:bg-gray-50/50 transition-colors"><td className="py-6 px-4 font-mono text-xs text-gray-500">{tx.date}</td><td className="py-6 px-4 font-black text-gray-900">{tx.description}</td><td className="py-6 px-4 text-right text-red-600 font-black">{tx.type === 'Debit' ? tx.amount.toLocaleString() : '-'}</td><td className="py-6 px-4 text-right text-green-600 font-black">{tx.type === 'Credit' ? tx.amount.toLocaleString() : '-'}</td><td className="py-6 px-4 text-right font-black text-gray-900 text-lg">KES {tx.balance.toLocaleString()}</td></tr>))}</tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

interface ReportCardProps {
  title: string;
  desc: string;
  icon: any;
  onClick: () => void;
  color: string;
  active?: boolean;
}

const ReportCard: React.FC<ReportCardProps> = ({ title, desc, icon: Icon, onClick, color, active }) => (
  <button onClick={onClick} className={`group bg-white p-10 rounded-[40px] shadow-sm border transition-all text-left relative overflow-hidden ${active ? `border-${color}-200 shadow-xl shadow-${color}-50` : 'border-gray-100 hover:border-blue-300'}`}>
    <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-125 transition-transform"><Icon className={`w-24 h-24 text-${color}-600`} /></div>
    <div className={`p-5 rounded-2xl bg-${color}-50 text-${color}-600 w-fit mb-8 border border-${color}-100 shadow-sm`}><Icon className="w-8 h-8" /></div>
    <h3 className="text-xl font-black text-gray-900 mb-2 flex items-center justify-between tracking-tight uppercase">{title} <ChevronRight className="w-6 h-6 opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all" /></h3>
    <p className="text-gray-400 text-xs font-bold leading-relaxed uppercase tracking-widest">{desc}</p>
  </button>
);

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Smartphone, 
  Receipt, 
  History, 
  AlertCircle, 
  CheckCircle2, 
  Banknote, 
  Building2,
  Search,
  Filter,
  UserCheck,
  X,
  Loader2,
  Printer,
  Download,
  Layers,
  LayoutGrid
} from 'lucide-react';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES } from '../types';
import { schoolService, AcademicConfig } from '../services/schoolService';
// @ts-ignore
import _html2pdf from 'html2pdf.js';

const INITIAL_STUDENTS = [
  { adm: 'ADM001', name: 'Kamau Njoroge', total: 45000, paid: 32500, balance: 12500, class: 'Grade 7' },
  { adm: 'ADM002', name: 'Amara Kiprono', total: 45000, paid: 45000, balance: 0, class: 'Grade 7' },
  { adm: 'ADM101', name: 'Neema Wambui', total: 32000, paid: 32000, balance: 0, class: 'Grade 4' },
  { adm: 'ADM201', name: 'Jabari Omondi', total: 25000, paid: 25000, balance: 0, class: 'PP1' },
  { adm: 'ADM301', name: 'Caleb Kipkorir', total: 48000, paid: 40000, balance: 8000, class: 'Grade 9' },
];

export const FinanceModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [allStudents] = useState(INITIAL_STUDENTS);
  const [history] = useState([
    { name: 'Kamau Njoroge', adm: 'ADM001', method: 'M-PESA', amount: 15000, id: 'SBR4A6HJ78', status: 'Confirmed', time: '10:45 AM', date: '2024-05-20', class: 'Grade 7' },
    { name: 'Amara Kiprono', adm: 'ADM002', method: 'CASH', amount: 5000, id: 'RCP-88902', status: 'Confirmed', time: '09:15 AM', date: '2024-05-19', class: 'Grade 7' },
    { name: 'Neema Wambui', adm: 'ADM101', method: 'BANK', amount: 32000, id: 'BNK-10022', status: 'Confirmed', time: '02:30 PM', date: '2024-05-18', class: 'Grade 4' },
  ]);

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [isPdfGenerating, setIsPdfGenerating] = useState(false);
  const [lastTx, setLastTx] = useState<any>(null);
  const [schoolConfig, setSchoolConfig] = useState<AcademicConfig | null>(null);

  useEffect(() => {
    schoolService.getAcademicConfig().then(setSchoolConfig);
  }, []);

  const filteredHistory = useMemo(() => {
    return history.filter(h => selectedClass === 'All Classes' || h.class === selectedClass);
  }, [history, selectedClass]);

  /**
   * Defensive Resolver for html2pdf
   */
  const getPdfEngine = () => {
    const lib = _html2pdf;
    // Handle ESM wrapping (check for .default)
    const engine = (typeof lib === 'function') ? lib : (lib as any)?.default;
    return engine;
  };

  const generatePDF = async (elementId: string, filename: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    setIsPdfGenerating(true);
    const html2pdf = getPdfEngine();

    if (!html2pdf) {
      console.error("PDF engine initialization failed. Falling back to print.");
      window.print();
      setIsPdfGenerating(false);
      return;
    }

    const opt = {
      margin: 0.3,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 1.2, 
        useCORS: true, 
        logging: false,
        letterRendering: true
      },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: 'avoid-all', after: '.pdf-page' }
    };

    try { 
      await html2pdf().set(opt).from(element).save(); 
    } catch (e) { 
      console.error("PDF Generation Error:", e);
      window.print(); 
    } finally {
      setIsPdfGenerating(false);
    }
  };

  const getStudentBalance = (adm: string) => {
    const student = allStudents.find(s => s.adm === adm);
    return student ? student.balance : 0;
  };

  return (
    <div className="space-y-8">
      {/* Off-screen Export Buffer */}
      <div className="offscreen-template" aria-hidden="true">
        {lastTx && (
          <div id="single-receipt-buffer" className="bg-white p-12" style={{ width: '210mm' }}>
            <ReceiptTemplate 
              tx={lastTx} 
              balance={getStudentBalance(lastTx.adm)} 
              schoolConfig={schoolConfig} 
            />
          </div>
        )}
        <div id="bulk-receipts-buffer">
          {filteredHistory.map((tx, idx) => (
            <div key={idx} className="bg-white p-12 pdf-page" style={{ pageBreakAfter: 'always', width: '210mm' }}>
              <ReceiptTemplate 
                tx={tx} 
                balance={getStudentBalance(tx.adm)} 
                schoolConfig={schoolConfig} 
              />
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase tracking-tight">Finance & Accounting</h1>
          <p className="text-gray-500 font-medium">Class-based receipt generation and fee reconciliation.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3 no-print">
          <div className="relative">
            <select 
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="appearance-none pl-10 pr-12 py-3 bg-white border-2 border-gray-100 rounded-2xl text-xs font-black uppercase tracking-widest text-gray-700 focus:border-blue-500 outline-none shadow-sm transition-all"
            >
              <option>All Classes</option>
              {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
            </select>
            <Filter className="w-4 h-4 absolute left-3.5 top-3.5 text-gray-400 pointer-events-none" />
          </div>

          <div className="flex p-1.5 bg-gray-100 rounded-2xl">
            <button 
              onClick={() => setActiveTab('class-summary')} 
              className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
            >
              History
            </button>
            <button 
              onClick={() => setActiveTab('payments')} 
              className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
            >
              New Entry
            </button>
          </div>
        </div>
      </div>

      {activeTab === 'class-summary' && (
        <div className="space-y-6">
          <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-8 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
              <h3 className="font-black text-gray-800 uppercase tracking-tight flex items-center gap-3 text-lg">
                <History className="w-6 h-6 text-blue-600" /> 
                {selectedClass} Transactions
              </h3>
              <div className="flex flex-wrap gap-2">
                 <button 
                  onClick={() => window.print()} 
                  className="flex items-center gap-2 bg-white border-2 border-gray-100 px-5 py-2.5 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-gray-50 transition-all"
                 >
                    <Printer className="w-4 h-4" /> Print Current
                 </button>
                 <button 
                  onClick={() => generatePDF('bulk-receipts-buffer', `Receipts_${selectedClass.replace(/\s+/g, '_')}.pdf`)} 
                  disabled={isPdfGenerating || filteredHistory.length === 0}
                  className="flex items-center gap-2 bg-blue-600 text-white px-5 py-2.5 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 disabled:opacity-50"
                 >
                    {isPdfGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Layers className="w-4 h-4" />} 
                    Save All as PDF
                 </button>
              </div>
            </div>
            <div className="divide-y">
              {filteredHistory.map((tx, idx) => (
                <div key={idx} className="p-6 flex items-center justify-between hover:bg-gray-50/30 transition-colors group">
                  <div className="flex items-center space-x-5">
                    <div className={`p-4 rounded-2xl ${tx.method === 'M-PESA' ? 'bg-green-50 text-green-600' : 'bg-blue-50 text-blue-600'}`}>
                      {tx.method === 'M-PESA' ? <Smartphone className="w-6 h-6" /> : <Building2 className="w-6 h-6" />}
                    </div>
                    <div>
                      <div className="font-black text-gray-900 text-lg leading-tight">{tx.name}</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">{tx.adm} • {tx.class} • {tx.id}</div>
                    </div>
                  </div>
                  <div className="flex items-center gap-6">
                     <div className="text-right">
                       <div className="font-black text-gray-900 text-lg tracking-tighter text-blue-600">KES {tx.amount.toLocaleString()}</div>
                       <div className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{tx.date}</div>
                     </div>
                     <div className="flex gap-2">
                        <button 
                          onClick={() => { setLastTx(tx); setTimeout(() => generatePDF('single-receipt-buffer', `Receipt_${tx.id}.pdf`), 100); }}
                          className="p-3 bg-gray-100 rounded-xl text-gray-500 hover:bg-blue-600 hover:text-white transition-all shadow-sm"
                          title="Save as PDF"
                          disabled={isPdfGenerating}
                        >
                          <Download className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => { setLastTx(tx); setTimeout(() => window.print(), 100); }}
                          className="p-3 bg-gray-100 rounded-xl text-gray-500 hover:bg-gray-900 hover:text-white transition-all shadow-sm"
                          title="Print Receipt"
                        >
                          <Printer className="w-5 h-5" />
                        </button>
                     </div>
                  </div>
                </div>
              ))}
              {filteredHistory.length === 0 && (
                <div className="p-20 text-center text-gray-300">
                   <AlertCircle className="w-12 h-12 mx-auto mb-4 opacity-20" />
                   <p className="font-bold italic uppercase tracking-widest text-xs">No payment records found.</p>
