export const TranscriptModule: React.FC<TranscriptModuleProps> = ({ student, hideControls = false }) => {
  const [config, setConfig] = useState<AcademicConfig | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [aiRemarks, setAiRemarks] = useState<string>('');
  const [isDownloading, setIsDownloading] = useState(false);
  const [isLoadingConfig, setIsLoadingConfig] = useState(true);

  const activeStudent = student || {
    id: 's1',
    admissionNumber: 'ADM/2024/048',
    firstName: 'Juma',
    lastName: 'Kipruto',
    class: 'Grade 7',
    stream: 'Eagle',
    gender: 'Male',
    dob: '2012-05-14',
    guardianPhone: '0711222333',
    guardianName: 'Robert Kipruto',
    feeBalance: 0
  } as Student;

  useEffect(() => {
    schoolService.getAcademicConfig()
      .then(data => setConfig(data))
      .finally(() => setIsLoadingConfig(false));
  }, []);

  const getPdfEngine = () => {
    const lib = _html2pdf;
    const engine = (typeof lib === 'function') ? lib : (lib as any)?.default;
    return engine;
  };

  const handleDownload = async () => {
    setIsDownloading(true);
    const element = document.getElementById(`printable-transcript-${activeStudent.id}`);
    if (!element) {
      setIsDownloading(false);
      return;
    }

    const filename = `Report_${activeStudent.firstName}_${activeStudent.lastName}_T${config?.term || 1}.pdf`;
    const html2pdf = getPdfEngine();

    if (!html2pdf) {
      window.print();
      setIsDownloading(false);
      return;
    }

    const opt = {
      margin: 0.2,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 1.2, 
        useCORS: true, 
        logging: false 
      },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    try {
      await html2pdf().set(opt).from(element).save();
    } catch (error) {
      console.error('PDF Engine Error:', error);
      window.print();
    } finally {
      setIsDownloading(false);
    }
  };

  if (isLoadingConfig) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] space-y-4">
        <Loader2 className="w-12 h-12 text-blue-600 animate-spin" />
        <p className="text-gray-400 font-black uppercase tracking-widest text-xs">Accessing Academic Records...</p>
      </div>
    );
  }

