  /**
   * Resilient resolver for html2pdf to handle varied module wrapping.
   */
  const getHtml2Pdf = () => {
    if (typeof _html2pdf === 'function') return _html2pdf;
    if ((_html2pdf as any)?.default && typeof (_html2pdf as any).default === 'function') return (_html2pdf as any).default;
    if (typeof (window as any).html2pdf === 'function') return (window as any).html2pdf;
    return null;
  };

  const generatePDF = async (elementId: string, filename: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    setIsPdfGenerating(true);
    const html2pdfFunc = getHtml2Pdf();

    if (!html2pdfFunc) {
      console.error("PDF Library not found. Falling back to print.");
      window.print();
      setIsPdfGenerating(false);
      return;
    }

    const opt = {
      margin: 0.3,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 1.2, 
        useCORS: true, 
        logging: false,
        letterRendering: true
      },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: 'avoid-all', after: '.pdf-page' }
    };

    try { 
      await html2pdfFunc().set(opt).from(element).save(); 
    } catch (e) { 
      console.error("PDF Generation Error:", e);
      window.print(); 
    } finally {
      setIsPdfGenerating(false);
    }
  };

