          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5">Expected</th>
                <th className="px-8 py-5">Paid</th>
                <th className="px-8 py-5">Balance</th>
                <th className="px-8 py-5 text-right">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {filteredStudents.map((s, idx) => (
                <tr key={idx} className="hover:bg-blue-50/20">
                  <td className="px-8 py-5">
                    <div className="font-black text-gray-900">{s.firstName} {s.lastName}</div>
                    <div className="text-[10px] text-gray-400 uppercase">{s.admissionNumber} • {s.class}</div>
