      {activeTab === 'payments' && (
        <div className="max-w-4xl mx-auto bg-white p-10 rounded-[40px] border shadow-2xl relative overflow-hidden">
          <div className="mb-10 flex items-center gap-4">
             <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl"><CreditCard className="w-8 h-8" /></div>
             <div>
               <h2 className="text-3xl font-black text-gray-900 uppercase tracking-tighter">Post Payment</h2>
               <p className="text-xs text-gray-400 font-black uppercase tracking-widest">Official Finance Terminal</p>
             </div>
          </div>
          <form onSubmit={handlePostPayment} className="space-y-8">
            <div className="grid grid-cols-2 gap-8">
              <select required value={paymentForm.adm} onChange={e => setPaymentForm({...paymentForm, adm: e.target.value})} className="p-4 bg-gray-50 border rounded-2xl font-black uppercase">
                <option value="">Select Student...</option>
                {filteredStudents.map(s => <option key={s.id} value={s.admissionNumber}>{s.admissionNumber} - {s.firstName} {s.lastName}</option>)}
              </select>
              <input required type="number" value={paymentForm.amount} onChange={e => setPaymentForm({...paymentForm, amount: e.target.value})} className="p-4 bg-gray-50 border rounded-2xl font-black" placeholder="Amount (KES)" />
              <div className="flex gap-2">
                {['M-PESA', 'BANK', 'CASH'].map(m => (
                  <button key={m} type="button" onClick={() => setPaymentForm({...paymentForm, method: m})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${paymentForm.method === m ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{m}</button>
