                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="max-w-4xl mx-auto bg-white p-12 rounded-[56px] border-2 border-gray-50 shadow-2xl shadow-blue-50 relative overflow-hidden animate-in zoom-in duration-500">
          <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
             <CreditCard className="w-64 h-64 text-blue-600" />
