interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, feeStructure, setFeeStructure }) => {
  const t = translations[lang];
  const [history, setHistory] = useState([
    { name: 'Kamau Njoroge', adm: 'ADM001', method: 'M-PESA', amount: 15000, id: 'SBR4A6HJ78', status: 'Confirmed', time: '10:45 AM', date: '2024-05-20', class: 'Grade 7' },
  ]);

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [isPosting, setIsPosting] = useState(false);
  const [isApplyingFees, setIsApplyingFees] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);

  const [globalFeeValue, setGlobalFeeValue] = useState<string>('');
  const [paymentForm, setPaymentForm] = useState({ adm: '', amount: '', method: 'M-PESA', reference: '' });

  // Dynamic calculations based on current filters
  const filteredStudents = useMemo(() => {
    return students.filter(s => selectedClass === 'All Classes' || s.class === selectedClass);
  }, [students, selectedClass]);

  const financeStats = useMemo(() => {
    const totalExpected = filteredStudents.reduce((sum, s) => sum + s.totalFee, 0);
    const totalCollected = filteredStudents.reduce((sum, s) => sum + s.paidFee, 0);
    const totalOutstanding = filteredStudents.reduce((sum, s) => sum + s.feeBalance, 0);
    const totalPrepaid = filteredStudents.reduce((sum, s) => sum + s.prepaidFee, 0);
    return { expected: totalExpected, collected: totalCollected, outstanding: totalOutstanding, prepaid: totalPrepaid };
  }, [filteredStudents]);

  const handlePostPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentForm.adm || !paymentForm.amount) return;
    setIsPosting(true);

    // Simulate API delay
    await new Promise(r => setTimeout(r, 1000));

    const amountNum = parseFloat(paymentForm.amount);
    let updatedStudent: Student | undefined;

    setStudents(prev => prev.map(s => {
      if (s.admissionNumber === paymentForm.adm) {
        const newPaid = s.paidFee + amountNum;
        let newBalance = s.totalFee - newPaid;
        let newPrepaid = s.prepaidFee;

        if (newBalance < 0) {
          newPrepaid += Math.abs(newBalance);
          newBalance = 0;
        }

        updatedStudent = { ...s, paidFee: newPaid, feeBalance: newBalance, prepaidFee: newPrepaid };
        return updatedStudent;
      }
      return s;
    }));

    if (updatedStudent) {
      const receipt: TransactionReceipt = {
        receiptNo: paymentForm.reference || `RCP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        studentName: `${updatedStudent.firstName} ${updatedStudent.lastName}`,
        adm: updatedStudent.admissionNumber,
        class: updatedStudent.class,
        amount: amountNum,
        method: paymentForm.method,
        date: new Date().toLocaleString(),
        balance: updatedStudent.feeBalance,
        servedBy: 'Admin Terminal'
      };

      setLastReceipt(receipt);
      setShowReceipt(true);

      const newTx = {
        name: receipt.studentName,
        adm: receipt.adm,
        method: receipt.method,
        amount: amountNum,
        id: receipt.receiptNo,
        status: 'Confirmed',
        time: new Date().toLocaleTimeString(),
        date: new Date().toISOString().split('T')[0],
        class: receipt.class
      };
      setHistory([newTx, ...history]);
    }

    setIsPosting(false);
    setPaymentForm({ adm: '', amount: '', method: 'M-PESA', reference: '' });
  };

  const handleUpdateClassFee = (className: string, amount: string) => {
    const val = parseInt(amount) || 0;
    setFeeStructure(prev => prev.map(f => f.className === className ? { ...f, amount: val } : f));
  };

  const applyGlobalFee = () => {
    const val = parseInt(globalFeeValue) || 0;
    if (val <= 0) return;
    setFeeStructure(prev => prev.map(f => ({ ...f, amount: val })));
    setGlobalFeeValue('');
  };

  const applyFeesToStudents = async () => {
    if (!confirm('This will update the total expected fees and balances for ALL enrolled students based on their class. Continue?')) return;

    setIsApplyingFees(true);
    await new Promise(r => setTimeout(r, 2000));

    setStudents(prev => prev.map(student => {
      const classFee = feeStructure.find(f => f.className === student.class);
      if (classFee) {
        const newTotal = classFee.amount;
        const newBalance = Math.max(0, newTotal - student.paidFee);
        const newPrepaid = student.paidFee > newTotal ? student.paidFee - newTotal : 0;
        return { ...student, totalFee: newTotal, feeBalance: newBalance, prepaidFee: newPrepaid };
      }
      return student;
    }));

    setIsApplyingFees(false);
    alert('Fee structure applied and student balances synchronized successfully.');
    setActiveTab('class-summary');
  };

  const exportToPDF = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    const h2p = (window as any).html2pdf;
    if (h2p) {
      h2p().set(opt).from(element).save();
    } else {
      window.print();
    }
  };

  const printElement = (elementId: string) => {
    const printContent = document.getElementById(elementId);
    const windowUrl = window.location.href;
    const uniqueName = new Date().getTime();
    const printWindow = window.open(windowUrl, uniqueName.toString(), 'left=0,top=0,width=800,height=900,toolbar=0,scrollbars=0,status=0');

    if (printWindow && printContent) {
      printWindow.document.write('<html><head><title>Print</title>');
      printWindow.document.write('<script src="https://cdn.tailwindcss.com"></script>');
      printWindow.document.write('</head><body>');
      printWindow.document.write(printContent.innerHTML);
      printWindow.document.write('</body></html>');
      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => {
        printWindow.print();
        printWindow.close();
      }, 500);
    }
  };

  return (
    <div className="space-y-8">
      {/* Hidden PDF/Print Templates */}
      <div id="receipt-print-template" className="hidden">
        {lastReceipt && (
          <div className="p-12 bg-white text-gray-900 font-sans border-4 border-double border-gray-200">
            <div className="text-center border-b-2 pb-6 mb-8">
              <h1 className="text-3xl font-black uppercase text-blue-900">ElimuSmart Academy</h1>
              <p className="text-xs font-bold text-gray-500 uppercase tracking-widest mt-1">Excellence in Knowledge and Character</p>
              <p className="text-[10px] mt-2 text-gray-400">P.O BOX 1234 - 00100, NAIROBI | TEL: 0700 000 000</p>
            </div>

            <div className="flex justify-between items-center mb-8">
              <h2 className="text-xl font-black uppercase underline">Official Receipt</h2>
              <div className="text-right">
                <p className="text-[10px] font-black text-gray-400 uppercase">Receipt No:</p>
                <p className="font-black text-blue-600">{lastReceipt.receiptNo}</p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-8 mb-10 text-sm">
              <div className="space-y-2">
                <p><span className="font-bold text-gray-400 uppercase text-[10px]">Student:</span> {lastReceipt.studentName}</p>
                <p><span className="font-bold text-gray-400 uppercase text-[10px]">ADM No:</span> {lastReceipt.adm}</p>
                <p><span className="font-bold text-gray-400 uppercase text-[10px]">Class:</span> {lastReceipt.class}</p>
              </div>
              <div className="space-y-2 text-right">
                <p><span className="font-bold text-gray-400 uppercase text-[10px]">Date:</span> {lastReceipt.date}</p>
                <p><span className="font-bold text-gray-400 uppercase text-[10px]">Method:</span> {lastReceipt.method}</p>
              </div>
            </div>

            <div className="border-t-4 border-gray-900 py-6 mb-10">
              <div className="flex justify-between items-center text-2xl font-black">
                <span className="uppercase">Amount Received:</span>
                <span className="text-green-700">KES {lastReceipt.amount.toLocaleString()}.00</span>
              </div>
            </div>

            <div className="bg-gray-50 p-6 rounded-2xl border-2 border-gray-100 flex justify-between mb-12">
              <span className="font-black uppercase text-sm">Outstanding Balance:</span>
              <span className="font-black text-red-600 text-lg">KES {lastReceipt.balance.toLocaleString()}.00</span>
            </div>

            <div className="flex justify-between items-end pt-12">
              <div className="text-center">
                <div className="w-40 border-b border-gray-900 mb-2"></div>
                <p className="text-[9px] font-black uppercase text-gray-400">Cashier Signature</p>
              </div>
              <div className="text-right">
                <p className="text-[8px] italic text-gray-400">This is a system generated receipt. Valid without rubber stamp.</p>
                <p className="text-[9px] font-black uppercase text-blue-900 mt-1">ElimuSmart Cloud ERP</p>
              </div>
            </div>
          </div>
        )}
