                  {students.map(s => <option key={s.id} value={s.admissionNumber}>{s.admissionNumber} - {s.firstName} {s.lastName}</option>)}
                </select>
              </div>

              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Payment Amount</label>
                 <div className="relative">
                    <span className="absolute left-5 top-5 font-black text-gray-300">KES</span>
                    <input required type="number" value={paymentForm.amount} onChange={e => setPaymentForm({...paymentForm, amount: e.target.value})} className="w-full pl-16 pr-6 py-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black text-xl outline-none focus:border-blue-500 focus:bg-white transition-all" placeholder="0.00" />
                 </div>
              </div>

              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Settlement Method</label>
                 <div className="flex gap-3 bg-gray-100 p-2 rounded-[28px]">
                  {['M-PESA', 'BANK', 'CASH'].map(m => (
                    <button key={m} type="button" onClick={() => setPaymentForm({...paymentForm, method: m})} className={`flex-1 py-4 rounded-[22px] text-[10px] font-black uppercase tracking-widest transition-all ${paymentForm.method === m ? 'bg-white text-blue-600 shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>{m}</button>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Transaction Ref (ID)</label>
                 <input value={paymentForm.reference} onChange={e => setPaymentForm({...paymentForm, reference: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all placeholder:text-gray-300" placeholder="e.g. SBR4A6HJ78" />
              </div>
            </div>

            <button type="submit" disabled={isPosting} className="w-full bg-blue-600 text-white py-6 rounded-[32px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 disabled:opacity-50 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-4">
              {isPosting ? <Loader2 className="w-6 h-6 animate-spin" /> : <ShieldAlert className="w-6 h-6" />}
              {isPosting ? 'Finalizing...' : 'Authorize Transaction'}
            </button>
          </form>
        </div>
      )}

      {/* Receipt Preview Modal */}
      {showReceipt && lastReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md animate-in fade-in duration-300">
           <div className="bg-white rounded-[40px] w-full max-w-2xl shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between no-print">
                 <div className="flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6 text-green-500" />
                    <h3 className="text-xl font-black uppercase tracking-tighter text-gray-900">Payment Successful</h3>
                 </div>
                 <button onClick={() => setShowReceipt(false)} className="p-2 hover:bg-white rounded-full transition-all text-gray-400">
                    <X className="w-6 h-6" />
                 </button>
              </div>

              <div className="p-10">
                 <div className="p-8 bg-white border-2 border-dashed rounded-3xl mb-8">
                    <div className="text-center mb-6">
                       <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Receipt Preview</p>
                       <h4 className="text-2xl font-black uppercase text-blue-900">ElimuSmart Academy</h4>
                    </div>

                    <div className="space-y-4 text-sm font-medium">
                       <div className="flex justify-between border-b border-gray-50 pb-2">
                          <span className="text-gray-400 uppercase text-[9px] font-black">Reference</span>
                          <span className="font-black text-blue-600">{lastReceipt.receiptNo}</span>
                       </div>
                       <div className="flex justify-between border-b border-gray-50 pb-2">
                          <span className="text-gray-400 uppercase text-[9px] font-black">Learner</span>
                          <span className="font-black text-gray-900">{lastReceipt.studentName}</span>
                       </div>
                       <div className="flex justify-between border-b border-gray-50 pb-2">
                          <span className="text-gray-400 uppercase text-[9px] font-black">Amount Paid</span>
                          <span className="font-black text-green-600">KES {lastReceipt.amount.toLocaleString()}</span>
                       </div>
                       <div className="flex justify-between border-b border-gray-50 pb-2">
                          <span className="text-gray-400 uppercase text-[9px] font-black">Current Balance</span>
                          <span className={`font-black ${lastReceipt.balance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                            KES {lastReceipt.balance.toLocaleString()}
                          </span>
                       </div>
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <button 
                      onClick={() => exportToPDF('receipt-print-template', `Receipt_${lastReceipt.receiptNo}.pdf`)}
                      className="flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-4 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-200 transition-all"
                    >
                      <Download className="w-4 h-4" /> Save PDF
                    </button>
                    <button 
                      onClick={() => printElement('receipt-print-template')}
                      className="flex items-center justify-center gap-2 bg-blue-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100"
                    >
                      <Printer className="w-4 h-4" /> Print Receipt
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, SCHOOL_STREAMS, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: 'Oak',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: 'Oak',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: Math.max(0, fee - (formData.paidFee || 0)),
      prepaidFee: (formData.paidFee || 0) > fee ? (formData.paidFee || 0) - fee : 0
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
        feeBalance: (formData.totalFee || 0) - (formData.paidFee || 0)
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you absolutely sure you want to delete this student record? This action cannot be undone.')) {
      setStudents(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || 'Oak',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest">{student.class} • {student.stream}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      KES {student.feeBalance.toLocaleString()}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2">
                      <button onClick={() => openModal(student)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 className="w-4 h-4" /></button>
                      <button onClick={() => handleDelete(student.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 className="w-4 h-4" /></button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSave} className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                   <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                   <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                   <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                   <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                  </select>
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                   <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                    {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                   <select value={formData.stream} onChange={e => setFormData({...formData, stream: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                    {SCHOOL_STREAMS.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                   <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                   <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                </div>
              </div>
              <div className="p-6 bg-blue-50 rounded-[32px] border border-blue-100 shadow-inner flex items-center justify-between">
                <div>
                   <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Financial Linkage</p>
                   <p className="text-xs font-bold text-gray-600 italic">Termly fee calculated for {formData.class}</p>
                </div>
                <div className="text-right">
                  <span className="text-[10px] font-black text-blue-400 uppercase mr-2">Total</span>
                  <span className="text-xl font-black text-blue-900 tracking-tighter">KES {formData.totalFee?.toLocaleString()}</span>
                </div>
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[24px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all">
                {editingStudent ? 'Update Profile' : 'Confirm Enrollment'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useMemo } from 'react';
import { 
  Users, 
  TrendingUp, 
  CheckCircle, 
  Clock,
  ArrowUpRight,
  ArrowDownRight,
  AlertCircle,
  Banknote,
  Target,
  Forward
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { User, Student } from '../types';
import { Language, translations } from '../services/localizationService';

interface DashboardProps {
  user: User;
  lang: Language;
  students: Student[];
}

