                       <div className="flex justify-between border-b pb-2"><span className="text-gray-400 uppercase text-[9px] font-black">Ref</span><span className="font-black text-blue-600">{lastReceipt.receiptNo}</span></div>
                       <div className="flex justify-between border-b pb-2"><span className="text-gray-400 uppercase text-[9px] font-black">Learner</span><span className="font-black text-gray-900">{lastReceipt.studentName}</span></div>
                       <div className="flex justify-between border-b pb-2"><span className="text-gray-400 uppercase text-[9px] font-black">Paid</span><span className="font-black text-green-600">KES {lastReceipt.amount.toLocaleString()}</span></div>
