                       <h4 className="text-2xl font-black uppercase text-blue-900">ElimuSmart Academy</h4>
                       <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Digital Payment Confirmation</p>
                    </div>
                    <div className="space-y-4">
                       <div className="flex justify-between border-b pb-2"><span className="text-gray-400 uppercase text-[9px] font-black">Receipt No</span><span className="font-black text-red-600">{lastReceipt.receiptNo}</span></div>
                       <div className="flex justify-between border-b pb-2"><span className="text-gray-400 uppercase text-[9px] font-black">Learner</span><span className="font-black text-gray-900">{lastReceipt.studentName}</span></div>
                       <div className="flex justify-between border-b pb-2"><span className="text-gray-400 uppercase text-[9px] font-black">Method</span><span className="font-black text-blue-600">{lastReceipt.method} • {lastReceipt.reference}</span></div>
                       <div className="flex justify-between items-center"><span className="text-gray-400 uppercase text-[9px] font-black">Paid</span><span className="font-black text-2xl text-green-600">KES {lastReceipt.amount.toLocaleString()}</span></div>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => exportToPDF('receipt-print-template', `Receipt_${lastReceipt.receiptNo}.pdf`)} className="flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-4 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-200 transition-all"><Download className="w-4 h-4" /> Save PDF</button>
