                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Amount Credited</p>
                    <h4 className="text-4xl font-black text-gray-900 leading-none">KES {lastReceipt.amount.toLocaleString()}.00</h4>
                    <div className="mt-6 flex flex-col items-center">
                       <p className="text-sm font-black text-blue-600 uppercase tracking-tighter">{lastReceipt.studentName}</p>
                       <span className="text-[9px] font-black text-gray-400 uppercase mt-2 tracking-widest">Receipt ID: {lastReceipt.receiptNo}</span>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => exportToPDF('receipt-print-template', `Receipt_${lastReceipt.receiptNo}.pdf`)} className="flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-200 transition-all"><Download size={18} /> Save PDF</button>
                    <button onClick={() => window.print()} className="flex items-center justify-center gap-2 bg-blue-600 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100"><Printer size={18} /> Print Now</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
