import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle,
  Banknote
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: '',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: '',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    const currentPaid = formData.paidFee || 0;
    const newBalance = Math.max(0, fee - currentPaid);
    const newPrepaid = currentPaid > fee ? currentPaid - fee : 0;

    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleInitialPaymentChange = (val: string) => {
    const paid = parseFloat(val) || 0;
    const total = formData.totalFee || 0;
    const newBalance = Math.max(0, total - paid);
    const newPrepaid = paid > total ? paid - total : 0;

    setFormData({ 
      ...formData, 
      paidFee: paid, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  /**
   * FIXED DELETE LOGIC
   * 1. Uses e.stopPropagation() to prevent unintended row clicks.
   * 2. Uses a robust ID check (string conversion to be safe).
   * 3. Functional state update ensures sync with App.tsx and localStorage.
   */
  const handleDelete = (idToDelete: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    if (!idToDelete) return;

    const confirmMsg = "CRITICAL ACTION: Are you sure you want to delete this student record? This action is permanent and will remove all linked academic and financial data.";

    if (window.confirm(confirmMsg)) {
      setStudents((currentStudents) => {
        const updatedList = currentStudents.filter(s => String(s.id) !== String(idToDelete));
        return [...updatedList]; 
      });

      // Clear editing state if the deleted student was being edited
      if (editingStudent && editingStudent.id === idToDelete) {
        setEditingStudent(null);
        setIsModalOpen(false);
      }
    }
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance,
      'Prepaid': rest.prepaidFee
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || '',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" alt="Student" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest">{student.class} {student.stream && `• ${student.stream}`}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {student.prepaidFee > 0 ? `+KES ${student.prepaidFee.toLocaleString()}` : `KES ${student.feeBalance.toLocaleString()}`}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        onClick={() => openModal(student)} 
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors border border-transparent hover:border-blue-200"
                        title="Edit Student"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={(e) => handleDelete(student.id, e)} 
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors border border-transparent hover:border-red-200"
                        title="Delete Student"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between shrink-0">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8">
              <form onSubmit={handleSave} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                     <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                     <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                     <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                     <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                     <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                     <input 
                       required 
                       value={formData.stream} 
                       onChange={e => setFormData({...formData, stream: e.target.value})} 
                       className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold uppercase" 
                       placeholder="e.g. Oak, Palm, Eagle" 
                     />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                     <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                     <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                  </div>
                </div>

                <div className="space-y-4 pt-4">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] border-b pb-2">Financial Setup</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Payment Received</label>
                      <div className="relative">
                        <Banknote className="absolute left-4 top-4 text-gray-400 w-5 h-5" />
                        <input 
                          type="number" 
                          value={formData.paidFee} 
                          onChange={e => handleInitialPaymentChange(e.target.value)} 
                          className="w-full pl-12 p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" 
                          placeholder="0.00" 
                        />
                      </div>
                    </div>
                    <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100 flex flex-col justify-center">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-sm font-black text-blue-900">KES {formData.totalFee?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">{formData.prepaidFee! > 0 ? 'Prepaid Credit' : 'Balance Due'}</span>
                        <span className={`text-sm font-black ${formData.prepaidFee! > 0 ? 'text-green-600' : 'text-red-600'}`}>
                          KES {formData.prepaidFee! > 0 ? formData.prepaidFee?.toLocaleString() : formData.feeBalance?.toLocaleString()}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[24px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all">
                  {editingStudent ? 'Update Profile' : 'Confirm Enrollment'}
                </button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle,
  Banknote
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: '',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: '',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    const currentPaid = formData.paidFee || 0;
    const newBalance = Math.max(0, fee - currentPaid);
    const newPrepaid = currentPaid > fee ? currentPaid - fee : 0;

    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleInitialPaymentChange = (val: string) => {
    const paid = parseFloat(val) || 0;
    const total = formData.totalFee || 0;
    const newBalance = Math.max(0, total - paid);
    const newPrepaid = paid > total ? paid - total : 0;

    setFormData({ 
      ...formData, 
      paidFee: paid, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  /**
   * REFINED DELETE LOGIC
   * 1. Direct confirmation check.
   * 2. Atomic state update using functional setState.
   * 3. Stop propagation to ensure row click (if any) doesn't fire.
   */
  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();

    if (window.confirm("Are you sure you want to delete this student record? This action cannot be undone.")) {
      setStudents(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance,
      'Prepaid': rest.prepaidFee
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || '',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight text-shadow-sm">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium shadow-inner" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" alt="Student" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">{student.class} {student.stream && `• ${student.stream}`}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {student.prepaidFee > 0 ? `+KES ${student.prepaidFee.toLocaleString()}` : `KES ${student.feeBalance.toLocaleString()}`}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2 relative z-10">
                      <button 
                        onClick={() => openModal(student)} 
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-all border border-transparent hover:border-blue-100 active:scale-90"
                        title="Edit Student"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={(e) => handleDelete(student.id, e)} 
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-all border border-transparent hover:border-red-100 active:scale-90"
                        title="Delete Student"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between shrink-0">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8">
              <form onSubmit={handleSave} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                     <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                     <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                     <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                     <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                     <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                     <input 
                       required 
                       value={formData.stream} 
                       onChange={e => setFormData({...formData, stream: e.target.value})} 
                       className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold uppercase" 
                       placeholder="e.g. Oak, Palm, Eagle" 
                     />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                     <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                     <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                  </div>
                </div>

                <div className="space-y-4 pt-4">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] border-b pb-2">Financial Setup</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Payment Received</label>
                      <div className="relative">
                        <Banknote className="absolute left-4 top-4 text-gray-400 w-5 h-5" />
                        <input 
                          type="number" 
                          value={formData.paidFee} 
                          onChange={e => handleInitialPaymentChange(e.target.value)} 
                          className="w-full pl-12 p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" 
                          placeholder="0.00" 
                        />
                      </div>
                    </div>
                    <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100 flex flex-col justify-center shadow-inner">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-sm font-black text-blue-900">KES {formData.totalFee?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">{formData.prepaidFee! > 0 ? 'Prepaid Credit' : 'Balance Due'}</span>
                        <span className={`text-sm font-black ${formData.prepaidFee! > 0 ? 'text-green-600' : 'text-red-600'}`}>
                          KES {formData.prepaidFee! > 0 ? formData.prepaidFee?.toLocaleString() : formData.feeBalance?.toLocaleString()}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[24px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all">
                  {editingStudent ? 'Update Profile' : 'Confirm Enrollment'}
                </button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle,
  Banknote
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: '',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: '',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    const currentPaid = formData.paidFee || 0;
    const newBalance = Math.max(0, fee - currentPaid);
    const newPrepaid = currentPaid > fee ? currentPaid - fee : 0;

    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleInitialPaymentChange = (val: string) => {
    const paid = parseFloat(val) || 0;
    const total = formData.totalFee || 0;
    const newBalance = Math.max(0, total - paid);
    const newPrepaid = paid > total ? paid - total : 0;

    setFormData({ 
      ...formData, 
      paidFee: paid, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Stop event bubbling to row clicks
    if (window.confirm("Are you sure you want to delete this student record? This action cannot be undone and will affect financial reports.")) {
      setStudents(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance,
      'Prepaid': rest.prepaidFee
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || '',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight text-shadow-sm">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium shadow-inner" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" alt="Student" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">{student.class} {student.stream && `• ${student.stream}`}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {student.prepaidFee > 0 ? `+KES ${student.prepaidFee.toLocaleString()}` : `KES ${student.feeBalance.toLocaleString()}`}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        onClick={() => openModal(student)} 
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-all border border-transparent hover:border-blue-100 active:scale-90"
                        title="Edit Student"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={(e) => handleDelete(student.id, e)} 
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-all border border-transparent hover:border-red-100 active:scale-90"
                        title="Delete Student"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between shrink-0">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8">
              <form onSubmit={handleSave} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                     <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                     <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                     <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                     <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                     <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                     <input 
                       required 
                       value={formData.stream} 
                       onChange={e => setFormData({...formData, stream: e.target.value})} 
                       className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold uppercase" 
                       placeholder="e.g. Oak, Palm, Eagle" 
                     />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                     <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                     <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                  </div>
                </div>

                <div className="space-y-4 pt-4">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] border-b pb-2">Financial Setup</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Payment Received</label>
                      <div className="relative">
                        <Banknote className="absolute left-4 top-4 text-gray-400 w-5 h-5" />
                        <input 
                          type="number" 
                          value={formData.paidFee} 
                          onChange={e => handleInitialPaymentChange(e.target.value)} 
                          className="w-full pl-12 p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" 
                          placeholder="0.00" 
                        />
                      </div>
                    </div>
                    <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100 flex flex-col justify-center shadow-inner">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-sm font-black text-blue-900">KES {formData.totalFee?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">{formData.prepaidFee! > 0 ? 'Prepaid Credit' : 'Balance Due'}</span>
                        <span className={`text-sm font-black ${formData.prepaidFee! > 0 ? 'text-green-600' : 'text-red-600'}`}>
                          KES {formData.prepaidFee! > 0 ? formData.prepaidFee?.toLocaleString() : formData.feeBalance?.toLocaleString()}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[24px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all">
                  {editingStudent ? 'Update Profile' : 'Confirm Enrollment'}
                </button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  AlertCircle, 
  Loader2, 
  Printer, 
  Download, 
  LayoutGrid, 
  Target, 
  Banknote, 
  Forward, 
  CreditCard, 
  Settings2, 
  Save, 
  ShieldAlert, 
  Zap, 
  X, 
  CheckCircle2, 
  FileDown,
  Building,
  User,
  Hash,
  Stamp,
  Smartphone,
  Check,
  ShieldCheck,
  Search,
  FileSpreadsheet
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
  setFeeStructure: React.Dispatch<React.SetStateAction<ClassFee[]>>;
  schoolLogo: string | null;
}

interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: 'M-PESA' | 'BANK' | 'CASH';
  reference: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, feeStructure, setFeeStructure, schoolLogo }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [financeSearch, setFinanceSearch] = useState('');
  const [isPosting, setIsPosting] = useState(false);
  const [isApplyingFees, setIsApplyingFees] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);

  const [globalFeeValue, setGlobalFeeValue] = useState<string>('');
  const [paymentForm, setPaymentForm] = useState({ 
    adm: '', 
    amount: '', 
    method: 'M-PESA' as 'M-PESA' | 'BANK' | 'CASH', 
    reference: '' 
  });

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const matchesClass = selectedClass === 'All Classes' || s.class === selectedClass;
      const matchesSearch = `${s.firstName} ${s.lastName} ${s.admissionNumber}`.toLowerCase().includes(financeSearch.toLowerCase());
      return matchesClass && matchesSearch;
    });
  }, [students, selectedClass, financeSearch]);

  const financeStats = useMemo(() => {
    const totalExpected = filteredStudents.reduce((sum, s) => sum + (s.totalFee || 0), 0);
    const totalCollected = filteredStudents.reduce((sum, s) => sum + (s.paidFee || 0), 0);
    const totalOutstanding = filteredStudents.reduce((sum, s) => sum + (s.feeBalance || 0), 0);
    const totalPrepaid = filteredStudents.reduce((sum, s) => sum + (s.prepaidFee || 0), 0);
    return { expected: totalExpected, collected: totalCollected, outstanding: totalOutstanding, prepaid: totalPrepaid };
  }, [filteredStudents]);

  const handleUpdateClassFee = (className: string, value: string) => {
    const amount = parseFloat(value) || 0;
    setFeeStructure(prev => prev.map(f => f.className === className ? { ...f, amount } : f));
  };

  const applyGlobalFee = () => {
    const amount = parseFloat(globalFeeValue) || 0;
    if (amount <= 0) return;
    setFeeStructure(prev => prev.map(f => ({ ...f, amount })));
    setGlobalFeeValue('');
  };

  const syncFeesToStudents = async () => {
    setIsApplyingFees(true);
    await new Promise(r => setTimeout(r, 1200));

    setStudents(prev => prev.map(student => {
      const structure = feeStructure.find(f => f.className === student.class);
      if (structure) {
        const newTotal = structure.amount;
        const paid = student.paidFee || 0;
        let newBalance = newTotal - paid;
        let newPrepaid = 0;
        if (newBalance < 0) {
          newPrepaid = Math.abs(newBalance);
          newBalance = 0;
        }
        return { ...student, totalFee: newTotal, feeBalance: newBalance, prepaidFee: newPrepaid };
      }
      return student;
    }));

    setIsApplyingFees(false);
    alert('Synchronization Successful! All student balances recalculated based on the updated Class Fee Structure.');
  };

  const handlePostPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentForm.adm || !paymentForm.amount) return;
    setIsPosting(true);

    await new Promise(r => setTimeout(r, 800));

    const amountNum = parseFloat(paymentForm.amount);
    let updatedStudent: Student | undefined;

    setStudents(prev => prev.map(s => {
      if (s.admissionNumber === paymentForm.adm) {
        const newPaid = (s.paidFee || 0) + amountNum;
        let newBalance = (s.totalFee || 0) - newPaid;
        let newPrepaid = s.prepaidFee || 0;
        if (newBalance < 0) {
          newPrepaid += Math.abs(newBalance);
          newBalance = 0;
        }
        updatedStudent = { ...s, paidFee: newPaid, feeBalance: newBalance, prepaidFee: newPrepaid };
        return updatedStudent;
      }
      return s;
    }));

    if (updatedStudent) {
      const receipt: TransactionReceipt = {
        receiptNo: `RCP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        studentName: `${updatedStudent.firstName} ${updatedStudent.lastName}`,
        adm: updatedStudent.admissionNumber,
        class: updatedStudent.class,
        amount: amountNum,
        method: paymentForm.method,
        reference: paymentForm.reference || 'CASH_ENTRY',
        date: new Date().toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }),
        balance: updatedStudent.feeBalance,
        servedBy: 'System Admin'
      };
      setLastReceipt(receipt);
      setShowReceipt(true);
    }

    setIsPosting(false);
    setPaymentForm({ adm: '', amount: '', method: 'M-PESA', reference: '' });
  };

  const exportToPDF = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    const h2p = (window as any).html2pdf;
    if (typeof h2p === 'function') {
      h2p().set(opt).from(element).save();
    } else {
      window.print();
    }
  };

  const handleIndividualExportExcel = (student: Student) => {
    const data = [{
      'Admission Number': student.admissionNumber,
      'Name': `${student.firstName} ${student.lastName}`,
      'Class': student.class,
      'Stream': student.stream,
      'Total Termly Invoice': student.totalFee,
      'Total Paid to Date': student.paidFee,
      'Prepaid/Credit': student.prepaidFee,
      'Outstanding Balance': student.feeBalance,
      'Statement Date': new Date().toLocaleDateString()
    }];
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Fee Statement");
    XLSX.writeFile(wb, `FeeStatement_${student.admissionNumber}.xlsx`);
  };

  const handleIndividualExportPDF = (student: Student) => {
    // We repurpose the lastReceipt state to populate the high-fidelity template for PDF generation
    const mockStatement: TransactionReceipt = {
        receiptNo: "STMT-GEN",
        studentName: `${student.firstName} ${student.lastName}`,
        adm: student.admissionNumber,
        class: student.class,
        amount: student.paidFee, // Show cumulative paid as the primary "amount" for statement purposes
        method: "CASH",
        reference: "CUMULATIVE_STATEMENT",
        date: new Date().toLocaleDateString(),
        balance: student.feeBalance,
        servedBy: "Ledger Export"
    };
    setLastReceipt(mockStatement);
    // Give state a moment to render before capturing
    setTimeout(() => {
        exportToPDF('receipt-print-template', `FeeStatement_${student.admissionNumber}.pdf`);
    }, 100);
  };

  return (
    <div className="space-y-8 pb-20">
      {/* Hidden high-fidelity template for PDF engine */}
      <div id="receipt-print-template" className="offscreen-template">
        {lastReceipt && (
          <div style={{ padding: '40px', background: 'white', color: 'black', fontFamily: 'Inter, sans-serif' }}>
            <div style={{ borderBottom: '2px solid #1e3a8a', paddingBottom: '20px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h1 style={{ margin: '0', fontSize: '24px', fontWeight: 'bold', color: '#1e3a8a' }}>ElimuSmart Academy</h1>
                <p style={{ margin: '5px 0', fontSize: '12px' }}>P.O BOX 1234 - 00100, Nairobi | Tel: +254 700 000 000</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Official Fee Document</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '18px' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Fee Statement' : 'Payment Receipt'}</h2>
                <p style={{ margin: '5px 0', fontWeight: 'bold' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Date: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ marginBottom: '30px' }}>
              <p><strong>Student Name:</strong> {lastReceipt.studentName}</p>
              <p><strong>ADM Number:</strong> {lastReceipt.adm}</p>
              <p><strong>Class:</strong> {lastReceipt.class}</p>
            </div>

            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '30px' }}>
              <thead>
                <tr style={{ background: '#f3f4f6' }}>
                  <th style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'left' }}>Description</th>
                  <th style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'right' }}>Amount (KES)</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>
                    {lastReceipt.receiptNo.startsWith('STMT') ? 'Total Tuition Fees Invoiced' : 'School Fees Payment Settlement'}
                    <br/><small>Ref: {lastReceipt.reference}</small>
                  </td>
                  <td style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'right' }}>{lastReceipt.amount.toLocaleString()}.00</td>
                </tr>
              </tbody>
            </table>

            <div style={{ textAlign: 'right', marginBottom: '50px' }}>
              <p style={{ fontSize: '18px', fontWeight: 'bold' }}>Remaining Balance: KES {lastReceipt.balance.toLocaleString()}.00</p>
            </div>

            <div style={{ borderTop: '1px solid #ddd', paddingTop: '20px', display: 'flex', justifyContent: 'space-between' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '150px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px' }}>Served By: {lastReceipt.servedBy}</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '150px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px' }}>School Official Stamp</p>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Finance Center</h1>
          <p className="text-gray-500 font-medium">Automatic billing and student ledger management.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="p-3 bg-white border-2 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-500 transition-all">
            <option>All Classes</option>
            {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
          </select>
          <div className="flex p-1 bg-gray-100 rounded-2xl shadow-inner">
            <button onClick={() => setActiveTab('class-summary')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Ledger</button>
            <button onClick={() => setActiveTab('fee-structure')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'fee-structure' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Fee Settings</button>
            <button onClick={() => setActiveTab('payments')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Post Receipt</button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: 'Expected Revenue', value: financeStats.expected, icon: Target, color: 'indigo' },
          { label: 'Amount Collected', value: financeStats.collected, icon: Banknote, color: 'green' },
          { label: 'Outstanding Debt', value: financeStats.outstanding, icon: AlertCircle, color: 'red' },
          { label: 'Credit Balance', value: financeStats.prepaid, icon: Forward, color: 'blue' },
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-gray-100 flex items-start justify-between shadow-sm hover:shadow-md transition-shadow">
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none mb-2">{stat.label}</p>
              <h3 className={`text-2xl font-black tracking-tight ${stat.color === 'red' ? 'text-red-700' : stat.color === 'green' ? 'text-green-700' : 'text-gray-900'}`}>
                <span className="text-xs font-medium mr-1 opacity-40">KES</span>
                {stat.value.toLocaleString()}
              </h3>
            </div>
            <div className={`p-3 rounded-2xl bg-${stat.color}-50 text-${stat.color}-600 border border-${stat.color}-100`}>
              <stat.icon className="w-5 h-5" />
            </div>
          </div>
        ))}
      </div>

      {activeTab === 'class-summary' && (
        <div className="bg-white rounded-[40px] border border-gray-100 overflow-hidden shadow-sm animate-in fade-in duration-300">
          <div className="p-8 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
             <div className="flex-1 flex items-center gap-4">
                <div className="relative flex-1 max-w-sm">
                   <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
                   <input 
                      type="text" 
                      placeholder="Search ledger by name or ADM..." 
                      value={financeSearch}
                      onChange={(e) => setFinanceSearch(e.target.value)}
                      className="w-full pl-10 pr-4 py-2.5 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-medium transition-all text-sm"
                   />
                </div>
             </div>
             <button onClick={() => exportToPDF('class-ledger-table', `Ledger_${selectedClass}.pdf`)} className="p-3 bg-white border border-gray-200 rounded-2xl text-gray-400 hover:text-blue-600 hover:border-blue-200 transition-all flex items-center gap-2 font-black uppercase text-[10px] tracking-widest shadow-sm">
                <Download className="w-4 h-4" /> Export Global Ledger
             </button>
          </div>
          <div className="overflow-x-auto" id="class-ledger-table">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                  <th className="px-8 py-6">Student Information</th>
                  <th className="px-8 py-6 text-center">Invoiced</th>
                  <th className="px-8 py-6 text-center">Paid</th>
                  <th className="px-8 py-6 text-center">Balance</th>
                  <th className="px-8 py-6 text-right">Statements</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filteredStudents.map((s, idx) => (
                  <tr key={idx} className="hover:bg-blue-50/10 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="font-black text-gray-900 text-lg leading-tight">{s.firstName} {s.lastName}</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">{s.admissionNumber} • {s.class}</div>
                    </td>
                    <td className="px-8 py-6 text-center font-bold text-gray-700">KES {(s.totalFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-bold text-green-600">KES {(s.paidFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-black">
                       <span className={s.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}>
                         KES {(s.feeBalance || 0).toLocaleString()}
                       </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleIndividualExportExcel(s)}
                          className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all"
                          title="Export Excel Ledger"
                        >
                          <FileSpreadsheet className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => handleIndividualExportPDF(s)}
                          className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                          title="Generate PDF Statement"
                        >
                          <FileDown className="w-5 h-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredStudents.length === 0 && (
                  <tr>
                    <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest">No matching student ledger entries found.</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'fee-structure' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="lg:col-span-2 bg-white rounded-[40px] border border-gray-100 shadow-sm overflow-hidden">
             <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                <div>
                   <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Billing Structure</h3>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Set Tuition per Class</p>
                </div>
                <div className="flex items-center gap-2">
                   <input type="number" placeholder="Global Fee..." value={globalFeeValue} onChange={e => setGlobalFeeValue(e.target.value)} className="w-32 p-3 bg-white border rounded-xl font-bold text-xs" />
                   <button onClick={applyGlobalFee} className="p-3 bg-gray-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm">Apply All</button>
                </div>
             </div>
             <div className="divide-y divide-gray-100 max-h-[600px] overflow-y-auto">
                {feeStructure.map((fee, idx) => (
                  <div key={idx} className="p-6 flex items-center justify-between hover:bg-gray-50 transition-colors">
                     <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black">{idx + 1}</div>
                        <span className="font-black text-gray-800">{fee.className}</span>
                     </div>
                     <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-gray-400 uppercase">KES</span>
                        <input 
                          type="number" 
                          value={fee.amount} 
                          onChange={e => handleUpdateClassFee(fee.className, e.target.value)} 
                          className="w-32 p-3 bg-gray-100 border-2 border-transparent rounded-xl text-center font-black focus:border-blue-500 focus:bg-white transition-all outline-none shadow-inner" 
                        />
                     </div>
                  </div>
                ))}
             </div>
          </div>

          <div className="space-y-6">
             <div className="bg-indigo-900 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden group">
                <div className="absolute -right-8 -bottom-8 opacity-10 group-hover:scale-110 transition-transform">
                  <Zap className="w-48 h-48" />
                </div>
                <div className="relative z-10">
                   <h4 className="text-2xl font-black uppercase tracking-tighter mb-3">Sync Global Invoices</h4>
                   <p className="text-indigo-100/70 font-medium text-sm leading-relaxed mb-8 italic">
                     Clicking sync will instantly update the fee records of all {students.length} students to match these new values.
                   </p>
                   <button 
                    onClick={syncFeesToStudents}
                    disabled={isApplyingFees}
                    className="w-full bg-green-500 text-white py-5 rounded-3xl font-black uppercase tracking-widest hover:bg-green-600 transition-all shadow-xl shadow-green-900/40 disabled:opacity-50 flex items-center justify-center gap-3"
                   >
                     {isApplyingFees ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="v-5 h-5" />}
                     Sync Billing Records
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="max-w-4xl mx-auto bg-white p-12 rounded-[56px] border-2 border-gray-100 shadow-2xl animate-in zoom-in duration-500 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-12 opacity-[0.03] pointer-events-none">
             <Smartphone size={200} />
          </div>
          <div className="mb-10 flex items-center gap-6">
             <div className="p-5 bg-blue-600 text-white rounded-[28px] shadow-2xl shadow-blue-200">
                <CreditCard className="w-10 h-10" />
             </div>
             <div>
               <h2 className="text-4xl font-black text-gray-900 uppercase tracking-tighter leading-none">Post Receipt</h2>
               <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] mt-3">M-Pesa / Bank Terminal</p>
             </div>
          </div>

          <form onSubmit={handlePostPayment} className="space-y-10 relative z-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><User className="w-3 h-3" /> Select Learner</label>
                 <select required value={paymentForm.adm} onChange={e => setPaymentForm({...paymentForm, adm: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner">
                  <option value="">ADM Number...</option>
                  {students.map(s => <option key={s.id} value={s.admissionNumber}>{s.admissionNumber} - {s.firstName} {s.lastName}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><Banknote className="w-3 h-3" /> Amount (KES)</label>
                 <input required type="number" value={paymentForm.amount} onChange={e => setPaymentForm({...paymentForm, amount: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black text-xl outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="0.00" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Method</label>
                 <div className="grid grid-cols-3 gap-2 p-2 bg-gray-100 rounded-[24px] shadow-inner">
                    {['M-PESA', 'BANK', 'CASH'].map(m => (
                      <button key={m} type="button" onClick={() => setPaymentForm({...paymentForm, method: m as any})} className={`py-4 rounded-[20px] text-[10px] font-black uppercase transition-all ${paymentForm.method === m ? 'bg-white text-blue-600 shadow-xl' : 'text-gray-400'}`}>{m}</button>
                    ))}
                 </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><Hash className="w-3 h-3" /> Reference Code</label>
                 <input value={paymentForm.reference} onChange={e => setPaymentForm({...paymentForm, reference: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="e.g. SBR4A6HJ78" />
              </div>
            </div>
            <button type="submit" disabled={isPosting} className="w-full bg-blue-600 text-white py-6 rounded-[32px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 disabled:opacity-50 hover:bg-blue-700 transition-all flex items-center justify-center gap-4">
              {isPosting ? <Loader2 className="w-6 h-6 animate-spin" /> : <ShieldAlert className="w-6 h-6" />}
              {isPosting ? 'POSTING...' : 'AUTHORIZE & PRINT'}
            </button>
          </form>
        </div>
      )}

      {/* Success Modal */}
      {showReceipt && lastReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md animate-in fade-in duration-300">
           <div className="bg-white rounded-[40px] w-full max-w-2xl shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between no-print">
                 <div className="flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6 text-green-500" />
                    <h3 className="text-xl font-black uppercase tracking-tighter text-gray-900">Payment Processed</h3>
                 </div>
                 <button onClick={() => setShowReceipt(false)} className="p-2 hover:bg-white rounded-full transition-all text-gray-400"><X className="w-6 h-6" /></button>
              </div>
              <div className="p-10 text-center">
                 <div className="p-10 bg-gray-50 border-4 border-dashed border-gray-200 rounded-[40px] mb-10 shadow-inner">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Amount Credited</p>
                    <h4 className="text-4xl font-black text-gray-900 leading-none">KES {lastReceipt.amount.toLocaleString()}.00</h4>
                    <div className="mt-6 flex flex-col items-center">
                       <p className="text-sm font-black text-blue-600 uppercase tracking-tighter">{lastReceipt.studentName}</p>
                       <span className="text-[9px] font-black text-gray-400 uppercase mt-2 tracking-widest">Receipt ID: {lastReceipt.receiptNo}</span>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => exportToPDF('receipt-print-template', `Receipt_${lastReceipt.receiptNo}.pdf`)} className="flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-200 transition-all shadow-sm border border-gray-100"><Download size={18} /> Save PDF</button>
                    <button onClick={() => window.print()} className="flex items-center justify-center gap-2 bg-blue-600 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 border border-blue-500"><Printer size={18} /> Print Now</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle,
  Banknote
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: '',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: '',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    const currentPaid = formData.paidFee || 0;
    const newBalance = Math.max(0, fee - currentPaid);
    const newPrepaid = currentPaid > fee ? currentPaid - fee : 0;

    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleInitialPaymentChange = (val: string) => {
    const paid = parseFloat(val) || 0;
    const total = formData.totalFee || 0;
    const newBalance = Math.max(0, total - paid);
    const newPrepaid = paid > total ? paid - total : 0;

    setFormData({ 
      ...formData, 
      paidFee: paid, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  // REFIXED: Robust Delete Logic
  const deleteStudent = (id: string, e: React.MouseEvent) => {
    // 1. Isolation: Stop event from triggering parent interactions
    e.preventDefault();
    e.stopPropagation();

    // 2. Verification: User Intent
    const confirmed = window.confirm(
      "CRITICAL: Are you sure you want to delete this student record? This will permanently remove all linked academic and financial data from the local database."
    );

    if (confirmed) {
      // 3. Execution: Functional state update ensures React 19 sync
      setStudents(prevStudents => {
        const updatedList = prevStudents.filter(s => String(s.id) !== String(id));
        return updatedList;
      });
    }
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance,
      'Prepaid': rest.prepaidFee
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || '',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight text-shadow-sm">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            type="button"
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            type="button"
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium shadow-inner" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" alt="Student" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">{student.class} {student.stream && `• ${student.stream}`}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {student.prepaidFee > 0 ? `+KES ${student.prepaidFee.toLocaleString()}` : `KES ${student.feeBalance.toLocaleString()}`}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        onClick={() => openModal(student)} 
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-all border border-transparent hover:border-blue-100 active:scale-90"
                        title="Edit Student"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        onClick={(e) => deleteStudent(student.id, e)} 
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-all border border-transparent hover:border-red-100 active:scale-90"
                        title="Delete Student"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between shrink-0">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8">
              <form onSubmit={handleSave} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                     <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                     <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                     <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                     <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                     <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                     <input 
                       required 
                       value={formData.stream} 
                       onChange={e => setFormData({...formData, stream: e.target.value})} 
                       className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold uppercase" 
                       placeholder="e.g. Oak, Palm, Eagle" 
                     />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                     <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                     <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                  </div>
                </div>

                <div className="space-y-4 pt-4">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] border-b pb-2">Financial Setup</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Payment Received</label>
                      <div className="relative">
                        <Banknote className="absolute left-4 top-4 text-gray-400 w-5 h-5" />
                        <input 
                          type="number" 
                          value={formData.paidFee} 
                          onChange={e => handleInitialPaymentChange(e.target.value)} 
                          className="w-full pl-12 p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" 
                          placeholder="0.00" 
                        />
                      </div>
                    </div>
                    <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100 flex flex-col justify-center shadow-inner">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-sm font-black text-blue-900">KES {formData.totalFee?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">{formData.prepaidFee! > 0 ? 'Prepaid Credit' : 'Balance Due'}</span>
                        <span className={`text-sm font-black ${formData.prepaidFee! > 0 ? 'text-green-600' : 'text-red-600'}`}>
                          KES {formData.prepaidFee! > 0 ? formData.prepaidFee?.toLocaleString() : formData.feeBalance?.toLocaleString()}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[24px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all">
                  {editingStudent ? 'Update Profile' : 'Confirm Enrollment'}
                </button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  AlertCircle, 
  Loader2, 
  Printer, 
  Download, 
  LayoutGrid, 
  Target, 
  Banknote, 
  Forward, 
  CreditCard, 
  Settings2, 
  Save, 
  ShieldAlert, 
  Zap, 
  X, 
  CheckCircle2, 
  FileDown,
  Building,
  User,
  Hash,
  Stamp,
  Smartphone,
  Check,
  ShieldCheck,
  Search,
  FileSpreadsheet,
  ArrowRight
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
  setFeeStructure: React.Dispatch<React.SetStateAction<ClassFee[]>>;
  schoolLogo: string | null;
}

interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: 'M-PESA' | 'BANK' | 'CASH';
  reference: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, feeStructure, setFeeStructure, schoolLogo }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [financeSearch, setFinanceSearch] = useState('');
  const [isPosting, setIsPosting] = useState(false);
  const [isApplyingFees, setIsApplyingFees] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);

  const [globalFeeValue, setGlobalFeeValue] = useState<string>('');
  const [paymentForm, setPaymentForm] = useState({ 
    adm: '', 
    amount: '', 
    method: 'M-PESA' as 'M-PESA' | 'BANK' | 'CASH', 
    reference: '' 
  });

  // REFINED: Synchronized filter and search logic
  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const matchesClass = selectedClass === 'All Classes' || s.class === selectedClass;
      const term = financeSearch.toLowerCase();
      const matchesSearch = 
        s.firstName.toLowerCase().includes(term) || 
        s.lastName.toLowerCase().includes(term) || 
        s.admissionNumber.toLowerCase().includes(term);
      return matchesClass && matchesSearch;
    });
  }, [students, selectedClass, financeSearch]);

  const financeStats = useMemo(() => {
    const totalExpected = filteredStudents.reduce((sum, s) => sum + (s.totalFee || 0), 0);
    const totalCollected = filteredStudents.reduce((sum, s) => sum + (s.paidFee || 0), 0);
    const totalOutstanding = filteredStudents.reduce((sum, s) => sum + (s.feeBalance || 0), 0);
    const totalPrepaid = filteredStudents.reduce((sum, s) => sum + (s.prepaidFee || 0), 0);
    return { expected: totalExpected, collected: totalCollected, outstanding: totalOutstanding, prepaid: totalPrepaid };
  }, [filteredStudents]);

  const handleUpdateClassFee = (className: string, value: string) => {
    const amount = parseFloat(value) || 0;
    setFeeStructure(prev => prev.map(f => f.className === className ? { ...f, amount } : f));
  };

  const applyGlobalFee = () => {
    const amount = parseFloat(globalFeeValue) || 0;
    if (amount <= 0) return;
    setFeeStructure(prev => prev.map(f => ({ ...f, amount })));
    setGlobalFeeValue('');
  };

  const syncFeesToStudents = async () => {
    setIsApplyingFees(true);
    await new Promise(r => setTimeout(r, 1200));

    setStudents(prev => prev.map(student => {
      const structure = feeStructure.find(f => f.className === student.class);
      if (structure) {
        const newTotal = structure.amount;
        const paid = student.paidFee || 0;
        let newBalance = newTotal - paid;
        let newPrepaid = 0;
        if (newBalance < 0) {
          newPrepaid = Math.abs(newBalance);
          newBalance = 0;
        }
        return { ...student, totalFee: newTotal, feeBalance: newBalance, prepaidFee: newPrepaid };
      }
      return student;
    }));

    setIsApplyingFees(false);
    alert('Synchronization Successful! All student balances recalculated based on the updated Class Fee Structure.');
  };

  const handlePostPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentForm.adm || !paymentForm.amount) return;
    setIsPosting(true);

    await new Promise(r => setTimeout(r, 800));

    const amountNum = parseFloat(paymentForm.amount);
    let updatedStudent: Student | undefined;

    setStudents(prev => prev.map(s => {
      if (s.admissionNumber === paymentForm.adm) {
        const newPaid = (s.paidFee || 0) + amountNum;
        let newBalance = (s.totalFee || 0) - newPaid;
        let newPrepaid = s.prepaidFee || 0;
        if (newBalance < 0) {
          newPrepaid += Math.abs(newBalance);
          newBalance = 0;
        }
        updatedStudent = { ...s, paidFee: newPaid, feeBalance: newBalance, prepaidFee: newPrepaid };
        return updatedStudent;
      }
      return s;
    }));

    if (updatedStudent) {
      const receipt: TransactionReceipt = {
        receiptNo: `RCP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        studentName: `${updatedStudent.firstName} ${updatedStudent.lastName}`,
        adm: updatedStudent.admissionNumber,
        class: updatedStudent.class,
        amount: amountNum,
        method: paymentForm.method,
        reference: paymentForm.reference || 'CASH_ENTRY',
        date: new Date().toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }),
        balance: updatedStudent.feeBalance,
        servedBy: 'System Admin'
      };
      setLastReceipt(receipt);
      setShowReceipt(true);
    }

    setIsPosting(false);
    setPaymentForm({ adm: '', amount: '', method: 'M-PESA', reference: '' });
  };

  const exportToPDF = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    const h2p = (window as any).html2pdf;
    if (typeof h2p === 'function') {
      h2p().set(opt).from(element).save();
    } else {
      window.print();
    }
  };

  const handleIndividualExportExcel = (student: Student) => {
    const data = [{
      'Admission Number': student.admissionNumber,
      'Name': `${student.firstName} ${student.lastName}`,
      'Class': student.class,
      'Stream': student.stream,
      'Total Termly Invoice': student.totalFee,
      'Total Paid to Date': student.paidFee,
      'Prepaid/Credit': student.prepaidFee,
      'Outstanding Balance': student.feeBalance,
      'Statement Date': new Date().toLocaleDateString()
    }];
    const ws = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, ws, "Fee Statement");
    XLSX.writeFile(workbook, `FeeStatement_${student.admissionNumber}.xlsx`);
  };

  const handleIndividualExportPDF = (student: Student) => {
    const mockStatement: TransactionReceipt = {
        receiptNo: "STMT-" + student.admissionNumber,
        studentName: `${student.firstName} ${student.lastName}`,
        adm: student.admissionNumber,
        class: student.class,
        amount: student.paidFee, 
        method: "CASH",
        reference: "TERM_STATEMENT",
        date: new Date().toLocaleDateString(),
        balance: student.feeBalance,
        servedBy: "Ledger Export"
    };
    setLastReceipt(mockStatement);
    setTimeout(() => {
        exportToPDF('receipt-print-template', `FeeStatement_${student.admissionNumber}.pdf`);
    }, 100);
  };

  return (
    <div className="space-y-8 pb-20">
      <div id="receipt-print-template" className="offscreen-template">
        {lastReceipt && (
          <div style={{ padding: '40px', background: 'white', color: 'black', fontFamily: 'Inter, sans-serif' }}>
            <div style={{ borderBottom: '2px solid #1e3a8a', paddingBottom: '20px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h1 style={{ margin: '0', fontSize: '24px', fontWeight: 'bold', color: '#1e3a8a' }}>ElimuSmart Academy</h1>
                <p style={{ margin: '5px 0', fontSize: '12px' }}>P.O BOX 1234 - 00100, Nairobi | Tel: +254 700 000 000</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Official Fee Document</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '18px' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Fee Statement' : 'Payment Receipt'}</h2>
                <p style={{ margin: '5px 0', fontWeight: 'bold' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Date: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ marginBottom: '30px' }}>
              <p><strong>Student Name:</strong> {lastReceipt.studentName}</p>
              <p><strong>ADM Number:</strong> {lastReceipt.adm}</p>
              <p><strong>Class:</strong> {lastReceipt.class}</p>
            </div>

            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '30px' }}>
              <thead>
                <tr style={{ background: '#f3f4f6' }}>
                  <th style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'left' }}>Description</th>
                  <th style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'right' }}>Amount (KES)</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>
                    {lastReceipt.receiptNo.startsWith('STMT') ? 'Total Tuition Fees Invoiced' : 'School Fees Payment Settlement'}
                    <br/><small>Ref: {lastReceipt.reference}</small>
                  </td>
                  <td style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'right' }}>{lastReceipt.amount.toLocaleString()}.00</td>
                </tr>
              </tbody>
            </table>

            <div style={{ textAlign: 'right', marginBottom: '50px' }}>
              <p style={{ fontSize: '18px', fontWeight: 'bold' }}>Remaining Balance: KES {lastReceipt.balance.toLocaleString()}.00</p>
            </div>

            <div style={{ borderTop: '1px solid #ddd', paddingTop: '20px', display: 'flex', justifyContent: 'space-between' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '150px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px' }}>Served By: {lastReceipt.servedBy}</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '150px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px' }}>School Official Stamp</p>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Finance Center</h1>
          <p className="text-gray-500 font-medium">Automatic billing and student ledger management.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="p-3 bg-white border-2 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-500 transition-all shadow-sm">
            <option>All Classes</option>
            {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
          </select>
          <div className="flex p-1 bg-gray-100 rounded-2xl shadow-inner">
            <button onClick={() => setActiveTab('class-summary')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Ledger</button>
            <button onClick={() => setActiveTab('fee-structure')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'fee-structure' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Fee Settings</button>
            <button onClick={() => setActiveTab('payments')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Post Receipt</button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: 'Expected Revenue', value: financeStats.expected, icon: Target, color: 'indigo' },
          { label: 'Amount Collected', value: financeStats.collected, icon: Banknote, color: 'green' },
          { label: 'Outstanding Debt', value: financeStats.outstanding, icon: AlertCircle, color: 'red' },
          { label: 'Credit Balance', value: financeStats.prepaid, icon: Forward, color: 'blue' },
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-gray-100 flex items-start justify-between shadow-sm hover:shadow-md transition-shadow">
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none mb-2">{stat.label}</p>
              <h3 className={`text-2xl font-black tracking-tight ${stat.color === 'red' ? 'text-red-700' : stat.color === 'green' ? 'text-green-700' : 'text-gray-900'}`}>
                <span className="text-xs font-medium mr-1 opacity-40">KES</span>
                {stat.value.toLocaleString()}
              </h3>
            </div>
            <div className={`p-3 rounded-2xl bg-${stat.color}-50 text-${stat.color}-600 border border-${stat.color}-100`}>
              <stat.icon className="w-5 h-5" />
            </div>
          </div>
        ))}
      </div>

      {activeTab === 'class-summary' && (
        <div className="bg-white rounded-[40px] border border-gray-100 overflow-hidden shadow-sm animate-in fade-in duration-300">
          <div className="p-8 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
             <div className="flex-1 flex items-center gap-4">
                <div className="relative flex-1 max-w-sm">
                   <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
                   <input 
                      type="text" 
                      placeholder="Find student by name or ADM..." 
                      value={financeSearch}
                      onChange={(e) => setFinanceSearch(e.target.value)}
                      className="w-full pl-10 pr-4 py-2.5 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-medium transition-all text-sm shadow-inner"
                   />
                </div>
             </div>
             <button onClick={() => exportToPDF('class-ledger-table', `Global_Ledger_${selectedClass}.pdf`)} className="p-3 bg-white border-2 border-gray-100 rounded-2xl text-gray-600 hover:text-blue-600 hover:border-blue-200 transition-all flex items-center gap-2 font-black uppercase text-[10px] tracking-widest shadow-sm">
                <FileSpreadsheet className="w-4 h-4 text-emerald-600" /> Full Class Ledger
             </button>
          </div>
          <div className="overflow-x-auto" id="class-ledger-table">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                  <th className="px-8 py-6">Student Information</th>
                  <th className="px-8 py-6 text-center">Invoiced</th>
                  <th className="px-8 py-6 text-center">Paid</th>
                  <th className="px-8 py-6 text-center">Balance</th>
                  <th className="px-8 py-6 text-right">Statements</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filteredStudents.map((s, idx) => (
                  <tr key={idx} className="hover:bg-blue-50/10 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="font-black text-gray-900 text-lg leading-tight">{s.firstName} {s.lastName}</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">{s.admissionNumber} • {s.class}</div>
                    </td>
                    <td className="px-8 py-6 text-center font-bold text-gray-700">KES {(s.totalFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-bold text-green-600">KES {(s.paidFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-black">
                       <span className={s.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}>
                         KES {(s.feeBalance || 0).toLocaleString()}
                       </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleIndividualExportExcel(s)}
                          className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-transparent hover:border-emerald-100"
                          title="Export Excel Ledger"
                        >
                          <FileSpreadsheet className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => handleIndividualExportPDF(s)}
                          className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-all border border-transparent hover:border-blue-100"
                          title="Generate PDF Statement"
                        >
                          <FileDown className="w-5 h-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredStudents.length === 0 && (
                  <tr>
                    <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest">No matching student records found in current ledger.</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'fee-structure' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="lg:col-span-2 bg-white rounded-[40px] border border-gray-100 shadow-sm overflow-hidden">
             <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                <div>
                   <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Billing Structure</h3>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Set Tuition per Class</p>
                </div>
                <div className="flex items-center gap-2">
                   <input type="number" placeholder="Global Fee..." value={globalFeeValue} onChange={e => setGlobalFeeValue(e.target.value)} className="w-32 p-3 bg-white border rounded-xl font-bold text-xs" />
                   <button onClick={applyGlobalFee} className="p-3 bg-gray-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm">Apply All</button>
                </div>
             </div>
             <div className="divide-y divide-gray-100 max-h-[600px] overflow-y-auto">
                {feeStructure.map((fee, idx) => (
                  <div key={idx} className="p-6 flex items-center justify-between hover:bg-gray-50 transition-colors">
                     <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black">{idx + 1}</div>
                        <span className="font-black text-gray-800">{fee.className}</span>
                     </div>
                     <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-gray-400 uppercase">KES</span>
                        <input 
                          type="number" 
                          value={fee.amount} 
                          onChange={e => handleUpdateClassFee(fee.className, e.target.value)} 
                          className="w-32 p-3 bg-gray-100 border-2 border-transparent rounded-xl text-center font-black focus:border-blue-500 focus:bg-white transition-all outline-none shadow-inner" 
                        />
                     </div>
                  </div>
                ))}
             </div>
          </div>

          <div className="space-y-6">
             <div className="bg-indigo-900 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden group">
                <div className="absolute -right-8 -bottom-8 opacity-10 group-hover:scale-110 transition-transform">
                  <Zap className="w-48 h-48" />
                </div>
                <div className="relative z-10">
                   <h4 className="text-2xl font-black uppercase tracking-tighter mb-3">Sync Global Invoices</h4>
                   <p className="text-indigo-100/70 font-medium text-sm leading-relaxed mb-8 italic">
                     Clicking sync will instantly update the fee records of all {students.length} students to match these new values.
                   </p>
                   <button 
                    onClick={syncFeesToStudents}
                    disabled={isApplyingFees}
                    className="w-full bg-green-500 text-white py-5 rounded-3xl font-black uppercase tracking-widest hover:bg-green-600 transition-all shadow-xl shadow-green-900/40 disabled:opacity-50 flex items-center justify-center gap-3"
                   >
                     {isApplyingFees ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="v-5 h-5" />}
                     Sync Billing Records
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="max-w-4xl mx-auto bg-white p-12 rounded-[56px] border-2 border-gray-100 shadow-2xl animate-in zoom-in duration-500 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-12 opacity-[0.03] pointer-events-none">
             <Smartphone size={200} />
          </div>
          <div className="mb-10 flex items-center gap-6">
             <div className="p-5 bg-blue-600 text-white rounded-[28px] shadow-2xl shadow-blue-200">
                <CreditCard className="w-10 h-10" />
             </div>
             <div>
               <h2 className="text-4xl font-black text-gray-900 uppercase tracking-tighter leading-none">Post Receipt</h2>
               <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] mt-3">M-Pesa / Bank Terminal</p>
             </div>
          </div>

          <form onSubmit={handlePostPayment} className="space-y-10 relative z-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><User className="w-3 h-3" /> Select Learner</label>
                 <select required value={paymentForm.adm} onChange={e => setPaymentForm({...paymentForm, adm: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner">
                  <option value="">ADM Number...</option>
                  {students.map(s => <option key={s.id} value={s.admissionNumber}>{s.admissionNumber} - {s.firstName} {s.lastName}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><Banknote className="w-3 h-3" /> Amount (KES)</label>
                 <input required type="number" value={paymentForm.amount} onChange={e => setPaymentForm({...paymentForm, amount: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black text-xl outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="0.00" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Method</label>
                 <div className="grid grid-cols-3 gap-2 p-2 bg-gray-100 rounded-[24px] shadow-inner">
                    {['M-PESA', 'BANK', 'CASH'].map(m => (
                      <button key={m} type="button" onClick={() => setPaymentForm({...paymentForm, method: m as any})} className={`py-4 rounded-[20px] text-[10px] font-black uppercase transition-all ${paymentForm.method === m ? 'bg-white text-blue-600 shadow-xl' : 'text-gray-400'}`}>{m}</button>
                    ))}
                 </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><Hash className="w-3 h-3" /> Reference Code</label>
                 <input value={paymentForm.reference} onChange={e => setPaymentForm({...paymentForm, reference: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="e.g. SBR4A6HJ78" />
              </div>
            </div>
            <button type="submit" disabled={isPosting} className="w-full bg-blue-600 text-white py-6 rounded-[32px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 disabled:opacity-50 hover:bg-blue-700 transition-all flex items-center justify-center gap-4">
              {isPosting ? <Loader2 className="w-6 h-6 animate-spin" /> : <ShieldAlert className="w-6 h-6" />}
              {isPosting ? 'POSTING...' : 'AUTHORIZE & PRINT'}
            </button>
          </form>
        </div>
      )}

      {/* Success Modal */}
      {showReceipt && lastReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md animate-in fade-in duration-300">
           <div className="bg-white rounded-[40px] w-full max-w-2xl shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between no-print">
                 <div className="flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6 text-green-500" />
                    <h3 className="text-xl font-black uppercase tracking-tighter text-gray-900">Payment Processed</h3>
                 </div>
                 <button onClick={() => setShowReceipt(false)} className="p-2 hover:bg-white rounded-full transition-all text-gray-400"><X className="w-6 h-6" /></button>
              </div>
              <div className="p-10 text-center">
                 <div className="p-10 bg-gray-50 border-4 border-dashed border-gray-200 rounded-[40px] mb-10 shadow-inner">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Amount Credited</p>
                    <h4 className="text-4xl font-black text-gray-900 leading-none">KES {lastReceipt.amount.toLocaleString()}.00</h4>
                    <div className="mt-6 flex flex-col items-center">
                       <p className="text-sm font-black text-blue-600 uppercase tracking-tighter">{lastReceipt.studentName}</p>
                       <span className="text-[9px] font-black text-gray-400 uppercase mt-2 tracking-widest">Receipt ID: {lastReceipt.receiptNo}</span>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => exportToPDF('receipt-print-template', `Receipt_${lastReceipt.receiptNo}.pdf`)} className="flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-200 transition-all shadow-sm border border-gray-100"><Download size={18} /> Save PDF</button>
                    <button onClick={() => window.print()} className="flex items-center justify-center gap-2 bg-blue-600 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 border border-blue-500"><Printer size={18} /> Print Now</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle,
  Banknote
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: '',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: '',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    const currentPaid = formData.paidFee || 0;
    const newBalance = Math.max(0, fee - currentPaid);
    const newPrepaid = currentPaid > fee ? currentPaid - fee : 0;

    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleInitialPaymentChange = (val: string) => {
    const paid = parseFloat(val) || 0;
    const total = formData.totalFee || 0;
    const newBalance = Math.max(0, total - paid);
    const newPrepaid = paid > total ? paid - total : 0;

    setFormData({ 
      ...formData, 
      paidFee: paid, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  /**
   * FIXED DELETE FUNCTION
   * Location: Place inside StudentManagement component.
   * Logic: Functional state update ensures React 19 batches correctly with localStorage.
   */
  const handleDelete = (id: string, e: React.MouseEvent) => {
    // Prevent the click from bubbling up to any row-level click events
    e.stopPropagation();

    const confirmMessage = "Are you sure you want to delete this student? This will remove all academic and financial records associated with them.";

    if (window.confirm(confirmMessage)) {
      setStudents(currentStudents => {
        // We use a functional update to ensure we're working with the freshest state
        const updatedList = currentStudents.filter(student => student.id !== id);
        return [...updatedList];
      });
    }
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance,
      'Prepaid': rest.prepaidFee
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || '',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            type="button"
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            type="button"
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium shadow-inner" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" alt="Student" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">{student.class} {student.stream && `• ${student.stream}`}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {student.prepaidFee > 0 ? `+KES ${student.prepaidFee.toLocaleString()}` : `KES ${student.feeBalance.toLocaleString()}`}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        onClick={() => openModal(student)} 
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-all border border-transparent hover:border-blue-100 active:scale-90"
                        title="Edit Student"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        onClick={(e) => handleDelete(student.id, e)} 
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-all border border-transparent hover:border-red-100 active:scale-90"
                        title="Delete Student"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between shrink-0">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8">
              <form onSubmit={handleSave} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                     <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                     <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                     <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                     <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                     <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                     <input 
                       required 
                       value={formData.stream} 
                       onChange={e => setFormData({...formData, stream: e.target.value})} 
                       className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold uppercase" 
                       placeholder="e.g. Oak, Palm, Eagle" 
                     />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                     <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                     <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                  </div>
                </div>

                <div className="space-y-4 pt-4">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] border-b pb-2">Financial Setup</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Payment Received</label>
                      <div className="relative">
                        <Banknote className="absolute left-4 top-4 text-gray-400 w-5 h-5" />
                        <input 
                          type="number" 
                          value={formData.paidFee} 
                          onChange={e => handleInitialPaymentChange(e.target.value)} 
                          className="w-full pl-12 p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" 
                          placeholder="0.00" 
                        />
                      </div>
                    </div>
                    <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100 flex flex-col justify-center shadow-inner">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Total Invoice</span>
                        <span className="text-sm font-black text-blue-900">KES {formData.totalFee?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest">{formData.prepaidFee! > 0 ? 'Prepaid Credit' : 'Balance Due'}</span>
                        <span className={`text-sm font-black ${formData.prepaidFee! > 0 ? 'text-green-600' : 'text-red-600'}`}>
                          KES {formData.prepaidFee! > 0 ? formData.prepaidFee?.toLocaleString() : formData.feeBalance?.toLocaleString()}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>

                <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-[24px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 hover:bg-blue-700 hover:scale-[1.01] active:scale-[0.99] transition-all">
                  {editingStudent ? 'Update Profile' : 'Confirm Enrollment'}
                </button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  AlertCircle, 
  Loader2, 
  Printer, 
  Download, 
  Target, 
  Banknote, 
  Forward, 
  CreditCard, 
  Save, 
  ShieldAlert, 
  Zap, 
  X, 
  CheckCircle2, 
  FileDown,
  User,
  Hash,
  Smartphone,
  Search,
  FileSpreadsheet
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
  setFeeStructure: React.Dispatch<React.SetStateAction<ClassFee[]>>;
  schoolLogo: string | null;
}

interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: 'M-PESA' | 'BANK' | 'CASH';
  reference: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, feeStructure, setFeeStructure, schoolLogo }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [financeSearch, setFinanceSearch] = useState('');
  const [isPosting, setIsPosting] = useState(false);
  const [isApplyingFees, setIsApplyingFees] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);

  const [globalFeeValue, setGlobalFeeValue] = useState<string>('');
  const [paymentForm, setPaymentForm] = useState({ 
    adm: '', 
    amount: '', 
    method: 'M-PESA' as 'M-PESA' | 'BANK' | 'CASH', 
    reference: '' 
  });

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const matchesClass = selectedClass === 'All Classes' || s.class === selectedClass;
      const term = financeSearch.toLowerCase();
      const matchesSearch = 
        s.firstName.toLowerCase().includes(term) || 
        s.lastName.toLowerCase().includes(term) || 
        s.admissionNumber.toLowerCase().includes(term);
      return matchesClass && matchesSearch;
    });
  }, [students, selectedClass, financeSearch]);

  const financeStats = useMemo(() => {
    const totalExpected = filteredStudents.reduce((sum, s) => sum + (s.totalFee || 0), 0);
    const totalCollected = filteredStudents.reduce((sum, s) => sum + (s.paidFee || 0), 0);
    const totalOutstanding = filteredStudents.reduce((sum, s) => sum + (s.feeBalance || 0), 0);
    const totalPrepaid = filteredStudents.reduce((sum, s) => sum + (s.prepaidFee || 0), 0);
    return { expected: totalExpected, collected: totalCollected, outstanding: totalOutstanding, prepaid: totalPrepaid };
  }, [filteredStudents]);

  const handleUpdateClassFee = (className: string, value: string) => {
    const amount = parseFloat(value) || 0;
    setFeeStructure(prev => prev.map(f => f.className === className ? { ...f, amount } : f));
  };

  const applyGlobalFee = () => {
    const amount = parseFloat(globalFeeValue) || 0;
    if (amount <= 0) return;
    setFeeStructure(prev => prev.map(f => ({ ...f, amount })));
    setGlobalFeeValue('');
  };

  const syncFeesToStudents = async () => {
    setIsApplyingFees(true);
    await new Promise(r => setTimeout(r, 1200));

    setStudents(prev => prev.map(student => {
      const structure = feeStructure.find(f => f.className === student.class);
      if (structure) {
        const newTotal = structure.amount;
        const paid = student.paidFee || 0;
        let newBalance = newTotal - paid;
        let newPrepaid = 0;
        if (newBalance < 0) {
          newPrepaid = Math.abs(newBalance);
          newBalance = 0;
        }
        return { ...student, totalFee: newTotal, feeBalance: newBalance, prepaidFee: newPrepaid };
      }
      return student;
    }));

    setIsApplyingFees(false);
    alert('Synchronization Successful! All student balances recalculated based on the updated Class Fee Structure.');
  };

  const handlePostPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentForm.adm || !paymentForm.amount) return;
    setIsPosting(true);

    await new Promise(r => setTimeout(r, 800));

    const amountNum = parseFloat(paymentForm.amount);
    let updatedStudent: Student | undefined;

    setStudents(prev => prev.map(s => {
      if (s.admissionNumber === paymentForm.adm) {
        const newPaid = (s.paidFee || 0) + amountNum;
        let newBalance = (s.totalFee || 0) - newPaid;
        let newPrepaid = s.prepaidFee || 0;
        if (newBalance < 0) {
          newPrepaid += Math.abs(newBalance);
          newBalance = 0;
        }
        updatedStudent = { ...s, paidFee: newPaid, feeBalance: newBalance, prepaidFee: newPrepaid };
        return updatedStudent;
      }
      return s;
    }));

    if (updatedStudent) {
      const receipt: TransactionReceipt = {
        receiptNo: `RCP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        studentName: `${updatedStudent.firstName} ${updatedStudent.lastName}`,
        adm: updatedStudent.admissionNumber,
        class: updatedStudent.class,
        amount: amountNum,
        method: paymentForm.method,
        reference: paymentForm.reference || 'CASH_ENTRY',
        date: new Date().toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }),
        balance: updatedStudent.feeBalance,
        servedBy: 'System Admin'
      };
      setLastReceipt(receipt);
      setShowReceipt(true);
    }

    setIsPosting(false);
    setPaymentForm({ adm: '', amount: '', method: 'M-PESA', reference: '' });
  };

  const exportToPDF = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    const h2p = (window as any).html2pdf;
    if (typeof h2p === 'function') {
      h2p().set(opt).from(element).save();
    } else {
      window.print();
    }
  };

  const handleIndividualExportExcel = (student: Student) => {
    const data = [{
      'Admission Number': student.admissionNumber,
      'Name': `${student.firstName} ${student.lastName}`,
      'Class': student.class,
      'Stream': student.stream,
      'Total Termly Invoice': student.totalFee,
      'Total Paid to Date': student.paidFee,
      'Prepaid/Credit': student.prepaidFee,
      'Outstanding Balance': student.feeBalance,
      'Statement Date': new Date().toLocaleDateString()
    }];
    const ws = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, ws, "Fee Statement");
    XLSX.writeFile(workbook, `FeeStatement_${student.admissionNumber}.xlsx`);
  };

  const handleIndividualExportPDF = (student: Student) => {
    const mockStatement: TransactionReceipt = {
        receiptNo: "STMT-" + student.admissionNumber,
        studentName: `${student.firstName} ${student.lastName}`,
        adm: student.admissionNumber,
        class: student.class,
        amount: student.paidFee, 
        method: "CASH",
        reference: "TERM_STATEMENT",
        date: new Date().toLocaleDateString(),
        balance: student.feeBalance,
        servedBy: "Ledger Export"
    };
    setLastReceipt(mockStatement);
    setTimeout(() => {
        exportToPDF('receipt-print-template', `FeeStatement_${student.admissionNumber}.pdf`);
    }, 100);
  };

  return (
    <div className="space-y-8 pb-20">
      <div id="receipt-print-template" className="offscreen-template">
        {lastReceipt && (
          <div style={{ padding: '40px', background: 'white', color: 'black', fontFamily: 'Inter, sans-serif' }}>
            <div style={{ borderBottom: '2px solid #1e3a8a', paddingBottom: '20px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h1 style={{ margin: '0', fontSize: '24px', fontWeight: 'bold', color: '#1e3a8a' }}>ElimuSmart Academy</h1>
                <p style={{ margin: '5px 0', fontSize: '12px' }}>P.O BOX 1234 - 00100, Nairobi | Tel: +254 700 000 000</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Official Fee Document</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '18px' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Fee Statement' : 'Payment Receipt'}</h2>
                <p style={{ margin: '5px 0', fontWeight: 'bold' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Date: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ marginBottom: '30px' }}>
              <p><strong>Student Name:</strong> {lastReceipt.studentName}</p>
              <p><strong>ADM Number:</strong> {lastReceipt.adm}</p>
              <p><strong>Class:</strong> {lastReceipt.class}</p>
            </div>

            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '30px' }}>
              <thead>
                <tr style={{ background: '#f3f4f6' }}>
                  <th style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'left' }}>Description</th>
                  <th style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'right' }}>Amount (KES)</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>
                    {lastReceipt.receiptNo.startsWith('STMT') ? 'Total Tuition Fees Invoiced' : 'School Fees Payment Settlement'}
                    <br/><small>Ref: {lastReceipt.reference}</small>
                  </td>
                  <td style={{ padding: '10px', border: '1px solid #ddd', textAlign: 'right' }}>{lastReceipt.amount.toLocaleString()}.00</td>
                </tr>
              </tbody>
            </table>

            <div style={{ textAlign: 'right', marginBottom: '50px' }}>
              <p style={{ fontSize: '18px', fontWeight: 'bold' }}>Remaining Balance: KES {lastReceipt.balance.toLocaleString()}.00</p>
            </div>

            <div style={{ borderTop: '1px solid #ddd', paddingTop: '20px', display: 'flex', justifyContent: 'space-between' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '150px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px' }}>Served By: {lastReceipt.servedBy}</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '150px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px' }}>School Official Stamp</p>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Finance Center</h1>
          <p className="text-gray-500 font-medium">Automatic billing and student ledger management.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="p-3 bg-white border-2 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-500 transition-all shadow-sm">
            <option>All Classes</option>
            {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
          </select>
          <div className="flex p-1 bg-gray-100 rounded-2xl shadow-inner">
            <button onClick={() => setActiveTab('class-summary')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Ledger</button>
            <button onClick={() => setActiveTab('fee-structure')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'fee-structure' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Fee Settings</button>
            <button onClick={() => setActiveTab('payments')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Post Receipt</button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: 'Expected Revenue', value: financeStats.expected, icon: Target, color: 'indigo' },
          { label: 'Amount Collected', value: financeStats.collected, icon: Banknote, color: 'green' },
          { label: 'Outstanding Debt', value: financeStats.outstanding, icon: AlertCircle, color: 'red' },
          { label: 'Credit Balance', value: financeStats.prepaid, icon: Forward, color: 'blue' },
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-gray-100 flex items-start justify-between shadow-sm hover:shadow-md transition-shadow">
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none mb-2">{stat.label}</p>
              <h3 className={`text-2xl font-black tracking-tight ${stat.color === 'red' ? 'text-red-700' : stat.color === 'green' ? 'text-green-700' : 'text-gray-900'}`}>
                <span className="text-xs font-medium mr-1 opacity-40">KES</span>
                {stat.value.toLocaleString()}
              </h3>
            </div>
            <div className={`p-3 rounded-2xl bg-${stat.color}-50 text-${stat.color}-600 border border-${stat.color}-100`}>
              <stat.icon className="w-5 h-5" />
            </div>
          </div>
        ))}
      </div>

      {activeTab === 'class-summary' && (
        <div className="bg-white rounded-[40px] border border-gray-100 overflow-hidden shadow-sm animate-in fade-in duration-300">
          <div className="p-8 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
             <div className="flex-1 flex items-center gap-4">
                <div className="relative flex-1 max-w-sm">
                   <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
                   <input 
                      type="text" 
                      placeholder="Find student by name or ADM..." 
                      value={financeSearch}
                      onChange={(e) => setFinanceSearch(e.target.value)}
                      className="w-full pl-10 pr-4 py-2.5 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-medium transition-all text-sm shadow-inner"
                   />
                </div>
             </div>
             <button onClick={() => exportToPDF('class-ledger-table', `Global_Ledger_${selectedClass}.pdf`)} className="p-3 bg-white border-2 border-gray-100 rounded-2xl text-gray-600 hover:text-blue-600 hover:border-blue-200 transition-all flex items-center gap-2 font-black uppercase text-[10px] tracking-widest shadow-sm">
                <FileSpreadsheet className="w-4 h-4 text-emerald-600" /> Full Class Ledger
             </button>
          </div>
          <div className="overflow-x-auto" id="class-ledger-table">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                  <th className="px-8 py-6">Student Information</th>
                  <th className="px-8 py-6 text-center">Invoiced</th>
                  <th className="px-8 py-6 text-center">Paid</th>
                  <th className="px-8 py-6 text-center">Balance</th>
                  <th className="px-8 py-6 text-right">Statements</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filteredStudents.map((s, idx) => (
                  <tr key={idx} className="hover:bg-blue-50/10 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="font-black text-gray-900 text-lg leading-tight">{s.firstName} {s.lastName}</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">{s.admissionNumber} • {s.class}</div>
                    </td>
                    <td className="px-8 py-6 text-center font-bold text-gray-700">KES {(s.totalFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-bold text-green-600">KES {(s.paidFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-black">
                       <span className={s.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}>
                         KES {(s.feeBalance || 0).toLocaleString()}
                       </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleIndividualExportExcel(s)}
                          className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-transparent hover:border-emerald-100"
                          title="Export Excel Ledger"
                        >
                          <FileSpreadsheet className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => handleIndividualExportPDF(s)}
                          className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-all border border-transparent hover:border-blue-100"
                          title="Generate PDF Statement"
                        >
                          <FileDown className="w-5 h-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredStudents.length === 0 && (
                  <tr>
                    <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest">No matching student records found in current ledger.</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'fee-structure' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="lg:col-span-2 bg-white rounded-[40px] border border-gray-100 shadow-sm overflow-hidden">
             <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                <div>
                   <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Billing Structure</h3>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Set Tuition per Class</p>
                </div>
                <div className="flex items-center gap-2">
                   <input type="number" placeholder="Global Fee..." value={globalFeeValue} onChange={e => setGlobalFeeValue(e.target.value)} className="w-32 p-3 bg-white border rounded-xl font-bold text-xs" />
                   <button onClick={applyGlobalFee} className="p-3 bg-gray-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm">Apply All</button>
                </div>
             </div>
             <div className="divide-y divide-gray-100 max-h-[600px] overflow-y-auto">
                {feeStructure.map((fee, idx) => (
                  <div key={idx} className="p-6 flex items-center justify-between hover:bg-gray-50 transition-colors">
                     <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center font-black">{idx + 1}</div>
                        <span className="font-black text-gray-800">{fee.className}</span>
                     </div>
                     <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-gray-400 uppercase">KES</span>
                        <input 
                          type="number" 
                          value={fee.amount} 
                          onChange={e => handleUpdateClassFee(fee.className, e.target.value)} 
                          className="w-32 p-3 bg-gray-100 border-2 border-transparent rounded-xl text-center font-black focus:border-blue-500 focus:bg-white transition-all outline-none shadow-inner" 
                        />
                     </div>
                  </div>
                ))}
             </div>
          </div>

          <div className="space-y-6">
             <div className="bg-indigo-900 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden group">
                <div className="absolute -right-8 -bottom-8 opacity-10 group-hover:scale-110 transition-transform">
                  <Zap className="w-48 h-48" />
                </div>
                <div className="relative z-10">
                   <h4 className="text-2xl font-black uppercase tracking-tighter mb-3">Sync Global Invoices</h4>
                   <p className="text-indigo-100/70 font-medium text-sm leading-relaxed mb-8 italic">
                     Clicking sync will instantly update the fee records of all {students.length} students to match these new values.
                   </p>
                   <button 
                    onClick={syncFeesToStudents}
                    disabled={isApplyingFees}
                    className="w-full bg-green-500 text-white py-5 rounded-3xl font-black uppercase tracking-widest hover:bg-green-600 transition-all shadow-xl shadow-green-900/40 disabled:opacity-50 flex items-center justify-center gap-3"
                   >
                     {isApplyingFees ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="v-5 h-5" />}
                     Sync Billing Records
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'payments' && (
        <div className="max-w-4xl mx-auto bg-white p-12 rounded-[56px] border-2 border-gray-100 shadow-2xl animate-in zoom-in duration-500 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-12 opacity-[0.03] pointer-events-none">
             <Smartphone size={200} />
          </div>
          <div className="mb-10 flex items-center gap-6">
             <div className="p-5 bg-blue-600 text-white rounded-[28px] shadow-2xl shadow-blue-200">
                <CreditCard className="w-10 h-10" />
             </div>
             <div>
               <h2 className="text-4xl font-black text-gray-900 uppercase tracking-tighter leading-none">Post Receipt</h2>
               <p className="text-xs text-gray-400 font-black uppercase tracking-[0.3em] mt-3">M-Pesa / Bank Terminal</p>
             </div>
          </div>

          <form onSubmit={handlePostPayment} className="space-y-10 relative z-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><User className="w-3 h-3" /> Select Learner</label>
                 <select required value={paymentForm.adm} onChange={e => setPaymentForm({...paymentForm, adm: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner">
                  <option value="">ADM Number...</option>
                  {students.map(s => <option key={s.id} value={s.admissionNumber}>{s.admissionNumber} - {s.firstName} {s.lastName}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><Banknote className="w-3 h-3" /> Amount (KES)</label>
                 <input required type="number" value={paymentForm.amount} onChange={e => setPaymentForm({...paymentForm, amount: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black text-xl outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="0.00" />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Method</label>
                 <div className="grid grid-cols-3 gap-2 p-2 bg-gray-100 rounded-[24px] shadow-inner">
                    {['M-PESA', 'BANK', 'CASH'].map(m => (
                      <button key={m} type="button" onClick={() => setPaymentForm({...paymentForm, method: m as any})} className={`py-4 rounded-[20px] text-[10px] font-black uppercase transition-all ${paymentForm.method === m ? 'bg-white text-blue-600 shadow-xl' : 'text-gray-400'}`}>{m}</button>
                    ))}
                 </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2"><Hash className="w-3 h-3" /> Reference Code</label>
                 <input value={paymentForm.reference} onChange={e => setPaymentForm({...paymentForm, reference: e.target.value})} className="w-full p-5 bg-gray-50 border-2 border-gray-100 rounded-[24px] font-black uppercase outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="e.g. SBR4A6HJ78" />
              </div>
            </div>
            <button type="submit" disabled={isPosting} className="w-full bg-blue-600 text-white py-6 rounded-[32px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-100 disabled:opacity-50 hover:bg-blue-700 transition-all flex items-center justify-center gap-4">
              {isPosting ? <Loader2 className="w-6 h-6 animate-spin" /> : <ShieldAlert className="w-6 h-6" />}
              {isPosting ? 'POSTING...' : 'AUTHORIZE & PRINT'}
            </button>
          </form>
        </div>
      )}

      {/* Success Modal */}
      {showReceipt && lastReceipt && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md animate-in fade-in duration-300">
           <div className="bg-white rounded-[40px] w-full max-w-2xl shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between no-print">
                 <div className="flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6 text-green-500" />
                    <h3 className="text-xl font-black uppercase tracking-tighter text-gray-900">Payment Processed</h3>
                 </div>
                 <button onClick={() => setShowReceipt(false)} className="p-2 hover:bg-white rounded-full transition-all text-gray-400"><X className="w-6 h-6" /></button>
              </div>
              <div className="p-10 text-center">
                 <div className="p-10 bg-gray-50 border-4 border-dashed border-gray-200 rounded-[40px] mb-10 shadow-inner">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Amount Credited</p>
                    <h4 className="text-4xl font-black text-gray-900 leading-none">KES {lastReceipt.amount.toLocaleString()}.00</h4>
                    <div className="mt-6 flex flex-col items-center">
                       <p className="text-sm font-black text-blue-600 uppercase tracking-tighter">{lastReceipt.studentName}</p>
                       <span className="text-[9px] font-black text-gray-400 uppercase mt-2 tracking-widest">Receipt ID: {lastReceipt.receiptNo}</span>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => exportToPDF('receipt-print-template', `Receipt_${lastReceipt.receiptNo}.pdf`)} className="flex items-center justify-center gap-2 bg-gray-100 text-gray-700 py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-200 transition-all shadow-sm border border-gray-100"><Download size={18} /> Save PDF</button>
                    <button onClick={() => window.print()} className="flex items-center justify-center gap-2 bg-blue-600 text-white py-5 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 border border-blue-500"><Printer size={18} /> Print Now</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

/**
 * Africa's Talking SMS Adapter
 * In production, replace the simulated delay with a real fetch to your Node.js/Python backend.
 */
export const smsService = {
  async sendSMS(to: string, message: string) {
    console.log(`[Africa's Talking] Requesting dispatch to ${to}`);

    // Simulate API network latency
    await new Promise(resolve => setTimeout(resolve, 600));

    // Simulated probability of failure (5%) for error handling demonstration
    if (Math.random() < 0.05) {
      throw new Error("GATEWAY_TIMEOUT: Africa's Talking API did not respond.");
    }

    return { 
      status: 'success', 
      messageId: 'AT_' + Math.random().toString(36).substr(2, 9),
      recipient: to 
    };
  },

  async sendBulkCampaign(recipients: { name: string, phone: string, balance?: number }[], template: string, date?: string) {
    const promises = recipients.map(student => {
      let finalMsg = template
        .replace('{StudentName}', student.name)
        .replace('{Balance}', (student.balance || 0).toLocaleString())
        .replace('{Date}', date || new Date().toLocaleDateString());

      return this.sendSMS(student.phone, finalMsg);
    });

    return Promise.all(promises);
  },

  async sendFeeReminder(studentName: string, phone: string, balance: number) {
    const msg = `ElimuSmart Fee Alert: Dear Guardian, your child ${studentName} has a balance of KES ${balance.toLocaleString()}. Kindly clear by end of week.`;
    return this.sendSMS(phone, msg);
  }
};

import React, { useState, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Filter, 
  Phone, 
  X, 
  Camera, 
  Trash2, 
  Edit2, 
  User, 
  Users, 
  FileUp, 
  FileDown, 
  Loader2,
  ShieldCheck,
  AlertCircle,
  Banknote
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Student, KENYAN_CLASSES, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
}

export const StudentManagement: React.FC<Props> = ({ students, setStudents, feeStructure }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Student>>({
    firstName: '',
    lastName: '',
    admissionNumber: '',
    class: 'Grade 7',
    stream: '',
    gender: 'Male',
    dob: '',
    guardianName: '',
    guardianPhone: '',
    totalFee: 45000,
    paidFee: 0,
    prepaidFee: 0,
    feeBalance: 45000
  });

  const openModal = (student?: Student) => {
    if (student) {
      setEditingStudent(student);
      setFormData(student);
    } else {
      setEditingStudent(null);
      const defaultClass = 'Grade 7';
      const defaultFee = feeStructure.find(f => f.className === defaultClass)?.amount || 45000;
      setFormData({
        firstName: '',
        lastName: '',
        admissionNumber: '',
        class: defaultClass,
        stream: '',
        gender: 'Male',
        dob: '',
        guardianName: '',
        guardianPhone: '',
        totalFee: defaultFee,
        paidFee: 0,
        prepaidFee: 0,
        feeBalance: defaultFee
      });
    }
    setIsModalOpen(true);
  };

  const handleClassChange = (newClass: string) => {
    const fee = feeStructure.find(f => f.className === newClass)?.amount || 0;
    const currentPaid = formData.paidFee || 0;
    const newBalance = Math.max(0, fee - currentPaid);
    const newPrepaid = currentPaid > fee ? currentPaid - fee : 0;

    setFormData({ 
      ...formData, 
      class: newClass, 
      totalFee: fee, 
      feeBalance: newBalance,
      prepaidFee: newPrepaid
    });
  };

  /**
   * FIXED DELETE FUNCTION
   * Location: Place inside StudentManagement component.
   * Logic: Functional state update ensures React 19 batches correctly with localStorage.
   */
  const handleDelete = (id: string, e: React.MouseEvent) => {
    // 1. Isolate the event so it doesn't trigger parent row clicks
    e.stopPropagation();

    // 2. Ask for confirmation (Safety first)
    const confirmed = window.confirm("Are you sure you want to delete this student? This will remove all associated financial and academic records permanently.");

    if (confirmed) {
      // 3. Update state using the functional form for immediate sync
      setStudents(prevStudents => {
        const updatedList = prevStudents.filter(student => student.id !== id);
        // Note: App.tsx has a useEffect that watches `students` and saves to localStorage automatically
        return [...updatedList];
      });
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setStudents(prev => prev.map(s => s.id === editingStudent.id ? { ...s, ...formData } as Student : s));
    } else {
      const newStudent = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${formData.firstName}${formData.lastName}${Date.now()}`,
      } as Student;
      setStudents(prev => [...prev, newStudent]);
    }
    setIsModalOpen(false);
  };

  const handleExportExcel = () => {
    const exportData = students.map(({ id, photo, ...rest }) => ({
      'Adm Number': rest.admissionNumber,
      'First Name': rest.firstName,
      'Last Name': rest.lastName,
      'Class': rest.class,
      'Stream': rest.stream,
      'Gender': rest.gender,
      'Guardian Name': rest.guardianName,
      'Guardian Phone': rest.guardianPhone,
      'Total Fee': rest.totalFee,
      'Paid Fee': rest.paidFee,
      'Balance': rest.feeBalance,
      'Prepaid': rest.prepaidFee
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_Export_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleImportExcel = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json(ws);

        const importedStudents: Student[] = data.map((row: any) => {
          const className = row['Class'] || 'Grade 7';
          const classFee = feeStructure.find(f => f.className === className)?.amount || 45000;
          const paid = parseFloat(row['Paid Fee']) || 0;
          const total = parseFloat(row['Total Fee']) || classFee;

          return {
            id: Math.random().toString(36).substr(2, 9),
            admissionNumber: String(row['Adm Number'] || row['Admission Number'] || ''),
            firstName: row['First Name'] || row['Name']?.split(' ')[0] || '',
            lastName: row['Last Name'] || row['Name']?.split(' ').slice(1).join(' ') || '',
            class: className,
            stream: row['Stream'] || '',
            gender: row['Gender'] || 'Male',
            dob: row['DOB'] || '2012-01-01',
            guardianName: row['Guardian Name'] || '',
            guardianPhone: String(row['Guardian Phone'] || ''),
            totalFee: total,
            paidFee: paid,
            feeBalance: Math.max(0, total - paid),
            prepaidFee: paid > total ? paid - total : 0,
            photo: `https://api.dicebear.com/7.x/avataaars/svg?seed=${row['First Name']}${row['Adm Number']}`
          };
        });

        setStudents(prev => [...prev, ...importedStudents]);
        alert(`Successfully imported ${importedStudents.length} students.`);
      } catch (error) {
        console.error("Import Error:", error);
        alert("Failed to parse file. Please ensure it follows the correct format.");
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  const filteredStudents = students.filter(s => 
    `${s.firstName} ${s.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.admissionNumber.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Student Directory</h1>
          <p className="text-gray-500 font-medium">Manage {students.length} enrolled learners.</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportExcel} 
            className="hidden" 
            accept=".xlsx, .xls, .csv" 
          />
          <button 
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={isImporting}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            {isImporting ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileUp className="w-4 h-4" />}
            <span>{isImporting ? 'Importing...' : 'Import'}</span>
          </button>
          <button 
            type="button"
            onClick={handleExportExcel}
            className="flex items-center gap-2 bg-white border-2 border-gray-100 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase tracking-widest text-xs shadow-sm active:scale-95"
          >
            <FileDown className="w-4 h-4" />
            <span>Export</span>
          </button>
          <button 
            type="button"
            onClick={() => openModal()}
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-100 active:scale-95"
          >
            <Plus className="w-4 h-4" />
            <span>Enroll Learner</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-6 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-md:w-full">
            <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search by name or ADM..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 transition-all outline-none font-medium shadow-inner" 
            />
          </div>
          <div className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-blue-700 font-black uppercase text-[10px] tracking-widest border border-blue-100 shadow-sm">
             <Users className="w-4 h-4" />
             {filteredStudents.length} Result{filteredStudents.length !== 1 ? 's' : ''}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                <th className="px-8 py-5">Learner Profile</th>
                <th className="px-8 py-5 text-center">ADM No</th>
                <th className="px-8 py-5 text-center">Grade/Stream</th>
                <th className="px-8 py-5 text-center">Fee Balance</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-blue-50/20 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <img src={student.photo} className="w-10 h-10 rounded-xl bg-gray-100 border border-gray-100 shadow-sm" alt="Student" />
                      <div>
                        <div className="font-black text-gray-900 leading-tight group-hover:text-blue-600 transition-colors">{student.firstName} {student.lastName}</div>
                        <div className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-0.5">{student.gender}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-center font-mono font-black text-blue-600">{student.admissionNumber}</td>
                  <td className="px-8 py-5 text-center">
                    <span className="px-3 py-1 bg-gray-100 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">{student.class} {student.stream && `• ${student.stream}`}</span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <div className={`font-black ${student.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                      {student.prepaidFee > 0 ? `+KES ${student.prepaidFee.toLocaleString()}` : `KES ${student.feeBalance.toLocaleString()}`}
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        onClick={() => openModal(student)} 
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-all border border-transparent hover:border-blue-100 active:scale-90"
                        title="Edit Student"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        onClick={(e) => handleDelete(student.id, e)} 
                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-all border border-transparent hover:border-red-100 active:scale-90"
                        title="Delete Student"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                   <td colSpan={5} className="py-20 text-center">
                      <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                      <p className="text-gray-400 font-black uppercase text-[10px] tracking-widest italic">No matching student records found.</p>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[32px] w-full max-w-2xl shadow-2xl relative overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in duration-300">
            <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between shrink-0">
              <div>
                <h2 className="text-2xl font-black text-gray-900 uppercase leading-none">{editingStudent ? 'Edit Profile' : 'Enrollment Detail'}</h2>
                <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-2">Personal & Academic Record</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 overflow-y-auto p-8">
              <form onSubmit={handleSave} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">First Name</label>
                     <input required value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="First Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Last Name</label>
                     <input required value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Last Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Admission Number</label>
                     <input required value={formData.admissionNumber} onChange={e => setFormData({...formData, admissionNumber: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-mono font-black text-blue-600" placeholder="ADM001" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Gender</label>
                     <select value={formData.gender} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Grade</label>
                     <select value={formData.class} onChange={e => handleClassChange(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-black uppercase">
                      {KENYAN_CLASSES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Stream</label>
                     <input 
                       required 
                       value={formData.stream} 
                       onChange={e => setFormData({...formData, stream: e.target.value})} 
                       className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold uppercase" 
                       placeholder="e.g. Oak, Palm, Eagle" 
                     />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Guardian Identity</label>
                     <input required value={formData.guardianName} onChange={e => setFormData({...formData, guardianName: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="Guardian Name" />
                  </div>
                  <div className="space-y-1">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Phone Contact</label>
                     <input required value={formData.guardianPhone} onChange={e => setFormData({...formData, guardianPhone: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none transition-all font-bold" placeholder="0700..." />
                  </div>
                </div>

