import React, { useState, useMemo } from 'react';
import { 
  Send, 
  MessageSquare, 
  Calendar, 
  Wallet, 
  Users, 
  Clock, 
  CheckCircle2, 
  AlertCircle, 
  Loader2, 
  Search,
  ChevronRight,
  Filter,
  Phone,
  LayoutGrid,
  FileText,
  Smartphone,
  Info,
  Plus,
  ArrowUpRight,
  X,
  CreditCard,
  History
} from 'lucide-react';
import { smsService } from '../services/smsService';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student } from '../types';

interface MessageLog {
  id: string;
  type: string;
  recipients: number;
  date: string;
  status: 'Delivered' | 'Failed' | 'Confirmed' | 'Pending';
  cost: number;
  sampleMessage?: string;
}

// Fixed: Correctly using the provided student list for logic
const RECIPIENTS_LIST: Student[] = [
  { id: '1', admissionNumber: 'ADM001', firstName: 'Kamau', lastName: 'Njoroge', class: 'Grade 7', stream: 'Oak', gender: 'Male', dob: '2011-04-12', guardianPhone: '0712345678', guardianName: 'Sarah Njoroge', feeBalance: 12500, totalFee: 45000, paidFee: 32500, prepaidFee: 0, photo: 'https://picsum.photos/100/100?random=10' },
  { id: '2', admissionNumber: 'ADM002', firstName: 'Amara', lastName: 'Kiprono', class: 'Grade 8', stream: 'Palm', gender: 'Female', dob: '2010-08-25', guardianPhone: '0722000111', guardianName: 'David Kiprono', feeBalance: 0, totalFee: 45000, paidFee: 45000, prepaidFee: 2500, photo: 'https://picsum.photos/100/100?random=11' },
];

type MessageType = 'fee' | 'opening' | 'closing' | 'custom';

export const MessagingModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'compose' | 'history' | 'automated' | 'credits'>('compose');
  const [selectedType, setSelectedType] = useState<MessageType>('fee');
  const [targetClass, setTargetClass] = useState('All Classes');
  const [isSending, setIsSending] = useState(false);
  const [customMessage, setCustomMessage] = useState('');
  const [smsBalance, setSmsBalance] = useState(4250);
  const [isTopUpModalOpen, setIsTopUpModalOpen] = useState(false);
  const [topUpAmount, setTopUpAmount] = useState('1000');
  const [isTopUpProcessing, setIsTopUpProcessing] = useState(false);

  const [logs, setLogs] = useState<MessageLog[]>([
    { id: '1', type: 'Fee Reminder', recipients: 45, date: '2024-05-10', status: 'Delivered', cost: 45, sampleMessage: "Dear Parent, your child Kamau's outstanding balance is KES 12,500." },
    { id: '2', type: 'Opening Date', recipients: 482, date: '2024-05-01', status: 'Delivered', cost: 482, sampleMessage: "School reopens on Monday, 6th May." },
  ]);

  const templates = {
    fee: "Dear Parent, your child {StudentName}'s outstanding balance is KES {Balance}. Please clear to avoid inconvenience.",
    opening: "ElimuSmart Academy: School reopens for Term 2 on {Date}. Ensure your child reports with all required materials.",
    closing: "Dear Parent, school closes today {Date}. Academic reports will be shared via the portal. Have a safe holiday!",
    custom: customMessage
  };

  const currentPreview = useMemo(() => {
    let msg = templates[selectedType];
    if (selectedType === 'fee') {
      msg = msg.replace('{StudentName}', 'Kamau').replace('{Balance}', '12,500');
    } else if (selectedType === 'opening') {
      msg = msg.replace('{Date}', 'Monday, 6th May');
    } else if (selectedType === 'closing') {
      msg = msg.replace('{Date}', 'Friday, 2nd August');
    }
    return msg;
  }, [selectedType, customMessage]);

  const handleSendBulk = async () => {
    // 1. Filter targets
    const targetRecipients = RECIPIENTS_LIST.filter(s => 
      (targetClass === 'All Classes' || s.class === targetClass) &&
      (selectedType !== 'fee' || s.feeBalance > 0)
    );

    if (targetRecipients.length === 0) {
      alert("No matching parents found for the selected criteria.");
      return;
    }

    // 2. Check balance (1 Unit per SMS)
    if (smsBalance < targetRecipients.length) {
      alert(`Insufficient SMS Credits. Required: ${targetRecipients.length} Units, Available: ${smsBalance} Units.`);
      return;
    }

    // 3. Dispatch Campaign
    setIsSending(true);
    try {
      const template = templates[selectedType];
      const dataForService = targetRecipients.map(s => ({
        name: s.firstName,
        phone: s.guardianPhone,
        balance: s.feeBalance
      }));

      // Call the "Backend" service
      const results = await smsService.sendBulkCampaign(dataForService, template);

      // Update UI state
      setSmsBalance(prev => prev - targetRecipients.length);

      const newLog: MessageLog = {
        id: Date.now().toString(),
        type: selectedType === 'custom' ? 'Announcement' : selectedType === 'fee' ? 'Fee Reminder' : 'Academic Alert',
        recipients: targetRecipients.length,
        date: new Date().toLocaleDateString(),
        status: 'Delivered',
        cost: targetRecipients.length,
        sampleMessage: currentPreview
      };

      setLogs(prev => [newLog, ...prev]);
      setCustomMessage('');
      alert(`SUCCESS: Live SMS dispatch complete. Sent to ${targetRecipients.length} parents.`);

    } catch (error: any) {
      console.error("SMS Dispatch Error:", error);
      alert(`DISPATCH FAILED: ${error.message || "An unknown error occurred during gateway communication."}`);
    } finally {
      setIsSending(false);
    }
  };

  const handleTopUp = async () => {
    setIsTopUpProcessing(true);
    try {
      await new Promise(r => setTimeout(r, 1500));
      setSmsBalance(prev => prev + parseInt(topUpAmount));
      alert("Credits topped up successfully via M-Pesa STK.");
      setIsTopUpModalOpen(false);
    } catch (error) {
      alert("Top-up failed. Please check M-Pesa connection.");
    } finally {
      setIsTopUpProcessing(false);
    }
  };

  return (
    <div className="space-y-8 max-w-6xl mx-auto pb-10">
