  { id: '2', admissionNumber: 'ADM002', firstName: 'Amara', lastName: 'Kiprono', class: 'Grade 8', stream: 'Palm', gender: 'Female', dob: '2010-08-25', guardianPhone: '0722000111', guardianName: 'David Kiprono', feeBalance: 0, totalFee: 45000, paidFee: 45000, prepaidFee: 2500, photo: 'https://picsum.photos/100/100?random=11' },
];

type MessageType = 'fee' | 'opening' | 'closing' | 'custom';

export const MessagingModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'compose' | 'history' | 'automated' | 'credits'>('compose');
  const [selectedType, setSelectedType] = useState<MessageType>('fee');
  const [targetClass, setTargetClass] = useState('All Classes');
  const [isSending, setIsSending] = useState(false);
  const [customMessage, setCustomMessage] = useState('');
  const [smsBalance, setSmsBalance] = useState(4250);
  const [isTopUpModalOpen, setIsTopUpModalOpen] = useState(false);
  const [topUpAmount, setTopUpAmount] = useState('1000');
  const [isTopUpProcessing, setIsTopUpProcessing] = useState(false);

  const [logs, setLogs] = useState<MessageLog[]>([
    { id: '1', type: 'Fee Reminder', recipients: 45, date: '2024-05-10', status: 'Delivered', cost: 45, sampleMessage: "Dear Parent, your child Kamau's outstanding balance is KES 12,500." },
    { id: '2', type: 'Opening Date', recipients: 482, date: '2024-05-01', status: 'Delivered', cost: 482, sampleMessage: "School reopens on Monday, 6th May." },
  ]);

  const templates = {
    fee: "Dear Parent, your child {StudentName}'s outstanding balance is KES {Balance}. Please clear to avoid inconvenience.",
    opening: "ElimuSmart Academy: School reopens for Term 2 on {Date}. Ensure your child reports with all required materials.",
    closing: "Dear Parent, school closes today {Date}. Academic reports will be shared via the portal. Have a safe holiday!",
    custom: customMessage
  };

  const currentPreview = useMemo(() => {
    let msg = templates[selectedType];
    if (selectedType === 'fee') {
      msg = msg.replace(/{StudentName}/g, 'Kamau').replace(/{Balance}/g, '12,500');
    } else if (selectedType === 'opening') {
      msg = msg.replace(/{Date}/g, 'Monday, 6th May');
    } else if (selectedType === 'closing') {
      msg = msg.replace(/{Date}/g, 'Friday, 2nd August');
    }
    return msg;
  }, [selectedType, customMessage]);

  const handleSendBulk = async () => {
    // 1. Identify Target Recipients
    const targetRecipients = MOCK_RECIPIENTS_LIST.filter(s => 
      (targetClass === 'All Classes' || s.class === targetClass) &&
      (selectedType !== 'fee' || s.feeBalance > 0)
    );

    if (targetRecipients.length === 0) {
      alert("System identified 0 matching recipients for this campaign. Please check your filters.");
      return;
    }

    // 2. Validate SMS Credit Balance
    const costPerUnit = 1;
    const estimatedCost = targetRecipients.length * costPerUnit;

    if (smsBalance < estimatedCost) {
      alert(`INSUFFICIENT CREDITS: This campaign requires ${estimatedCost} units. Current balance: ${smsBalance}.`);
      return;
    }

    // 3. Confirm with Admin
    const confirmation = window.confirm(`PROCEED WITH DISPATCH?\nTarget: ${targetRecipients.length} Parents\nEstimated Cost: ${estimatedCost} SMS Units\nGateway: Africa's Talking (LIVE)`);
