    // 4. Execution
    setIsSending(true);
    try {
      const template = templates[selectedType];
      const dataForService = targetRecipients.map(s => ({
        name: s.firstName,
        phone: s.guardianPhone,
        balance: s.feeBalance
      }));

      // LIVE CALL TO SMS GATEWAY SERVICE
      await smsService.sendBulkCampaign(dataForService, template);

      // Update Balance and Logs
      setSmsBalance(prev => prev - estimatedCost);

      const newLog: MessageLog = {
        id: 'LOG_' + Date.now(),
        type: selectedType === 'custom' ? 'Announcement' : selectedType === 'fee' ? 'Fee Alert' : 'Academic Update',
        recipients: targetRecipients.length,
        date: new Date().toLocaleDateString() + ' ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        status: 'Delivered',
        cost: estimatedCost,
        sampleMessage: currentPreview
      };

      setLogs(prev => [newLog, ...prev]);
      setCustomMessage('');

      // Feedback Success
      alert(`CAMPAIGN DISPATCHED SUCCESSFULLY!\nGateway confirmation received for ${targetRecipients.length} messages.`);

