                <p className="text-lg font-black text-white leading-none">{smsBalance.toLocaleString()}</p>
              </div>
           </div>
           <button 
            onClick={() => setIsTopUpModalOpen(true)}
            className="bg-white text-blue-600 px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-50 transition-all flex items-center gap-2 shadow-sm"
           >
