### 2. Backend Implementation (Node.js + Africa's Talking)

To make this live, you need a backend server. Here is a production-ready snippet for an Express server.

**Step A: Setup Dependencies**
```bash
npm install express africastalking dotenv body-parser cors
```

**Step B: Backend Code (`server.js`)**
```javascript
const express = require('express');
const AfricasTalking = require('africastalking');
const bodyParser = require('body-parser');
const cors = require('cors');
require('dotenv').config();

const app = express();
app.use(cors());
app.use(bodyParser.json());

// Initialize AT SDK
const at = AfricasTalking({
    apiKey: process.env.AT_API_KEY,
    username: process.env.AT_USERNAME
});

const sms = at.SMS;

/**
 * Endpoint: /api/sms/dispatch
 * Handles bulk dispatch with batching to avoid rate limits
 */
app.post('/api/sms/dispatch', async (req, res) => {
    const { recipients, template, campaignType } = req.body;

    // Batch size of 50 is recommended for Africa's Talking
    const batchSize = 50;
    const errors = [];
    const successes = [];

    try {
        for (let i = 0; i < recipients.length; i += batchSize) {
            const batch = recipients.slice(i, i + batchSize);

            // Map batch to individual messages or group by content
            const promises = batch.map(async (student) => {
                const message = template
                    .replace(/{StudentName}/g, student.name)
                    .replace(/{Balance}/g, (student.balance || 0).toLocaleString());

                return sms.send({
                    to: [student.phone],
                    message: message,
                    from: process.env.AT_SENDER_ID, // Ensure UTF-8 is handled natively by the SDK
                    enqueue: true // Uses AT's queue for better reliability
                });
            });

            const results = await Promise.allSettled(promises);
            // Log results for auditing...
        }

        res.json({ success: true, message: `Campaign initiated for ${recipients.length} recipients.` });
    } catch (err) {
        res.status(500).json({ success: false, error: err.message });
    }
});

/**
 * Webhook: Africa's Talking Delivery Reports
 * AT will call this endpoint whenever a status changes
 */
app.post('/api/sms/webhook', (req, res) => {
    const { phoneNumber, status, requestId } = req.body;
    console.log(`[AT Webhook] Number: ${phoneNumber}, Status: ${status}`);

    // Here you would update your database (PostgreSQL/MongoDB)
    // db.sms_logs.update({ requestId }, { status });

    res.sendStatus(200);
});

app.listen(3000, () => console.log('ElimuSmart Live Gateway active on port 3000'));
```

### 3. Debugging & Maintenance Tips

1.  **UTF-8 Support**: Africa's Talking supports UTF-8 by default. When sending Swahili or special characters, ensure your Node.js file is saved as UTF-8 (the default in VS Code).
2.  **Sender ID**: In the `sms.send` object, the `from` field MUST match the Sender ID approved by Africa's Talking. If you use the sandbox, leave it blank or use the provided shortcode.
3.  **Queue Management**: For very large schools (10,000+ students), use **BullMQ** or **RabbitMQ**. Instead of looping in the HTTP request, push the job to a queue and return `202 Accepted` immediately.
4.  **Balance Check**: Africa's Talking has an API to check your balance. It’s good practice to call `at.APPLICATION.fetchApplicationData()` before sending to warn the admin if credits are low.

