              <button onClick={() => setIsDeleteModalOpen(false)} className="absolute top-6 right-6 p-4 text-gray-300 hover:text-red-500 transition-colors">
                 <X className="w-8 h-8" />
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

