    }
  });

  const [feeStructure, setFeeStructure] = useState<ClassFee[]>(() => {
    try {
      const saved = localStorage.getItem('elimusmart_fees');
      return saved ? JSON.parse(saved) : INITIAL_FEE_STRUCTURE;
    } catch (e) {
      return INITIAL_FEE_STRUCTURE;
    }
  });

  const [schoolLogo, setSchoolLogo] = useState<string | null>(() => {
    return localStorage.getItem('elimusmart_logo');
  });

  useEffect(() => {
    localStorage.setItem('elimusmart_students', JSON.stringify(students));
  }, [students]);

  useEffect(() => {
    localStorage.setItem('elimusmart_fees', JSON.stringify(feeStructure));
  }, [feeStructure]);

  useEffect(() => {
    if (schoolLogo) localStorage.setItem('elimusmart_logo', schoolLogo);
    else localStorage.removeItem('elimusmart_logo');
  }, [schoolLogo]);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallPop, setShowInstallPop] = useState(false);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setTimeout(() => setShowInstallPop(true), 4000);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallApp = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: { outcome: string }) => {
        setDeferredPrompt(null);
        setShowInstallPop(false);
      });
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const foundUser = AUTH_DB.find(u => u.email === username.toLowerCase() && u.password === password);
    if (foundUser) {
      const { password, ...userWithoutPassword } = foundUser;
      setUser(userWithoutPassword as User);
      setCurrentTab('dashboard');
    } else {
      alert('Invalid credentials.');
    }
  };

  const switchRole = (role: UserRole) => {
    const roleUser = AUTH_DB.find(u => u.role === role);
    if (roleUser) {
      const { password, ...userWithoutPassword } = roleUser;
      setUser(userWithoutPassword as User);
      setCurrentTab('dashboard');
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-blue-700 p-4">
        <div className="bg-white rounded-[40px] shadow-2xl p-10 max-w-lg w-full">
          <div className="text-center mb-10">
            <h1 className="text-4xl font-black text-gray-900 tracking-tighter leading-none">ElimuSmart</h1>
            <p className="text-gray-400 font-bold uppercase text-[10px] tracking-widest mt-2 leading-none">Management ERP System</p>
          </div>
          <form className="space-y-6" onSubmit={handleLogin}>
            <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full p-4 bg-gray-50 border rounded-2xl font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="Email" />
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full p-4 bg-gray-50 border rounded-2xl font-bold outline-none focus:ring-2 focus:ring-blue-500" placeholder="Password" />
            <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all">Sign In</button>
          </form>
          <div className="mt-8 flex gap-2 justify-center">
            <button onClick={() => { setUsername('principal@school.ac.ke'); setPassword('password123'); }} className="text-[9px] bg-gray-100 px-3 py-2 rounded-xl font-black uppercase text-gray-500 hover:bg-gray-200 transition-all">Principal Demo</button>
            <button onClick={() => { setUsername('admin@school.ac.ke'); setPassword('adminpassword'); }} className="text-[9px] bg-gray-100 px-3 py-2 rounded-xl font-black uppercase text-gray-500 hover:bg-gray-200 transition-all">Admin Demo</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      currentTab={currentTab} 
      setCurrentTab={setCurrentTab}
      isSidebarOpen={isSidebarOpen}
      setIsSidebarOpen={setIsSidebarOpen}
      logout={() => setUser(null)}
      lang={lang}
      setLang={setLang}
      switchRole={switchRole}
      installApp={deferredPrompt ? handleInstallApp : undefined}
    >
      {showInstallPop && deferredPrompt && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[200] w-full max-w-md px-4 animate-in slide-in-from-top-4 duration-500">
          <div className="bg-white rounded-[32px] shadow-[0_20px_50px_rgba(0,0,0,0.2)] p-6 border-2 border-blue-50 flex items-center gap-6 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <Smartphone size={100} />
             </div>
             <div className="bg-blue-600 text-white p-4 rounded-2xl shadow-xl shadow-blue-100 shrink-0">
                <Smartphone size={24} />
             </div>
             <div className="flex-1">
                <h4 className="text-sm font-black text-gray-900 uppercase tracking-tight">Offline Access Ready</h4>
                <p className="text-[11px] font-bold text-gray-500 leading-tight mt-1">Install ElimuSmart for the best experience.</p>
                <div className="flex gap-2 mt-4">
                   <button onClick={handleInstallApp} className="bg-blue-600 text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-100 flex items-center gap-2">
                     <Check size={14} /> Install Now
                   </button>
                   <button onClick={() => setShowInstallPop(false)} className="bg-gray-100 text-gray-500 px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest">
                     Later
                   </button>
                </div>
             </div>
             <button onClick={() => setShowInstallPop(false)} className="absolute top-4 right-4 text-gray-300 hover:text-gray-500"><X size={18} /></button>
          </div>
        </div>
      )}

      <main className="p-4 md:p-8 max-w-[1600px] mx-auto">
        {currentTab === 'dashboard' && <Dashboard user={user} lang={lang} students={students} />}
        {currentTab === 'students' && <StudentManagement students={students} setStudents={setStudents} feeStructure={feeStructure} />}
        {currentTab === 'staff' && <StaffManagement />}
        {currentTab === 'academics' && <AcademicsModule lang={lang} students={students} setStudents={setStudents} />}
        {currentTab === 'timetable' && <TimetableModule lang={lang} />}
        {currentTab === 'finance' && <FinanceModule lang={lang} students={students} setStudents={setStudents} feeStructure={feeStructure} setFeeStructure={setFeeStructure} schoolLogo={schoolLogo} />}
        {currentTab === 'attendance' && <AttendanceModule lang={lang} />}
        {currentTab === 'messaging' && <MessagingModule lang={lang} students={students} />}
        {currentTab === 'reports' && <ReportsModule lang={lang} students={students} />}
        {currentTab === 'settings' && <SettingsModule userRole={user.role} schoolLogo={schoolLogo} setSchoolLogo={setSchoolLogo} />}
      </main>
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  BookOpen, 
  Plus, 
  Search, 
  ChevronRight, 
  Save, 
  Wand2, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Filter,
  ArrowLeft,
  BookMarked,
  Trash2,
  Edit3,
  X,
  Tags,
  CalendarDays,
  LayoutGrid
} from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { Exam, MarkEntry, CBCGrade, KENYAN_CLASSES, SCHOOL_STREAMS, Student, ExamResult } from '../types';
import { schoolService } from '../services/schoolService';
import { Language, translations } from '../services/localizationService';

interface Subject {
  id: string;
  name: string;
  category: string;
  gradeRange: string;
}

const MOCK_SUBJECTS: Subject[] = [
  { id: 'sub1', name: 'Mathematics', category: 'STEM', gradeRange: 'PP1 - Grade 9' },
  { id: 'sub2', name: 'English Language', category: 'Languages', gradeRange: 'Grade 1 - Grade 9' },
  { id: 'sub3', name: 'Kiswahili', category: 'Languages', gradeRange: 'Grade 1 - Grade 9' },
  { id: 'sub4', name: 'Integrated Science', category: 'STEM', gradeRange: 'Grade 7 - Grade 9' },
  { id: 'sub5', name: 'Creative Arts', category: 'Arts', gradeRange: 'PP1 - Grade 9' },
  { id: 'sub6', name: 'Pre-Technical Studies', category: 'Technical', gradeRange: 'Grade 7 - Grade 9' },
];

interface AcademicsProps {
  lang: Language;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

export const AcademicsModule: React.FC<AcademicsProps> = ({ lang, students, setStudents }) => {
  const t = translations[lang];
  const [view, setView] = useState<'exams' | 'mark-entry' | 'subjects'>('exams');

  const [exams, setExams] = useState<Exam[]>([]);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [editingExam, setEditingExam] = useState<Exam | null>(null);
  const [examSearch, setExamSearch] = useState('');
  const [examFormData, setExamFormData] = useState<Partial<Exam>>({
    title: '',
    term: 1,
    year: new Date().getFullYear(),
    type: 'CAT',
    date: new Date().toISOString().split('T')[0]
  });

  const [subjects, setSubjects] = useState<Subject[]>(MOCK_SUBJECTS);
  const [isSubjectModalOpen, setIsSubjectModalOpen] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Subject | null>(null);
  const [subjectSearch, setSubjectSearch] = useState('');
  const [subjectFormData, setSubjectFormData] = useState({ 
    name: '', 
    category: 'STEM', 
    gradeRange: 'Grade 1 - Grade 6' 
  });

  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [selectedSubject, setSelectedSubject] = useState('Mathematics');
  const [selectedClass, setSelectedClass] = useState('Grade 7');
  const [selectedStream, setSelectedStream] = useState('Oak');
  const [marks, setMarks] = useState<MarkEntry[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isGeneratingRemarks, setIsGeneratingRemarks] = useState<string | null>(null);

  useEffect(() => {
    schoolService.getExams().then(setExams);
  }, []);

  const filteredExams = useMemo(() => {
    return exams.filter(ex => 
      ex.title.toLowerCase().includes(examSearch.toLowerCase()) ||
      ex.type.toLowerCase().includes(examSearch.toLowerCase())
    );
  }, [exams, examSearch]);

  const filteredSubjects = useMemo(() => {
    return subjects.filter(s => 
      s.name.toLowerCase().includes(subjectSearch.toLowerCase()) ||
      s.category.toLowerCase().includes(subjectSearch.toLowerCase())
    );
  }, [subjects, subjectSearch]);

  const handleOpenMarkEntry = (exam: Exam) => {
    setSelectedExam(exam);
    // Fetch actual students for the class/stream
    const classStudents = students.filter(s => s.class === selectedClass && (selectedStream === 'All Streams' || s.stream === selectedStream || !s.stream));

    const entries: MarkEntry[] = classStudents.map(s => {
      // Check if student already has a mark for this exam and subject
      const existing = s.results?.find(r => r.examId === exam.id && r.subject === selectedSubject);
      return {
        studentId: s.id,
        studentName: `${s.firstName} ${s.lastName}`,
        admissionNumber: s.admissionNumber,
        score: existing?.score || 0,
        competency: existing?.competency || CBCGrade.BE,
        remarks: existing?.remarks || ''
      };
    });

    setMarks(entries);
    setView('mark-entry');
  };

  const openExamModal = (exam?: Exam) => {
    if (exam) {
      setEditingExam(exam);
      setExamFormData({
        title: exam.title,
        term: exam.term,
        year: exam.year,
        type: exam.type,
        date: exam.date
      });
    } else {
      setEditingExam(null);
      setExamFormData({
        title: '',
        term: 1,
        year: new Date().getFullYear(),
        type: 'CAT',
        date: new Date().toISOString().split('T')[0]
      });
    }
    setIsExamModalOpen(true);
  };

  const handleSaveExam = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingExam) {
      setExams(prev => prev.map(ex => 
        ex.id === editingExam.id ? { ...ex, ...examFormData } as Exam : ex
      ));
    } else {
      const newExam: Exam = {
        id: `ex${Date.now()}`,
        title: examFormData.title || 'New Assessment',
        term: examFormData.term || 1,
        year: examFormData.year || new Date().getFullYear(),
        type: examFormData.type as any || 'CAT',
        date: examFormData.date || new Date().toISOString().split('T')[0]
      };
      setExams(prev => [newExam, ...prev]);
    }
    setIsExamModalOpen(false);
  };

  const handleDeleteExam = (id: string) => {
    if (confirm('Are you sure you want to delete this exam and all associated records?')) {
      setExams(prev => prev.filter(ex => ex.id !== id));
    }
  };

  const openSubjectModal = (subject?: Subject) => {
    if (subject) {
      setEditingSubject(subject);
      setSubjectFormData({ 
        name: subject.name, 
        category: subject.category, 
        gradeRange: subject.gradeRange 
      });
    } else {
      setEditingSubject(null);
      setSubjectFormData({ 
        name: '', 
        category: 'STEM', 
        gradeRange: 'Grade 1 - Grade 6' 
      });
    }
    setIsSubjectModalOpen(true);
  };

  const handleSaveSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingSubject) {
      setSubjects(prev => prev.map(s => 
        s.id === editingSubject.id ? { ...s, ...subjectFormData } : s
      ));
    } else {
      const newSub: Subject = {
        id: `sub${Date.now()}`,
        ...subjectFormData
      };
      setSubjects(prev => [...prev, newSub]);
    }
    setIsSubjectModalOpen(false);
  };

  const handleDeleteSubject = (id: string) => {
    if (confirm('Are you sure you want to remove this subject from the school curriculum?')) {
      setSubjects(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleScoreChange = (studentId: string, scoreStr: string) => {
    const score = parseInt(scoreStr) || 0;
    setMarks(prev => prev.map(m => 
      m.studentId === studentId 
        ? { ...m, score, competency: schoolService.calculateCBCGrade(score) } 
        : m
    ));
  };

  const handleRemarkChange = (studentId: string, remarks: string) => {
    setMarks(prev => prev.map(m => m.studentId === studentId ? { ...m, remarks } : m));
  };

  const generateAIRemark = async (student: MarkEntry) => {
    if (!process.env.API_KEY) {
      handleRemarkChange(student.studentId, `${student.studentName} shows ${student.competency} in ${selectedSubject}. Keep it up!`);
      return;
    }

    setIsGeneratingRemarks(student.studentId);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Write a one-sentence professional teacher remark for a student named ${student.studentName} who scored ${student.score}% (CBC level: ${student.competency}) in ${selectedSubject}. Make it encouraging and specific to the grade level ${selectedClass}.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: promptText
      });
      handleRemarkChange(student.studentId, response.text || 'Commendable performance.');
    } catch (error) {
      console.error(error);
      handleRemarkChange(student.studentId, 'Performance is within expectations.');
    } finally {
      setIsGeneratingRemarks(null);
    }
  };

  const saveMarks = async () => {
    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1200));

    // Update the global students list with results
    setStudents(prev => prev.map(student => {
      const markEntry = marks.find(m => m.studentId === student.id);
      if (markEntry && selectedExam) {
        const result: ExamResult = {
          examId: selectedExam.id,
          subject: selectedSubject,
          score: markEntry.score,
          grade: markEntry.score >= 80 ? 'A' : markEntry.score >= 60 ? 'B' : markEntry.score >= 40 ? 'C' : 'D',
          competency: markEntry.competency,
          remarks: markEntry.remarks
        };

        const existingResults = student.results || [];
        const filteredResults = existingResults.filter(r => !(r.examId === selectedExam.id && r.subject === selectedSubject));

        return {
          ...student,
          results: [...filteredResults, result]
        };
      }
      return student;
    }));

    setIsSaving(false);
    alert('Marks successfully recorded and synced with student report cards.');
    setView('exams');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Academics & Assessments</h1>
          <p className="text-gray-500 font-medium">Manage CBC assessments and subject categories for PP1 - Grade 9.</p>
        </div>

        <div className="flex gap-2 no-print">
          {view === 'exams' && (
            <>
              <button 
                onClick={() => setView('subjects')}
                className="flex items-center space-x-2 border-2 border-gray-100 text-gray-600 px-6 py-3 rounded-2xl hover:bg-white hover:border-blue-100 transition-all font-black uppercase text-xs tracking-widest"
              >
                <BookMarked className="w-5 h-5" />
                <span>Curriculum</span>
              </button>
              <button 
                onClick={() => openExamModal()}
                className="flex items-center space-x-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-100"
              >
                <Plus className="w-5 h-5" />
                <span>Schedule Exam</span>
              </button>
            </>
          )}
          {view === 'subjects' && (
            <>
              <button 
                onClick={() => setView('exams')}
                className="flex items-center space-x-2 border-2 border-gray-100 text-gray-600 px-6 py-3 rounded-2xl hover:bg-white transition-all font-black uppercase text-xs tracking-widest"
              >
                <ArrowLeft className="w-5 h-5" />
                <span>Back to Exams</span>
              </button>
              <button 
                onClick={() => openSubjectModal()}
                className="flex items-center space-x-2 bg-blue-600 text-white px-8 py-3 rounded-2xl hover:bg-blue-700 transition-all font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-100"
              >
                <Plus className="w-5 h-5" />
                <span>Add Subject</span>
              </button>
            </>
          )}
        </div>
      </div>

      {view === 'exams' && (
        <div className="space-y-6 animate-in fade-in duration-300">
          <div className="bg-white p-8 rounded-[32px] border-2 border-gray-50 flex flex-col md:flex-row items-center gap-6 no-print shadow-sm">
             <div className="flex-1 w-full space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Select Target Class</label>
                <div className="relative">
                  <Search className="absolute left-3.5 top-3.5 w-5 h-5 text-gray-300" />
                  <select 
                    value={selectedClass} 
                    onChange={e => setSelectedClass(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-2xl font-black uppercase text-sm focus:border-blue-500 outline-none transition-all shadow-inner"
                  >
                    {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
                  </select>
                </div>
             </div>

             <div className="flex-1 w-full space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Select Subject</label>
                <select 
                  value={selectedSubject} 
                  onChange={e => setSelectedSubject(e.target.value)}
                  className="w-full p-3.5 bg-gray-50 border-2 border-gray-100 rounded-2xl font-black uppercase text-sm focus:border-blue-500 outline-none transition-all shadow-inner"
                >
                  {subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
             </div>

             <div className="w-full md:w-auto self-end">
                <div className="relative w-full">
                    <input 
                      type="text"
                      placeholder="Find exam..."
                      value={examSearch}
                      onChange={e => setExamSearch(e.target.value)}
                      className="w-full pl-10 pr-4 py-3.5 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none font-medium text-sm"
                    />
                    <Filter className="absolute left-3 top-4 w-4 h-4 text-gray-300" />
                </div>
             </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredExams.map(exam => (
              <div key={exam.id} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all group relative overflow-hidden">
                <div className="absolute -top-4 -right-4 p-8 opacity-5 group-hover:scale-110 transition-transform">
                  <LayoutGrid className="w-24 h-24" />
                </div>

                <div className="flex justify-between items-start mb-6">
                  <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl border border-white shadow-sm">
                    <BookOpen className="w-6 h-6" />
                  </div>
                  <div className="flex gap-2 no-print">
                    <button onClick={() => openExamModal(exam)} className="p-2.5 bg-gray-50 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all border border-transparent hover:border-blue-100"><Edit3 className="w-4 h-4" /></button>
                    <button onClick={() => handleDeleteExam(exam.id)} className="p-2.5 bg-gray-50 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all border border-transparent hover:border-red-100"><Trash2 className="w-4 h-4" /></button>
                  </div>
                </div>

                <div className="space-y-1">
                  <h3 className="text-xl font-black text-gray-900 tracking-tight leading-tight">{exam.title}</h3>
                  <div className="flex items-center gap-2 text-[10px] font-black text-blue-500 uppercase tracking-widest">
                    <span>Term {exam.term} • {exam.year}</span>
                    <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                    <span>{exam.type}</span>
                  </div>
                </div>

                <div className="mt-8 flex items-center justify-between gap-4">
                  <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1.5">
                    <CalendarDays className="w-3.5 h-3.5" />
                    {exam.date}
                  </div>
                  <button 
                    onClick={() => handleOpenMarkEntry(exam)}
                    className="flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-600 hover:text-white transition-all shadow-sm"
                  >
                    Enter Marks <ChevronRight className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
            {filteredExams.length === 0 && (
              <div className="col-span-full py-24 text-center border-2 border-dashed rounded-[40px] border-gray-100">
                <AlertCircle className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                <p className="text-gray-400 font-bold uppercase tracking-widest text-xs italic">No assessments found matching your criteria.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {view === 'subjects' && (
        <div className="bg-white rounded-[40px] shadow-sm border border-gray-100 overflow-hidden animate-in fade-in duration-300">
           <div className="p-8 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div className="relative flex-1 max-w-md">
                <Search className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" />
                <input 
                  type="text" 
                  placeholder="Search by area name or category..." 
                  value={subjectSearch}
                  onChange={e => setSubjectSearch(e.target.value)}
                  className="w-full pl-12 pr-4 py-3 bg-white border-2 border-gray-100 rounded-2xl focus:ring-4 focus:ring-blue-100 outline-none font-bold text-gray-700" 
                />
