  { id: 'u2', email: 'admin@school.ac.ke', password: 'adminpassword', name: 'Admin Kioko', role: UserRole.ADMIN, avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Kioko' },
  { id: 'u3', email: 'teacher@school.ac.ke', password: 'teacher123', name: 'Tr. Wambui', role: UserRole.CLASS_TEACHER, avatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Wambui' },
];

const INITIAL_FEE_STRUCTURE: ClassFee[] = KENYAN_CLASSES.map(cls => ({ className: cls, amount: 45000 }));

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentTab, setCurrentTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [lang, setLang] = useState<Language>('en');

  const [users, setUsers] = useState<User[]>(() => {
    try {
      const saved = localStorage.getItem('elimusmart_users');
      return saved ? JSON.parse(saved) : INITIAL_USERS;
    } catch (e) {
      return INITIAL_USERS;
    }
  });

  const [students, setStudents] = useState<Student[]>(() => {
    try {
      const saved = localStorage.getItem('elimusmart_students');
      return saved ? JSON.parse(saved) : INITIAL_STUDENTS;
    } catch (e) {
      console.error("Failed to parse students from localStorage", e);
      return INITIAL_STUDENTS;
    }
  });

  const [feeStructure, setFeeStructure] = useState<ClassFee[]>(() => {
    try {
      const saved = localStorage.getItem('elimusmart_fees');
      return saved ? JSON.parse(saved) : INITIAL_FEE_STRUCTURE;
    } catch (e) {
      return INITIAL_FEE_STRUCTURE;
    }
  });

  const [schoolLogo, setSchoolLogo] = useState<string | null>(() => {
    return localStorage.getItem('elimusmart_logo');
  });

  useEffect(() => {
    localStorage.setItem('elimusmart_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('elimusmart_students', JSON.stringify(students));
  }, [students]);

  useEffect(() => {
    localStorage.setItem('elimusmart_fees', JSON.stringify(feeStructure));
  }, [feeStructure]);

  useEffect(() => {
    if (schoolLogo) localStorage.setItem('elimusmart_logo', schoolLogo);
    else localStorage.removeItem('elimusmart_logo');
  }, [schoolLogo]);

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallPop, setShowInstallPop] = useState(false);
  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);

    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      if (!window.matchMedia('(display-mode: standalone)').matches) {
        setTimeout(() => setShowInstallPop(true), 4000);
      }
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallApp = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then(() => {
        setDeferredPrompt(null);
        setShowInstallPop(false);
      });
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const foundUser = users.find(u => u.email === username.toLowerCase() && u.password === password);
    if (foundUser) {
      setUser(foundUser);
      setCurrentTab('dashboard');
    } else {
      alert('Authentication Failed: Incorrect email or password.');
    }
  };

  const switchRole = (role: UserRole) => {
    const roleUser = users.find(u => u.role === role);
    if (roleUser) {
      setUser(roleUser);
      setCurrentTab('dashboard');
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-blue-700 p-4 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600 rounded-full -mr-48 -mt-48 opacity-50 blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-blue-800 rounded-full -ml-32 -mb-32 opacity-50 blur-3xl"></div>

        <div className="bg-white rounded-[40px] shadow-2xl p-10 max-w-lg w-full relative z-10 animate-in fade-in zoom-in duration-500">
          <div className="text-center mb-10">
            <div className="bg-blue-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-xl shadow-blue-100">
               <ShieldCheck className="text-white w-8 h-8" />
            </div>
            <h1 className="text-4xl font-black text-gray-900 tracking-tighter leading-none">ElimuSmart</h1>
            <p className="text-gray-400 font-bold uppercase text-[10px] tracking-widest mt-2 leading-none">Secure School Environment</p>
          </div>
          <form className="space-y-6" onSubmit={handleLogin}>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Email Address</label>
              <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all" placeholder="name@school.ac.ke" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Secure Password</label>
              <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all" placeholder="••••••••" />
            </div>
            <button type="submit" className="w-full bg-blue-600 text-white font-black py-5 rounded-2xl uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95">Enter System Portal</button>
          </form>

          <div className="mt-8 text-center">
             <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest leading-relaxed">
               Authorized Personnel Only. All access is logged for institutional integrity.
             </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      currentTab={currentTab} 
      setCurrentTab={setCurrentTab}
      isSidebarOpen={isSidebarOpen}
      setIsSidebarOpen={setIsSidebarOpen}
      logout={() => setUser(null)}
      lang={lang}
      setLang={setLang}
      switchRole={switchRole}
      installApp={(deferredPrompt || isIOS) ? () => setShowInstallPop(true) : undefined}
    >
      {showInstallPop && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[200] w-full max-w-md px-4 animate-in slide-in-from-top-4 duration-500">
          <div className="bg-white rounded-[32px] shadow-[0_20px_50px_rgba(0,0,0,0.2)] p-6 border-2 border-blue-50 flex items-center gap-6 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <Smartphone size={100} />
             </div>
             <div className="bg-blue-600 text-white p-4 rounded-2xl shadow-xl shadow-blue-100 shrink-0">
                <Smartphone size={24} />
             </div>
             <div className="flex-1">
                <h4 className="text-sm font-black text-gray-900 uppercase tracking-tight">{isIOS ? 'Install on iPhone' : 'Offline Access Ready'}</h4>
                <p className="text-[11px] font-bold text-gray-500 leading-tight mt-1">
                  {isIOS ? 'Tap Share and "Add to Home Screen"' : 'Install ElimuSmart for the best experience.'}
                </p>
                <div className="flex gap-2 mt-4">
                   {!isIOS && (
                     <button onClick={handleInstallApp} className="bg-blue-600 text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-100 flex items-center gap-2">
                       <Check size={14} /> Install Now
                     </button>
                   )}
                   {isIOS && (
                     <div className="flex items-center gap-2 text-[10px] font-black uppercase text-blue-600 bg-blue-50 px-3 py-2 rounded-xl">
                        <Share size={14} /> Share Menu
                     </div>
                   )}
                   <button onClick={() => setShowInstallPop(false)} className="bg-gray-100 text-gray-500 px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest">
                     Close
                   </button>
                </div>
             </div>
             <button onClick={() => setShowInstallPop(false)} className="absolute top-4 right-4 text-gray-300 hover:text-gray-500"><X size={18} /></button>
          </div>
        </div>
      )}

      <main className="p-4 md:p-8 max-w-[1600px] mx-auto">
        {currentTab === 'dashboard' && <Dashboard user={user} lang={lang} students={students} />}
        {currentTab === 'students' && <StudentManagement students={students} setStudents={setStudents} feeStructure={feeStructure} />}
        {currentTab === 'staff' && <StaffManagement />}
        {currentTab === 'academics' && <AcademicsModule lang={lang} students={students} setStudents={setStudents} />}
        {currentTab === 'timetable' && <TimetableModule lang={lang} />}
        {currentTab === 'finance' && <FinanceModule lang={lang} students={students} setStudents={setStudents} feeStructure={feeStructure} setFeeStructure={setFeeStructure} schoolLogo={schoolLogo} />}
        {currentTab === 'attendance' && <AttendanceModule lang={lang} />}
        {currentTab === 'messaging' && <MessagingModule lang={lang} students={students} />}
        {currentTab === 'reports' && <ReportsModule lang={lang} students={students} />}
        {currentTab === 'settings' && (
          <SettingsModule 
            currentUser={user} 
            users={users} 
            setUsers={setUsers} 
            schoolLogo={schoolLogo} 
            setSchoolLogo={setSchoolLogo} 
          />
        )}
      </main>
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Settings as SettingsIcon, 
  School, 
  Calendar, 
  Shield, 
  Bell, 
  User, 
  Save, 
  Loader2, 
  Database,
  History,
  Lock,
  Upload,
  Camera,
  Trash2,
  Users,
  Plus,
  Key
} from 'lucide-react';
import { AcademicConfig, schoolService } from '../services/schoolService';
import { UserRole, User as UserType } from '../types';

interface SettingsModuleProps {
  currentUser: UserType;
  users: UserType[];
  setUsers: React.Dispatch<React.SetStateAction<UserType[]>>;
  schoolLogo: string | null;
  setSchoolLogo: (logo: string | null) => void;
}

export const SettingsModule: React.FC<SettingsModuleProps> = ({ 
  currentUser, 
  users, 
  setUsers, 
  schoolLogo, 
  setSchoolLogo 
}) => {
  const [activeSection, setActiveSection] = useState<'profile' | 'school' | 'academic' | 'security' | 'users'>('profile');
  const [config, setConfig] = useState<AcademicConfig | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Security State
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // User Management State
  const [isAddUserModalOpen, setIsAddUserModalOpen] = useState(false);
  const [newUser, setNewUser] = useState<Partial<UserType>>({
    name: '',
    email: '',
    role: UserRole.SUBJECT_TEACHER,
    password: ''
  });

  useEffect(() => {
    schoolService.getAcademicConfig().then(setConfig);
  }, []);

  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isAdminOrPrincipal = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.PRINCIPAL;

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSchoolLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      alert('Error: New passwords do not match.');
      return;
    }
    if (currentPassword !== currentUser.password) {
      alert('Error: Current password is incorrect.');
      return;
    }

    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1000));

    setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, password: newPassword } : u));

    setIsSaving(false);
    alert('Security Update: Password successfully changed.');
    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.name || !newUser.email || !newUser.password) return;

    const userToAdd: UserType = {
      id: `u${Date.now()}`,
      name: newUser.name,
      email: newUser.email.toLowerCase(),
      role: newUser.role as UserRole,
      password: newUser.password,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${newUser.name}`
    };

    setUsers(prev => [...prev, userToAdd]);
    setIsAddUserModalOpen(false);
    setNewUser({ name: '', email: '', role: UserRole.SUBJECT_TEACHER, password: '' });
  };

  const handleDeleteUser = (id: string) => {
    if (id === currentUser.id) {
      alert("Error: You cannot delete your own active session.");
      return;
    }
    if (window.confirm('Security Warning: Are you sure you want to permanently revoke this user\'s access?')) {
      setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  const handleSaveSchoolInfo = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1500));
    setIsSaving(false);
    alert('School configuration updated successfully!');
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">System Management</h1>
          <p className="text-gray-500 font-medium">Core platform configuration and administrative controls.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="md:col-span-1 space-y-1">
          <nav className="bg-white rounded-2xl border border-gray-100 p-2 shadow-sm">
            <NavItem icon={User} label="Personal Profile" active={activeSection === 'profile'} onClick={() => setActiveSection('profile')} />
            {isAdminOrPrincipal && (
              <>
                <NavItem icon={School} label="School Profile" active={activeSection === 'school'} onClick={() => setActiveSection('school')} />
                <NavItem icon={Calendar} label="Academic Term" active={activeSection === 'academic'} onClick={() => setActiveSection('academic')} />
              </>
            )}
            {isAdmin && (
              <NavItem icon={Users} label="User Accounts" active={activeSection === 'users'} onClick={() => setActiveSection('users')} />
            )}
            <NavItem icon={Lock} label="Security" active={activeSection === 'security'} onClick={() => setActiveSection('security')} />
          </nav>
        </div>

        <div className="md:col-span-3">
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden min-h-[500px]">

            {activeSection === 'profile' && (
              <div className="p-8 space-y-6 animate-in fade-in duration-300">
                <h3 className="text-lg font-black border-b pb-4 uppercase tracking-tight text-gray-800">My Identity</h3>
                <div className="flex items-center gap-6 p-6 bg-gray-50 rounded-2xl">
                   <img src={currentUser.avatar} className="w-20 h-20 rounded-2xl border-4 border-white shadow-md" alt="Avatar" />
                   <div>
                      <p className="text-2xl font-black text-gray-900 leading-none">{currentUser.name}</p>
                      <p className="text-xs font-black text-blue-600 uppercase tracking-widest mt-2">{currentUser.role.replace('_', ' ')}</p>
                      <p className="text-[10px] text-gray-400 font-medium mt-1">{currentUser.email}</p>
                   </div>
                </div>
              </div>
            )}

            {activeSection === 'users' && isAdmin && (
              <div className="p-8 space-y-6 animate-in fade-in duration-300">
                <div className="flex items-center justify-between border-b pb-4">
                   <h3 className="text-lg font-black uppercase tracking-tight text-gray-800">Platform Users</h3>
                   <button onClick={() => setIsAddUserModalOpen(true)} className="flex items-center gap-2 bg-blue-600 text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
                     <Plus className="w-4 h-4" /> Add User
                   </button>
                </div>

                <div className="divide-y border rounded-2xl overflow-hidden">
                  {users.map(u => (
                    <div key={u.id} className="p-4 flex items-center justify-between hover:bg-gray-50 transition-colors">
                       <div className="flex items-center gap-4">
                          <img src={u.avatar} className="w-10 h-10 rounded-xl border bg-white" />
                          <div>
                            <p className="font-black text-gray-900 text-sm">{u.name}</p>
                            <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">{u.role}</p>
                          </div>
                       </div>
                       <div className="flex items-center gap-4">
                          <div className="text-right">
                             <p className="text-[10px] text-gray-400 font-medium">{u.email}</p>
                             <p className="text-[9px] font-mono text-gray-300">ID: {u.id}</p>
                          </div>
                          <button 
                            onClick={() => handleDeleteUser(u.id)}
                            className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                            title="Revoke Access"
                          >
                            <Trash2 className="w-5 h-5" />
                          </button>
                       </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeSection === 'security' && (
              <form onSubmit={handleUpdatePassword} className="p-8 space-y-8 animate-in fade-in duration-300">
                <div className="flex items-center gap-4 border-b pb-4">
                   <Key className="text-blue-600 w-6 h-6" />
                   <h3 className="text-lg font-black uppercase tracking-tight text-gray-800">Credentials Management</h3>
                </div>

                <div className="max-w-md space-y-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Current Password</label>
                      <input required type="password" value={currentPassword} onChange={e => setCurrentPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                   </div>
                   <div className="space-y-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">New Password</label>
                        <input required type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Confirm New Password</label>
                        <input required type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                      </div>
                   </div>
                   <button 
                    type="submit"
                    disabled={isSaving}
                    className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-gray-200 disabled:opacity-50 flex items-center justify-center gap-3"
                   >
                     {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                     Commit Security Change
                   </button>
                </div>
              </form>
            )}

            {activeSection === 'school' && isAdminOrPrincipal && (
              <form onSubmit={handleSaveSchoolInfo} className="p-8 space-y-8 animate-in fade-in duration-300">
                <h3 className="text-lg font-black border-b pb-4 text-blue-900 uppercase tracking-tight">Institutional Profile</h3>

                <div className="flex flex-col sm:flex-row gap-8 p-8 bg-blue-50/50 rounded-3xl border border-blue-100 relative">
                  <div className="relative group z-10">
                    <div className="w-40 h-40 rounded-3xl bg-white border-4 border-white shadow-2xl flex items-center justify-center overflow-hidden">
                      <img src={schoolLogo || `https://api.dicebear.com/7.x/initials/svg?seed=${config?.schoolName || 'School'}&backgroundColor=1e3a8a&fontFamily=Inter&fontSize=45&bold=true`} alt="Logo" className="w-full h-full object-cover" />
                    </div>
                    <label className="absolute -bottom-3 -right-3 bg-blue-600 text-white p-3 rounded-2xl shadow-xl cursor-pointer hover:bg-blue-700 transition-all border-4 border-white">
                      <Camera className="w-5 h-5" />
                      <input type="file" className="hidden" accept="image/*" onChange={handleLogoChange} />
                    </label>
                  </div>

                  <div className="flex-1 flex flex-col justify-center">
                    <h4 className="text-xl font-black text-blue-900 uppercase tracking-tight">{config?.schoolName}</h4>
                    <p className="text-[10px] text-blue-600 font-black uppercase tracking-widest mt-1 opacity-70">Main Digital Seal</p>
                    <div className="mt-6 flex gap-3">
                       <button type="button" onClick={() => setSchoolLogo(null)} className="text-[10px] font-black uppercase text-red-500 hover:text-red-700 transition-colors">Remove Custom Logo</button>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Official Name</label>
                    <input type="text" defaultValue={config?.schoolName} className="w-full p-3 border rounded-xl font-bold" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Reg No.</label>
                    <input type="text" defaultValue={config?.registrationNo} className="w-full p-3 border rounded-xl font-mono font-bold" />
                  </div>
                  <div className="col-span-2 space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">School Motto</label>
                    <input type="text" defaultValue={config?.motto} className="w-full p-3 border rounded-xl font-bold" />
                  </div>
                </div>
                <div className="flex justify-end">
                   <button type="submit" className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-100">Save Changes</button>
                </div>
              </form>
            )}

            {activeSection === 'academic' && isAdminOrPrincipal && (
              <div className="p-8 space-y-6 animate-in fade-in duration-300">
                <h3 className="text-lg font-black border-b pb-4 text-indigo-900 uppercase tracking-tight">Active Session</h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                   <div className="p-6 bg-indigo-50 rounded-2xl border border-indigo-100">
                      <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Current Year</p>
                      <p className="text-3xl font-black text-indigo-900 leading-none">{config?.year}</p>
                   </div>
                   <div className="p-6 bg-indigo-50 rounded-2xl border border-indigo-100">
                      <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Active Term</p>
                      <p className="text-3xl font-black text-indigo-900 leading-none">Term {config?.term}</p>
                   </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Add User Modal */}
      {isAddUserModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md animate-in fade-in duration-200">
           <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                 <div>
                    <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">New Credentials</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2">Create Secure System Account</p>
                 </div>
                 <button onClick={() => setIsAddUserModalOpen(false)} className="p-4 hover:bg-red-50 text-gray-400 hover:text-red-600 rounded-full transition-all">
                    <Trash2 className="w-6 h-6" />
                 </button>
              </div>

              <form onSubmit={handleAddUser} className="p-8 space-y-6">
                 <div className="space-y-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Full Name</label>
                       <input required type="text" value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Email Address</label>
                       <input required type="email" value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">System Role</label>
                       <select value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as UserRole})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner">
                          {Object.values(UserRole).map(r => <option key={r} value={r}>{r.replace('_', ' ')}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Initial Password</label>
                       <input required type="password" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                    </div>
                 </div>

                 <div className="flex gap-4 pt-6">
                    <button type="button" onClick={() => setIsAddUserModalOpen(false)} className="flex-1 py-4 text-gray-400 font-black uppercase text-xs tracking-widest">Discard</button>
                    <button type="submit" className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all">Confirm Account</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

const NavItem: React.FC<{ icon: any, label: string, active: boolean, onClick: () => void }> = ({ icon: Icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-sm font-black uppercase tracking-tighter transition-all ${active ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'text-gray-500 hover:bg-gray-50 hover:text-gray-900'}`}
  >
    <Icon className={`w-5 h-5 ${active ? 'text-white' : 'text-gray-400'}`} />
    <span>{label}</span>
  </button>
);

import React, { useState, useMemo, useEffect } from 'react';
import { 
  AlertCircle, 
  Loader2, 
  Printer, 
  Download, 
  Target, 
  Banknote, 
  Forward, 
  CreditCard, 
  Save, 
  ShieldAlert, 
  Zap, 
  X, 
  CheckCircle2, 
  FileDown,
  User,
  Hash,
  Smartphone,
  Search,
  FileSpreadsheet
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student, ClassFee } from '../types';
import { schoolService, AcademicConfig } from '../services/schoolService';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
  setFeeStructure: React.Dispatch<React.SetStateAction<ClassFee[]>>;
  schoolLogo: string | null;
}

interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: 'M-PESA' | 'BANK' | 'CASH';
  reference: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, feeStructure, setFeeStructure, schoolLogo }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [financeSearch, setFinanceSearch] = useState('');
  const [isPosting, setIsPosting] = useState(false);
  const [isApplyingFees, setIsApplyingFees] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);
  const [config, setConfig] = useState<AcademicConfig | null>(null);

  const [globalFeeValue, setGlobalFeeValue] = useState<string>('');
  const [paymentForm, setPaymentForm] = useState({ 
    adm: '', 
    amount: '', 
    method: 'M-PESA' as 'M-PESA' | 'BANK' | 'CASH', 
    reference: '' 
  });

  useEffect(() => {
    schoolService.getAcademicConfig().then(setConfig);
  }, []);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const matchesClass = selectedClass === 'All Classes' || s.class === selectedClass;
      const term = financeSearch.toLowerCase();
      const matchesSearch = 
        s.firstName.toLowerCase().includes(term) || 
        s.lastName.toLowerCase().includes(term) || 
        s.admissionNumber.toLowerCase().includes(term);
      return matchesClass && matchesSearch;
    });
  }, [students, selectedClass, financeSearch]);

  const financeStats = useMemo(() => {
    const totalExpected = filteredStudents.reduce((sum, s) => sum + (s.totalFee || 0), 0);
    const totalCollected = filteredStudents.reduce((sum, s) => sum + (s.paidFee || 0), 0);
    const totalOutstanding = filteredStudents.reduce((sum, s) => sum + (s.feeBalance || 0), 0);
    const totalPrepaid = filteredStudents.reduce((sum, s) => sum + (s.prepaidFee || 0), 0);
    return { expected: totalExpected, collected: totalCollected, outstanding: totalOutstanding, prepaid: totalPrepaid };
  }, [filteredStudents]);

  const handleUpdateClassFee = (className: string, value: string) => {
    const amount = parseFloat(value) || 0;
    setFeeStructure(prev => prev.map(f => f.className === className ? { ...f, amount } : f));
  };

  const applyGlobalFee = () => {
    const amount = parseFloat(globalFeeValue) || 0;
    if (amount <= 0) return;
    setFeeStructure(prev => prev.map(f => ({ ...f, amount })));
    setGlobalFeeValue('');
  };

  const syncFeesToStudents = async () => {
    setIsApplyingFees(true);
    await new Promise(r => setTimeout(r, 1200));

    setStudents(prev => prev.map(student => {
      const structure = feeStructure.find(f => f.className === student.class);
      if (structure) {
        const newTotal = structure.amount;
        const paid = student.paidFee || 0;
        let newBalance = newTotal - paid;
        let newPrepaid = 0;
        if (newBalance < 0) {
          newPrepaid = Math.abs(newBalance);
          newBalance = 0;
        }
        return { ...student, totalFee: newTotal, feeBalance: newBalance, prepaidFee: newPrepaid };
      }
      return student;
    }));

    setIsApplyingFees(false);
    alert('Synchronization Successful! All student balances recalculated based on the updated Class Fee Structure.');
  };

  const handlePostPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentForm.adm || !paymentForm.amount) return;
    setIsPosting(true);

    await new Promise(r => setTimeout(r, 800));

    const amountNum = parseFloat(paymentForm.amount);
    let updatedStudent: Student | undefined;

    setStudents(prev => prev.map(s => {
      if (s.admissionNumber === paymentForm.adm) {
        const newPaid = (s.paidFee || 0) + amountNum;
        let newBalance = (s.totalFee || 0) - newPaid;
        let newPrepaid = s.prepaidFee || 0;
        if (newBalance < 0) {
          newPrepaid += Math.abs(newBalance);
          newBalance = 0;
        }
        updatedStudent = { ...s, paidFee: newPaid, feeBalance: newBalance, prepaidFee: newPrepaid };
        return updatedStudent;
      }
      return s;
    }));

    if (updatedStudent) {
      const receipt: TransactionReceipt = {
        receiptNo: `RCP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        studentName: `${updatedStudent.firstName} ${updatedStudent.lastName}`,
        adm: updatedStudent.admissionNumber,
        class: updatedStudent.class,
        amount: amountNum,
        method: paymentForm.method,
        reference: paymentForm.reference || 'CASH_ENTRY',
        date: new Date().toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }),
        balance: updatedStudent.feeBalance,
        servedBy: 'System Admin'
      };
      setLastReceipt(receipt);
      setShowReceipt(true);
    }

    setIsPosting(false);
    setPaymentForm({ adm: '', amount: '', method: 'M-PESA', reference: '' });
  };

  const exportToPDF = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    const h2p = (window as any).html2pdf;
    if (typeof h2p === 'function') {
      h2p().set(opt).from(element).save();
    } else {
      window.print();
    }
  };

  const handleIndividualExportExcel = (student: Student) => {
    const data = [{
      'Admission Number': student.admissionNumber,
      'Name': `${student.firstName} ${student.lastName}`,
      'Class': student.class,
      'Stream': student.stream,
      'Total Termly Invoice': student.totalFee,
      'Total Paid to Date': student.paidFee,
      'Prepaid/Credit': student.prepaidFee,
      'Outstanding Balance': student.feeBalance,
      'Statement Date': new Date().toLocaleDateString()
    }];
    const ws = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, ws, "Fee Statement");
    XLSX.writeFile(workbook, `FeeStatement_${student.admissionNumber}.xlsx`);
  };

  const handleIndividualExportPDF = (student: Student) => {
    const mockStatement: TransactionReceipt = {
        receiptNo: "STMT-" + student.admissionNumber,
        studentName: `${student.firstName} ${student.lastName}`,
        adm: student.admissionNumber,
        class: student.class,
        amount: student.paidFee, 
        method: "CASH",
        reference: "TERM_STATEMENT",
        date: new Date().toLocaleDateString(),
        balance: student.feeBalance,
        servedBy: "Ledger Export"
    };
    setLastReceipt(mockStatement);
    setTimeout(() => {
        exportToPDF('receipt-print-template', `FeeStatement_${student.admissionNumber}.pdf`);
    }, 100);
  };

  return (
    <div className="space-y-8 pb-20">
      <div id="receipt-print-template" className="offscreen-template">
        {lastReceipt && (
          <div style={{ padding: '40px', background: 'white', color: 'black', fontFamily: 'Inter, sans-serif' }}>
            <div style={{ borderBottom: '2px solid #1e3a8a', paddingBottom: '20px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                {schoolLogo ? (
                  <img src={schoolLogo} style={{ width: '80px', height: '80px', borderRadius: '12px', objectFit: 'cover' }} />
                ) : (
                  <div style={{ width: '80px', height: '80px', borderRadius: '12px', background: '#1e3a8a', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 'bold', fontSize: '24px' }}>ES</div>
                )}
                <div>
                  <h1 style={{ margin: '0', fontSize: '24px', fontWeight: 'bold', color: '#1e3a8a' }}>{config?.schoolName || 'ElimuSmart Academy'}</h1>
                  <p style={{ margin: '5px 0', fontSize: '12px', fontStyle: 'italic' }}>{config?.motto || 'Excellence in Knowledge and Character'}</p>
                  <p style={{ margin: '0', fontSize: '10px', color: '#666' }}>Reg No: {config?.registrationNo || 'N/A'}</p>
                  <p style={{ margin: '2px 0', fontSize: '10px' }}>P.O BOX 1234 - 00100, Nairobi | Tel: +254 700 000 000</p>
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '18px' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Fee Statement' : 'Payment Receipt'}</h2>
                <p style={{ margin: '5px 0', fontWeight: 'bold' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Date: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ marginBottom: '30px', background: '#f8fafc', padding: '20px', borderRadius: '12px' }}>
              <p style={{ margin: '5px 0' }}><strong>Student Name:</strong> {lastReceipt.studentName}</p>
              <p style={{ margin: '5px 0' }}><strong>ADM Number:</strong> {lastReceipt.adm}</p>
              <p style={{ margin: '5px 0' }}><strong>Grade / Level:</strong> {lastReceipt.class}</p>
            </div>

            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '30px' }}>
              <thead>
                <tr style={{ background: '#1e3a8a', color: 'white' }}>
                  <th style={{ padding: '12px', border: '1px solid #1e3a8a', textAlign: 'left', fontSize: '12px', textTransform: 'uppercase' }}>Description of Transaction</th>
                  <th style={{ padding: '12px', border: '1px solid #1e3a8a', textAlign: 'right', fontSize: '12px', textTransform: 'uppercase' }}>Amount (KES)</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ padding: '15px', border: '1px solid #ddd' }}>
                    <div style={{ fontWeight: 'bold' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Full Tuition & Amenities Fees' : 'School Fees Installment'}</div>
                    <div style={{ fontSize: '10px', color: '#666', marginTop: '4px' }}>Mode: {lastReceipt.method} | Ref: {lastReceipt.reference}</div>
                  </td>
                  <td style={{ padding: '15px', border: '1px solid #ddd', textAlign: 'right', fontWeight: 'bold', fontSize: '16px' }}>{lastReceipt.amount.toLocaleString()}.00</td>
                </tr>
              </tbody>
            </table>

            <div style={{ textAlign: 'right', marginBottom: '50px' }}>
              <div style={{ display: 'inline-block', padding: '15px 30px', border: '2px solid #1e3a8a', borderRadius: '12px' }}>
                <p style={{ margin: '0', fontSize: '10px', textTransform: 'uppercase', color: '#666' }}>Current Outstanding Balance</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '24px', fontWeight: 'black', color: '#1e3a8a' }}>KES {lastReceipt.balance.toLocaleString()}.00</p>
              </div>
            </div>

            <div style={{ borderTop: '1px solid #ddd', paddingTop: '30px', display: 'flex', justifyContent: 'space-between' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '200px', marginBottom: '5px' }}></div>
                <p style={{ fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase' }}>Accounts Department</p>
                <p style={{ fontSize: '9px', color: '#666' }}>ID: {lastReceipt.servedBy}</p>
              </div>
              <div style={{ textAlign: 'center', position: 'relative' }}>
                <div style={{ border: '3px double #1e3a8a', borderRadius: '50%', width: '100px', height: '100px', display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: '0.1', transform: 'rotate(-15deg)' }}>
                  <div style={{ fontSize: '10px', fontWeight: 'black', textAlign: 'center' }}>OFFICIAL<br/>SCHOOL<br/>STAMP</div>
                </div>
                <div style={{ borderBottom: '1px solid black', width: '200px', marginBottom: '5px', marginTop: '-40px' }}></div>
                <p style={{ fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase' }}>Verification Stamp</p>
              </div>
            </div>

            <div style={{ marginTop: '40px', textAlign: 'center', borderTop: '1px dashed #eee', paddingTop: '10px' }}>
              <p style={{ fontSize: '9px', color: '#999', margin: '0' }}>This is an electronically generated document. Powered by ElimuSmart Cloud ERP.</p>
            </div>
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Finance Center</h1>
          <p className="text-gray-500 font-medium">Automatic billing and student ledger management.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="p-3 bg-white border-2 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-500 transition-all shadow-sm">
            <option>All Classes</option>
            {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
          </select>
          <div className="flex p-1 bg-gray-100 rounded-2xl shadow-inner">
            <button onClick={() => setActiveTab('class-summary')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'class-summary' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Ledger</button>
            <button onClick={() => setActiveTab('fee-structure')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'fee-structure' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Fee Settings</button>
            <button onClick={() => setActiveTab('payments')} className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'payments' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Post Receipt</button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: 'Expected Revenue', value: financeStats.expected, icon: Target, color: 'indigo' },
          { label: 'Amount Collected', value: financeStats.collected, icon: Banknote, color: 'green' },
          { label: 'Outstanding Debt', value: financeStats.outstanding, icon: AlertCircle, color: 'red' },
          { label: 'Credit Balance', value: financeStats.prepaid, icon: Forward, color: 'blue' },
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-6 rounded-3xl border border-gray-100 flex items-start justify-between shadow-sm hover:shadow-md transition-shadow">
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none mb-2">{stat.label}</p>
              <h3 className={`text-2xl font-black tracking-tight ${stat.color === 'red' ? 'text-red-700' : stat.color === 'green' ? 'text-green-700' : 'text-gray-900'}`}>
                <span className="text-xs font-medium mr-1 opacity-40">KES</span>
                {stat.value.toLocaleString()}
              </h3>
            </div>
            <div className={`p-3 rounded-2xl bg-${stat.color}-50 text-${stat.color}-600 border border-${stat.color}-100`}>
              <stat.icon className="w-5 h-5" />
            </div>
          </div>
        ))}
      </div>

      {activeTab === 'class-summary' && (
        <div className="bg-white rounded-[40px] border border-gray-100 overflow-hidden shadow-sm animate-in fade-in duration-300">
          <div className="p-8 border-b bg-gray-50/50 flex flex-col md:flex-row md:items-center justify-between gap-4">
             <div className="flex-1 flex items-center gap-4">
                <div className="relative flex-1 max-w-sm">
                   <Search className="absolute left-3.5 top-3 w-4 h-4 text-gray-400" />
                   <input 
                      type="text" 
                      placeholder="Find student by name or ADM..." 
                      value={financeSearch}
                      onChange={(e) => setFinanceSearch(e.target.value)}
                      className="w-full pl-10 pr-4 py-2.5 bg-white border-2 border-gray-100 rounded-xl focus:border-blue-500 outline-none font-medium transition-all text-sm shadow-inner"
                   />
                </div>
             </div>
             <button onClick={() => exportToPDF('class-ledger-table', `Global_Ledger_${selectedClass}.pdf`)} className="p-3 bg-white border-2 border-gray-100 rounded-2xl text-gray-600 hover:text-blue-600 hover:border-blue-200 transition-all flex items-center gap-2 font-black uppercase text-[10px] tracking-widest shadow-sm">
                <FileSpreadsheet className="w-4 h-4 text-emerald-600" /> Full Class Ledger
             </button>
          </div>
          <div className="overflow-x-auto" id="class-ledger-table">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b text-[10px] text-gray-400 uppercase font-black tracking-widest">
                  <th className="px-8 py-6">Student Information</th>
                  <th className="px-8 py-6 text-center">Invoiced</th>
                  <th className="px-8 py-6 text-center">Paid</th>
                  <th className="px-8 py-6 text-center">Balance</th>
                  <th className="px-8 py-6 text-right">Statements</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filteredStudents.map((s, idx) => (
                  <tr key={idx} className="hover:bg-blue-50/10 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="font-black text-gray-900 text-lg leading-tight">{s.firstName} {s.lastName}</div>
                      <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">{s.admissionNumber} • {s.class}</div>
                    </td>
                    <td className="px-8 py-6 text-center font-bold text-gray-700">KES {(s.totalFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-bold text-green-600">KES {(s.paidFee || 0).toLocaleString()}</td>
                    <td className="px-8 py-6 text-center font-black">
                       <span className={s.feeBalance > 0 ? 'text-red-600' : 'text-green-600'}>
                         KES {(s.feeBalance || 0).toLocaleString()}
                       </span>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleIndividualExportExcel(s)}
                          className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-transparent hover:border-emerald-100"
                          title="Export Excel Ledger"
                        >
                          <FileSpreadsheet className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={() => handleIndividualExportPDF(s)}
                          className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-all border border-transparent hover:border-blue-100"
                          title="Generate PDF Statement"
                        >
                          <FileDown className="w-5 h-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredStudents.length === 0 && (
