      <div id="receipt-print-template" className="offscreen-template">
        {lastReceipt && (
          <div style={{ padding: '60px', background: 'white', color: 'black', fontFamily: 'Inter, sans-serif' }}>
            <div style={{ borderBottom: '4px solid #1e3a8a', paddingBottom: '30px', marginBottom: '40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '30px' }}>
                {schoolLogo ? (
                  <img src={schoolLogo} style={{ width: '100px', height: '100px', borderRadius: '15px', objectFit: 'cover' }} />
                ) : (
                  <div style={{ width: '100px', height: '100px', borderRadius: '15px', background: '#1e3a8a', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: '900', fontSize: '36px' }}>ES</div>
                )}
                <div>
                  <h1 style={{ margin: '0', fontSize: '28px', fontWeight: '900', color: '#1e3a8a', textTransform: 'uppercase' }}>{schoolConfig?.schoolName || 'ElimuSmart Academy'}</h1>
                  <p style={{ margin: '5px 0', fontSize: '13px', fontStyle: 'italic', fontWeight: 'bold', color: '#4b5563' }}>{schoolConfig?.motto || 'Excellence in Knowledge and Character'}</p>
                  <p style={{ margin: '0', fontSize: '11px', fontWeight: '900', color: '#6b7280', textTransform: 'uppercase' }}>Reg No: {schoolConfig?.registrationNo || 'N/A'}</p>
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '18px', fontWeight: '900', color: '#1e3a8a' }}>OFFICIAL PAYMENT RECEIPT</h2>
                <p style={{ margin: '8px 0', fontWeight: '900', fontSize: '14px', color: '#ef4444' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '11px', color: '#9ca3af', fontWeight: 'bold' }}>DATE: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: '40px', marginBottom: '40px', background: '#f8fafc', padding: '30px', borderRadius: '20px', border: '1px solid #e2e8f0' }}>
              <div>
                <p style={{ margin: '0 0 10px 0', fontSize: '10px', fontWeight: '900', color: '#94a3b8', textTransform: 'uppercase' }}>Student Information</p>
                <p style={{ margin: '0', fontSize: '20px', fontWeight: '900', color: '#0f172a' }}>{lastReceipt.studentName}</p>
                <p style={{ margin: '5px 0', fontSize: '14px', fontWeight: 'bold' }}>ADM: <span style={{ color: '#2563eb' }}>{lastReceipt.adm}</span></p>
                <p style={{ margin: '0', fontSize: '14px', fontWeight: 'bold' }}>CLASS: {lastReceipt.class}</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <p style={{ margin: '0 0 10px 0', fontSize: '10px', fontWeight: '900', color: '#94a3b8', textTransform: 'uppercase' }}>Payment Details</p>
                <p style={{ margin: '0', fontSize: '18px', fontWeight: '900', color: '#059669' }}>{lastReceipt.method}</p>
                <p style={{ margin: '5px 0', fontSize: '12px', color: '#64748b' }}>Bank Ref: {lastReceipt.reference}</p>
              </div>
            </div>

            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '40px' }}>
              <thead>
                <tr style={{ background: '#1e3a8a', color: 'white' }}>
                  <th style={{ padding: '15px 20px', textAlign: 'left', fontSize: '11px', textTransform: 'uppercase', fontWeight: '900' }}>Item Description</th>
                  <th style={{ padding: '15px 20px', textAlign: 'right', fontSize: '11px', textTransform: 'uppercase', fontWeight: '900' }}>Amount Paid (KES)</th>
