              <tbody>
                <tr>
                  <td style={{ padding: '25px 20px', borderBottom: '2px solid #f1f5f9' }}>
                    <div style={{ fontWeight: '900', fontSize: '15px', color: '#1e293b' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Statement Balance Summary' : 'School Fees Installment'}</div>
                    <div style={{ fontSize: '11px', color: '#64748b', marginTop: '6px' }}>Fee Allocation for Termly Invoice - Academic {schoolConfig?.year || new Date().getFullYear()}</div>
                  </td>
                  <td style={{ padding: '25px 20px', borderBottom: '2px solid #f1f5f9', textAlign: 'right', fontWeight: '900', fontSize: '22px', color: '#1e293b' }}>{lastReceipt.amount.toLocaleString()}.00</td>
                </tr>
              </tbody>
            </table>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '80px' }}>
              <div style={{ width: '320px', padding: '25px', background: '#f0f9ff', borderRadius: '15px', border: '2px solid #1e3a8a', textAlign: 'right' }}>
                <p style={{ margin: '0', fontSize: '10px', fontWeight: '900', color: '#1e3a8a', textTransform: 'uppercase', letterSpacing: '1px' }}>Current Account Balance</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '32px', fontWeight: '900', color: '#1e3a8a' }}>KES {lastReceipt.balance.toLocaleString()}.00</p>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '100px', paddingTop: '40px', borderTop: '2px dashed #e2e8f0' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '2px solid #000', height: '60px', width: '250px', margin: '0 auto', marginBottom: '10px' }}></div>
                <p style={{ fontSize: '11px', fontWeight: '900', textTransform: 'uppercase', color: '#334155' }}>School Bursar Signature</p>
                <p style={{ fontSize: '9px', color: '#94a3b8' }}>Verified: {lastReceipt.servedBy}</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ border: '4px double rgba(30, 58, 138, 0.1)', borderRadius: '50%', width: '110px', height: '110px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto', marginBottom: '10px' }}>
                   <div style={{ fontSize: '14px', fontWeight: '900', color: 'rgba(30, 58, 138, 0.2)', transform: 'rotate(-20deg)', textAlign: 'center' }}>OFFICIALLY<br/>PAID</div>
                </div>
                <p style={{ fontSize: '11px', fontWeight: '900', textTransform: 'uppercase', color: '#334155' }}>Institution Stamp</p>
              </div>
            </div>

            <div style={{ marginTop: '80px', textAlign: 'center' }}>
              <p style={{ fontSize: '10px', color: '#94a3b8', fontWeight: 'bold' }}>This receipt is generated by ElimuSmart Cloud ERP. Document Integrity Hash: {Math.random().toString(36).substring(2, 15).toUpperCase()}</p>
            </div>
          </div>
        )}
      </div>

      {/* Main Finance UI */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Finance Center</h1>
          <p className="text-gray-500 font-medium">Automatic billing and student ledger management.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <select value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} className="p-3 bg-white border-2 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-500 transition-all shadow-sm">
            <option>All Classes</option>
            {KENYAN_CLASSES.map(cls => <option key={cls} value={cls}>{cls}</option>)}
