import React, { useState, useMemo } from 'react';
import { 
  AlertCircle, 
  Loader2, 
  Printer, 
  Download, 
  Target, 
  Banknote, 
  Forward, 
  CreditCard, 
  Save, 
  ShieldAlert, 
  Zap, 
  X, 
  CheckCircle2, 
  FileDown,
  User,
  Hash,
  Smartphone,
  Search,
  FileSpreadsheet,
  ShieldCheck,
  ReceiptText
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { Language, translations } from '../services/localizationService';
import { KENYAN_CLASSES, Student, ClassFee } from '../types';

interface Props {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  feeStructure: ClassFee[];
  setFeeStructure: React.Dispatch<React.SetStateAction<ClassFee[]>>;
  schoolLogo: string | null;
  schoolConfig: any;
}

interface TransactionReceipt {
  receiptNo: string;
  studentName: string;
  adm: string;
  class: string;
  amount: number;
  method: 'M-PESA' | 'BANK' | 'CASH';
  reference: string;
  date: string;
  balance: number;
  servedBy: string;
}

export const FinanceModule: React.FC<Props & { lang: Language }> = ({ lang, students, setStudents, feeStructure, setFeeStructure, schoolLogo, schoolConfig }) => {
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState<'payments' | 'class-summary' | 'fee-structure'>('class-summary');
  const [selectedClass, setSelectedClass] = useState<string>('All Classes');
  const [financeSearch, setFinanceSearch] = useState('');
  const [isPosting, setIsPosting] = useState(false);
  const [isApplyingFees, setIsApplyingFees] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<TransactionReceipt | null>(null);

  const [globalFeeValue, setGlobalFeeValue] = useState<string>('');
  const [paymentForm, setPaymentForm] = useState({ 
    adm: '', 
    amount: '', 
    method: 'M-PESA' as 'M-PESA' | 'BANK' | 'CASH', 
    reference: '' 
  });

  const filteredStudents = useMemo(() => {
    return (students || []).filter(s => {
      const matchesClass = selectedClass === 'All Classes' || s.class === selectedClass;
      const term = financeSearch.toLowerCase();
      const matchesSearch = 
        s.firstName.toLowerCase().includes(term) || 
        s.lastName.toLowerCase().includes(term) || 
        s.admissionNumber.toLowerCase().includes(term);
      return matchesClass && matchesSearch;
    });
  }, [students, selectedClass, financeSearch]);

  const financeStats = useMemo(() => {
    const targetStudents = filteredStudents || [];
    const totalExpected = targetStudents.reduce((sum, s) => sum + (s.totalFee || 0), 0);
    const totalCollected = targetStudents.reduce((sum, s) => sum + (s.paidFee || 0), 0);
    const totalOutstanding = targetStudents.reduce((sum, s) => sum + (s.feeBalance || 0), 0);
    const totalPrepaid = targetStudents.reduce((sum, s) => sum + (s.prepaidFee || 0), 0);
    return { expected: totalExpected, collected: totalCollected, outstanding: totalOutstanding, prepaid: totalPrepaid };
  }, [filteredStudents]);

  const handlePostPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentForm.adm || !paymentForm.amount) return;
    setIsPosting(true);

    // Simulating Secure API handshake
    await new Promise(r => setTimeout(r, 1000));

    const amountNum = parseFloat(paymentForm.amount);
    let updatedStudent: Student | undefined;

    setStudents(prev => prev.map(s => {
      if (s.admissionNumber === paymentForm.adm) {
        const newPaid = (s.paidFee || 0) + amountNum;
        let newBalance = (s.totalFee || 0) - newPaid;
        let newPrepaid = s.prepaidFee || 0;
        if (newBalance < 0) {
          newPrepaid += Math.abs(newBalance);
          newBalance = 0;
        }
        updatedStudent = { ...s, paidFee: newPaid, feeBalance: newBalance, prepaidFee: newPrepaid };
        return updatedStudent;
      }
      return s;
    }));

    if (updatedStudent) {
      const receipt: TransactionReceipt = {
        receiptNo: `RCP-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
        studentName: `${updatedStudent.firstName} ${updatedStudent.lastName}`,
        adm: updatedStudent.admissionNumber,
        class: updatedStudent.class,
        amount: amountNum,
        method: paymentForm.method,
        reference: paymentForm.reference || `TXN-${Date.now().toString().slice(-8)}`,
        date: new Date().toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' }),
        balance: updatedStudent.feeBalance,
        servedBy: 'Accounts Official'
      };
      setLastReceipt(receipt);
      setShowReceipt(true);
    }

    setIsPosting(false);
    setPaymentForm({ adm: '', amount: '', method: 'M-PESA', reference: '' });
  };

  const exportToPDF = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const opt = {
      margin: 0.5,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true, scrollY: 0 },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    const h2p = (window as any).html2pdf;
    if (typeof h2p === 'function') {
      h2p().set(opt).from(element).save();
    } else {
      window.print();
    }
  };

  const handleIndividualExportPDF = (student: Student) => {
    const mockStatement: TransactionReceipt = {
        receiptNo: "STMT-" + student.admissionNumber,
        studentName: `${student.firstName} ${student.lastName}`,
        adm: student.admissionNumber,
        class: student.class,
        amount: student.paidFee, 
        method: "CASH",
        reference: "HISTORICAL_LEDGER",
        date: new Date().toLocaleDateString(),
        balance: student.feeBalance,
        servedBy: "System Auditor"
    };
    setLastReceipt(mockStatement);
    setTimeout(() => {
        exportToPDF('receipt-print-template', `FeeStatement_${student.admissionNumber}.pdf`);
    }, 100);
  };

  const handleUpdateClassFee = (className: string, value: string) => {
    const amount = parseFloat(value) || 0;
    setFeeStructure(prev => prev.map(f => f.className === className ? { ...f, amount } : f));
  };

  const syncFeesToStudents = async () => {
    setIsApplyingFees(true);
    await new Promise(r => setTimeout(r, 1000));
    setStudents(prev => prev.map(student => {
      const structure = feeStructure.find(f => f.className === student.class);
      if (structure) {
        const newTotal = structure.amount;
        const paid = student.paidFee || 0;
        let newBalance = newTotal - paid;
        let newPrepaid = 0;
        if (newBalance < 0) {
          newPrepaid = Math.abs(newBalance);
          newBalance = 0;
        }
        return { ...student, totalFee: newTotal, feeBalance: newBalance, prepaidFee: newPrepaid };
      }
      return student;
    }));
    setIsApplyingFees(false);
    alert('Synchronization Complete.');
  };

  return (
    <div className="space-y-8 pb-20">
      {/* PROFESSIONAL RECEIPT TEMPLATE - HIDDEN BUT ACTIVE FOR CAPTURE */}
      <div id="receipt-print-template" className="offscreen-template" style={{ left: '-9999px', position: 'absolute' }}>
        {lastReceipt && (
          <div style={{ padding: '60px', background: 'white', color: 'black', width: '210mm', minHeight: '297mm', fontFamily: 'Arial, sans-serif' }}>
            <div style={{ borderBottom: '5px solid #1e3a8a', paddingBottom: '30px', marginBottom: '40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '30px' }}>
                {schoolLogo ? (
                  <img src={schoolLogo} style={{ width: '100px', height: '100px', borderRadius: '12px', objectFit: 'cover' }} />
                ) : (
                  <div style={{ width: '100px', height: '100px', borderRadius: '12px', background: '#1e3a8a', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 'bold', fontSize: '32px' }}>ES</div>
                )}
                <div>
                  <h1 style={{ margin: '0', fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a', textTransform: 'uppercase' }}>{schoolConfig?.schoolName || 'ElimuSmart Academy'}</h1>
                  <p style={{ margin: '5px 0', fontSize: '14px', fontStyle: 'italic', color: '#666' }}>{schoolConfig?.motto || 'Excellence in Knowledge and Character'}</p>
                  <p style={{ margin: '0', fontSize: '12px', fontWeight: 'bold' }}>Registration No: {schoolConfig?.registrationNo || 'N/A'}</p>
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '24px', fontWeight: 'bold', color: '#1e3a8a' }}>OFFICIAL RECEIPT</h2>
                <p style={{ margin: '5px 0', fontWeight: 'bold', color: '#dc2626' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Date: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '40px', marginBottom: '40px', background: '#f8fafc', padding: '30px', borderRadius: '15px' }}>
              <div>
                <p style={{ margin: '0', fontSize: '10px', textTransform: 'uppercase', color: '#64748b', fontWeight: 'bold' }}>Learner Profile</p>
                <p style={{ margin: '10px 0 0 0', fontSize: '20px', fontWeight: 'bold' }}>{lastReceipt.studentName}</p>
                <p style={{ margin: '5px 0', fontSize: '14px' }}>ADM: <span style={{ fontWeight: 'bold' }}>{lastReceipt.adm}</span> | {lastReceipt.class}</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <p style={{ margin: '0', fontSize: '10px', textTransform: 'uppercase', color: '#64748b', fontWeight: 'bold' }}>Payment Gateway</p>
                <p style={{ margin: '10px 0 0 0', fontSize: '20px', fontWeight: 'bold', color: '#10b981' }}>{lastReceipt.method}</p>
                <p style={{ margin: '5px 0', fontSize: '14px' }}>Ref Code: <span style={{ fontWeight: 'bold' }}>{lastReceipt.reference}</span></p>
              </div>
            </div>

            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '40px' }}>
              <thead>
                <tr style={{ background: '#1e3a8a', color: 'white' }}>
                  <th style={{ padding: '15px 20px', textAlign: 'left', textTransform: 'uppercase', fontSize: '12px' }}>Narration / Description</th>
                  <th style={{ padding: '15px 20px', textAlign: 'right', textTransform: 'uppercase', fontSize: '12px' }}>Amount (KES)</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ padding: '25px 20px', borderBottom: '1px solid #e2e8f0' }}>
                    <p style={{ margin: '0', fontWeight: 'bold', fontSize: '16px' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'Cumulative Tuition Fees' : 'Fee Installment Payment'}</p>
                    <p style={{ margin: '5px 0 0 0', fontSize: '12px', color: '#64748b' }}>Allocated to Termly Invoice for {schoolConfig?.year || new Date().getFullYear()}</p>
                  </td>
                  <td style={{ padding: '25px 20px', borderBottom: '1px solid #e2e8f0', textAlign: 'right', fontSize: '22px', fontWeight: 'bold' }}>{lastReceipt.amount.toLocaleString()}.00</td>
                </tr>
              </tbody>
            </table>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '60px' }}>
              <div style={{ width: '350px', padding: '20px', border: '2px solid #1e3a8a', borderRadius: '12px', textAlign: 'right' }}>
                <p style={{ margin: '0', fontSize: '11px', textTransform: 'uppercase', color: '#64748b', fontWeight: 'bold' }}>Current Outstanding Arrears</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a' }}>KES {lastReceipt.balance.toLocaleString()}.00</p>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '2px dashed #e2e8f0', paddingTop: '40px' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '200px', height: '60px', marginBottom: '10px' }}></div>
                <p style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase' }}>Bursar Office Signature</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ border: '4px double rgba(30, 58, 138, 0.2)', borderRadius: '50%', width: '100px', height: '100px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '10px' }}>
                   <div style={{ fontSize: '14px', fontWeight: 'bold', color: 'rgba(30, 58, 138, 0.2)', transform: 'rotate(-25deg)' }}>OFFICIAL<br/>STAMP</div>
                </div>
                <p style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase' }}>Institution Stamp</p>
              </div>
            </div>

            <div style={{ marginTop: '60px', textAlign: 'center', borderTop: '1px solid #f1f5f9', paddingTop: '10px' }}>
              <p style={{ fontSize: '10px', color: '#94a3b8' }}>Powered by ElimuSmart Cloud ERP. Verification Hash: {Math.random().toString(36).substr(2, 10).toUpperCase()}</p>
            </div>
          </div>
        )}
      </div>

      {/* Main UI Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">Finance Center</h1>
          <p className="text-gray-500 font-medium">Manage student ledgers and process payments.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
