        {lastReceipt && (
          <div style={{ padding: '60px', background: 'white', color: 'black', width: '210mm', minHeight: '297mm', fontFamily: 'Inter, Arial, sans-serif' }}>
            <div style={{ borderBottom: '5px solid #1e3a8a', paddingBottom: '30px', marginBottom: '40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '30px' }}>
                {schoolLogo ? (
                  <img src={schoolLogo} style={{ width: '100px', height: '100px', borderRadius: '12px', objectFit: 'cover' }} crossOrigin="anonymous" />
                ) : (
                  <div style={{ width: '100px', height: '100px', borderRadius: '12px', background: '#1e3a8a', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 'bold', fontSize: '32px' }}>ES</div>
                )}
                <div>
                  <h1 style={{ margin: '0', fontSize: '28px', fontWeight: 'bold', color: '#1e3a8a', textTransform: 'uppercase' }}>{schoolConfig?.schoolName || 'ElimuSmart Academy'}</h1>
                  <p style={{ margin: '5px 0', fontSize: '13px', fontStyle: 'italic', color: '#666' }}>{schoolConfig?.motto || 'Excellence in Knowledge and Character'}</p>
                  <p style={{ margin: '0', fontSize: '11px', fontWeight: 'bold' }}>Registration No: {schoolConfig?.registrationNo || 'N/A'}</p>
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <h2 style={{ margin: '0', fontSize: '20px', fontWeight: 'bold', color: '#1e3a8a' }}>OFFICIAL RECEIPT</h2>
                <p style={{ margin: '5px 0', fontWeight: 'bold', color: '#dc2626' }}>REF: {lastReceipt.receiptNo}</p>
                <p style={{ margin: '0', fontSize: '12px' }}>Date: {lastReceipt.date}</p>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '40px', marginBottom: '40px', background: '#f8fafc', padding: '30px', borderRadius: '15px', border: '1px solid #e2e8f0' }}>
              <div>
                <p style={{ margin: '0', fontSize: '10px', textTransform: 'uppercase', color: '#64748b', fontWeight: 'bold' }}>Student Information</p>
                <p style={{ margin: '10px 0 0 0', fontSize: '18px', fontWeight: 'bold' }}>{lastReceipt.studentName}</p>
                <p style={{ margin: '5px 0', fontSize: '14px' }}>ADM: <span style={{ fontWeight: 'bold' }}>{lastReceipt.adm}</span> | {lastReceipt.class}</p>
              </div>
              <div style={{ textAlign: 'right' }}>
                <p style={{ margin: '0', fontSize: '10px', textTransform: 'uppercase', color: '#64748b', fontWeight: 'bold' }}>Payment Gateway</p>
                <p style={{ margin: '10px 0 0 0', fontSize: '18px', fontWeight: 'bold', color: '#10b981' }}>{lastReceipt.method}</p>
                <p style={{ margin: '5px 0', fontSize: '14px' }}>Ref Code: <span style={{ fontWeight: 'bold' }}>{lastReceipt.reference}</span></p>
              </div>
