            <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '40px' }}>
              <thead>
                <tr style={{ background: '#1e3a8a', color: 'white' }}>
                  <th style={{ padding: '15px 20px', textAlign: 'left', textTransform: 'uppercase', fontSize: '11px' }}>Description of Service</th>
                  <th style={{ padding: '15px 20px', textAlign: 'right', textTransform: 'uppercase', fontSize: '11px' }}>Amount (KES)</th>
                </tr>
