              <tbody>
                <tr>
                  <td style={{ padding: '25px 20px', borderBottom: '1px solid #e2e8f0' }}>
                    <p style={{ margin: '0', fontWeight: 'bold', fontSize: '16px' }}>{lastReceipt.receiptNo.startsWith('STMT') ? 'School Fee Ledger Export' : 'Tuition Fee Payment'}</p>
                    <p style={{ margin: '5px 0 0 0', fontSize: '12px', color: '#64748b' }}>Allocated for Academic Year {schoolConfig?.year || new Date().getFullYear()}</p>
                  </td>
                  <td style={{ padding: '25px 20px', borderBottom: '1px solid #e2e8f0', textAlign: 'right', fontSize: '22px', fontWeight: 'bold' }}>{lastReceipt.amount.toLocaleString()}.00</td>
