            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '60px' }}>
              <div style={{ width: '350px', padding: '20px', border: '2px solid #1e3a8a', background: '#f0f9ff', borderRadius: '12px', textAlign: 'right' }}>
                <p style={{ margin: '0', fontSize: '10px', textTransform: 'uppercase', color: '#1e3a8a', fontWeight: 'bold' }}>Closing Outstanding Arrears</p>
                <p style={{ margin: '5px 0 0 0', fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a' }}>KES {lastReceipt.balance.toLocaleString()}.00</p>
              </div>
