            <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '2px dashed #e2e8f0', paddingTop: '40px' }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ borderBottom: '1px solid black', width: '200px', height: '60px', marginBottom: '10px' }}></div>
                <p style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase' }}>Bursar Office Signature</p>
                <p style={{ fontSize: '9px', color: '#94a3b8' }}>ID: {lastReceipt.servedBy}</p>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ border: '4px double rgba(30, 58, 138, 0.15)', borderRadius: '50%', width: '100px', height: '100px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '10px' }}>
                   <div style={{ fontSize: '14px', fontWeight: 'bold', color: 'rgba(30, 58, 138, 0.2)', transform: 'rotate(-20deg)' }}>OFFICIAL<br/>STAMP</div>
                </div>
                <p style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase' }}>Institution Stamp</p>
              </div>
            </div>

            <div style={{ marginTop: '80px', textAlign: 'center', borderTop: '1px solid #f1f5f9', paddingTop: '10px' }}>
              <p style={{ fontSize: '9px', color: '#94a3b8' }}>Generated by ElimuSmart System Portal. Digital verification code: {Math.random().toString(36).substring(2, 10).toUpperCase()}</p>
