} from 'lucide-react';
import { TimetableEntry, KENYAN_CLASSES, SCHOOL_STREAMS } from '../types';
import { schoolService } from '../services/schoolService';
import { Language, translations } from '../services/localizationService';

const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'];
const TIME_SLOTS = ['08:00', '08:40', '09:20', '10:00', '10:30', '11:10', '11:50', '12:30', '13:30', '14:10', '14:50'];

export const TimetableModule: React.FC<{ lang: Language }> = ({ lang }) => {
  const t = translations[lang];
  const [entries, setEntries] = useState<TimetableEntry[]>([]);
  const [selectedClass, setSelectedClass] = useState('Grade 7');
  const [selectedStream, setSelectedStream] = useState('Eagle');
  const [selectedDay, setSelectedDay] = useState(DAYS[new Date().getDay() - 1] || 'Monday');
  const [isLoading, setIsLoading] = useState(true);

  // Editing State
  const [editingSlot, setEditingSlot] = useState<{ day: string, time: string } | null>(null);
  const [formData, setFormData] = useState<Partial<TimetableEntry>>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Load data with persistence
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);

    const saved = localStorage.getItem(`tt_${selectedClass}_${selectedStream}`);
    if (saved) {
      setEntries(JSON.parse(saved));
      setIsLoading(false);
    } else {
      setIsLoading(true);
      schoolService.getTimetable(`${selectedClass} ${selectedStream}`)
        .then(data => {
          setEntries(data);
          setIsLoading(false);
        });
    }

    return () => clearInterval(timer);
  }, [selectedClass, selectedStream]);

  // Save on change
  useEffect(() => {
    if (entries.length > 0) {
      localStorage.setItem(`tt_${selectedClass}_${selectedStream}`, JSON.stringify(entries));
    }
  }, [entries, selectedClass, selectedStream]);

  const getEntry = (day: string, time: string) => {
    return entries.find(e => e.day === day && e.time === time);
  };

  const isCurrentSlot = (day: string, time: string) => {
    const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const currentDayName = dayNames[currentTime.getDay()];
    if (currentDayName !== day) return false;

    const [h, m] = time.split(':').map(Number);
    const slotStart = new Date(currentTime);
    slotStart.setHours(h, m, 0);

    const slotEnd = new Date(slotStart);
    slotEnd.setMinutes(slotEnd.getMinutes() + 40);

    return currentTime >= slotStart && currentTime < slotEnd;
  };

  const getSubjectIcon = (subject: string) => {
    const s = subject.toLowerCase();
    if (s.includes('math')) return <Calculator size={14} />;
    if (s.includes('sci') || s.includes('phys') || s.includes('chem')) return <FlaskConical size={14} />;
    if (s.includes('eng') || s.includes('swa') || s.includes('lang')) return <Languages size={14} />;
    if (s.includes('art') || s.includes('creat')) return <Palette size={14} />;
    if (s.includes('soc') || s.includes('hist')) return <Globe2 size={14} />;
    return <BookOpen size={14} />;
  };

  const getCategoryStyles = (category: string) => {
    switch (category) {
      case 'STEM': return 'bg-blue-50 text-blue-700 border-blue-200';
      case 'Languages': return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case 'Arts': return 'bg-purple-50 text-purple-700 border-purple-200';
      case 'Technical': return 'bg-amber-50 text-amber-700 border-amber-200';
      case 'Social': return 'bg-rose-50 text-rose-700 border-rose-200';
      case 'Break': return 'bg-gray-50 text-gray-500 border-gray-200 border-dashed';
      default: return 'bg-gray-50 text-gray-600 border-gray-200';
