  const handleEditClick = (day: string, time: string) => {
    const existing = getEntry(day, time);
    setFormData(existing || { day, time, subject: '', teacher: '', category: 'STEM' });
    setEditingSlot({ day, time });
  };

  const handleSaveSlot = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.subject) return;

    const newEntry: TimetableEntry = {
      id: formData.id || `${formData.day}-${formData.time}`,
      day: formData.day!,
      time: formData.time!,
      subject: formData.subject!,
      teacher: formData.teacher || 'To Be Assigned',
      category: formData.category as any || 'STEM',
      room: formData.room || 'General Room'
    };

    setEntries(prev => {
      const filtered = prev.filter(e => !(e.day === formData.day && e.time === formData.time));
      return [...filtered, newEntry];
    });
    setEditingSlot(null);
  };

  const clearSlot = () => {
    if (editingSlot) {
      setEntries(prev => prev.filter(e => !(e.day === editingSlot.day && e.time === editingSlot.time)));
      setEditingSlot(null);
    }
  };

