             <div className="w-[1px] bg-gray-200 mx-2"></div>
             <select 
               value={selectedStream} 
               onChange={e => setSelectedStream(e.target.value)}
               className="bg-transparent px-4 py-2 text-[10px] font-black uppercase tracking-widest border-none outline-none text-gray-600 cursor-pointer"
             >
               {SCHOOL_STREAMS.map(s => <option key={s} value={s}>{s}</option>)}
             </select>
          </div>

          <div className="flex gap-2">
            <button 
              onClick={resetTimetable}
              className="p-3 bg-white border-2 border-gray-100 rounded-2xl text-gray-400 hover:text-blue-600 hover:border-blue-100 transition-all shadow-sm group"
              title="Reset Template"
            >
              <RotateCcw size={18} className="group-active:rotate-[-180deg] transition-transform duration-500" />
            </button>
            <button 
              onClick={() => window.print()}
              className="flex items-center gap-3 bg-gray-900 text-white px-6 py-3 rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] shadow-xl hover:bg-black transition-all active:scale-95"
            >
              <Printer size={16} /> PDF Export
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Day Navigation */}
      <div className="xl:hidden flex gap-2 overflow-x-auto pb-4 no-print snap-x">
        {DAYS.map(day => (
          <button
            key={day}
            onClick={() => setSelectedDay(day)}
            className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all snap-start ${
              selectedDay === day 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-100' 
                : 'bg-white text-gray-400 border border-gray-100'
            }`}
          >
            {day}
          </button>
        ))}
      </div>

      {/* Main Grid View */}
      <div className="bg-white rounded-[40px] border-2 border-gray-50 shadow-2xl shadow-gray-200/50 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b-2 border-gray-100">
                <th className="p-6 border-r-2 border-gray-100 w-32 text-[10px] font-black uppercase text-gray-400 tracking-[0.3em] text-center">Period</th>
                {DAYS.map(day => (
                  <th key={day} className={`p-6 border-r-2 border-gray-100 min-w-[200px] text-[10px] font-black uppercase tracking-[0.3em] text-center transition-all xl:table-cell ${selectedDay === day ? 'table-cell bg-blue-50/30 text-blue-900' : 'hidden'}`}>
                    {day}
                  </th>
