                        className={`p-3 border-r-2 border-gray-100 transition-all cursor-pointer xl:table-cell ${selectedDay === day ? 'table-cell' : 'hidden'} ${isBreak ? 'bg-gray-50/50' : 'hover:scale-[1.02] active:scale-95'}`}
                      >
                        {entry ? (
                          <div className={`h-full min-h-[90px] p-4 rounded-3xl border-2 transition-all flex flex-col justify-between relative overflow-hidden group/card ${getCategoryStyles(entry.category)} ${isLive ? 'ring-4 ring-blue-500/20 shadow-2xl animate-pulse border-blue-400' : 'shadow-sm'}`}>
                            {isLive && (
                              <div className="absolute top-2 right-2 flex items-center gap-1.5 px-2 py-0.5 bg-blue-600 text-white rounded-full text-[8px] font-black tracking-widest animate-bounce">
                                <Zap size={8} className="fill-current" /> LIVE
                              </div>
