                            <div>
                              <div className="flex items-center gap-2 mb-1">
                                <span className="opacity-40">{getSubjectIcon(entry.subject)}</span>
                                <h4 className="font-black text-[12px] uppercase leading-tight tracking-tight">{entry.subject}</h4>
                              </div>
                              {!isBreak && (
                                <div className="flex items-center gap-2 mt-1 opacity-60">
                                   <User size={10} />
                                   <span className="text-[9px] font-bold uppercase truncate">{entry.teacher}</span>
                                </div>
                              )}
