                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Assigned Educator</label>
                       <input 
                         placeholder="e.g. Tr. Maina" 
                         value={formData.teacher} 
                         onChange={e => setFormData({...formData, teacher: e.target.value})}
