                 <div className="flex gap-4 pt-4">
                    <button type="button" onClick={clearSlot} className="flex-1 py-5 bg-red-50 text-red-600 font-black uppercase tracking-widest rounded-3xl hover:bg-red-100 transition-all flex items-center justify-center gap-3">
                       <Trash2 size={20} /> Clear Slot
                    </button>
                    <button type="submit" className="flex-1 py-5 bg-blue-600 text-white font-black uppercase tracking-widest rounded-3xl hover:bg-blue-700 transition-all shadow-2xl shadow-blue-100 flex items-center justify-center gap-3 active:scale-95">
                       <Save size={20} /> Commit Change
                    </button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

